/** Meanings for the two long homas (Chandika and Pavamana); the other homas are in homa.ts. */
export const taHoma2: MeaningPack = {
  lang: 'ta',
  texts: {
    'chandika-homa': {
      summary: "சண்டீ ஹோமம் (துர்கா ஸப்தசதீ ஹோமம்), செய்யும் வரிசையில்: ஹோமத்தின் இயல்பு, ஸங்கல்பம் (மாத்வ, ஸ்மார்த்த வடிவங்கள்), கலசமும் தேவீ ஆவாஹனமும், ஆஜ்யபாகம் வரையிலான பொது பூர்வாங்கம், தேவீ கவசம்–அர்களா–கீலகம்–ராத்ரி ஸூக்த பாராயணம், நவார்ண மந்திரம், பின் தேவீ மாஹாத்ம்யத்தின் பதின்மூன்று அத்தியாயங்களின் 700 மந்திரங்கள் — ஒவ்வொன்றும் ஹோமம் செய்வது போல ஸ்வாஹாவுடன், மூன்று சரித்திரங்களின் விநியோகம், தியானத்துடன்; தேவீ ஸூக்தம், உத்தராங்கம் (ஸ்விஷ்டக்ருத், ப்ராயச்சித்தம், பூர்ணாஹுதி), பலிதானம், உத்தர பூஜை, க்ஷமாபணம், ஸமர்ப்பணம்.",
      verses: {
        '0.0': "பலிதானம், பூஜை, அக்னிகார்யம் (ஹோமம்), மகோத்ஸவம் ஆகிய சமயங்களில் என் இந்தச் சரித்திரத்தை முழுமையாக ஓதவும் கேட்கவும் வேண்டும். (தேவீ மாஹாத்மியம் 12.10)",
        '0.1': "அறிந்தோ அறியாமலோ செய்த பலியையும் பூஜையையும், அவ்வாறே ஹோமத்தையும் நான் அன்புடன் ஏற்பேன். (தேவீ மாஹாத்மியம் 12.11)",
        '1.0': "யஜ்ஞபுருஷனின் அந்தர்யாமியான, பாரதீரமண முக்யப்ராணாந்தர்கதரான ஹரிணீபதி ஸ்ரீபரசுராமரின் தூண்டுதலால், அவர் மகிழ்ச்சிக்காகவும் ஸ்ரீதுர்கையின் மகிழ்ச்சிக்காகவும், விரும்பிய பலன் கிடைப்பதற்காக, ஸப்தசதியின் ஒவ்வொரு ச்லோகத்தாலும் எள்–நெய் கலந்த பாயஸத்தை ஹோமம் செய்யும் சண்டிகா ஹோமம் என்னும் கர்மத்தைச் செய்வேன்; அதன் அங்கமாகக் கலசஸ்தாபனம், ஸ்தண்டில ஸம்ஸ்காரம், அக்னிப்ரதிஷ்டை செய்வேன்.",
        '2.0': "என் எல்லாப் பாவங்களும் நீங்குவதன் மூலம் பரமேஸ்வரனின் மகிழ்ச்சிக்காக, மஹாகாளீ–மஹாலக்ஷ்மீ–மஹாஸரஸ்வதீ ஸ்வரூபிணியான ஸ்ரீசண்டிகையின் அருளுக்காக, விரும்பிய பலன் கிடைப்பதற்காக, ஸப்தசதியின் ஒவ்வொரு ச்லோகத்தாலும் எள்–நெய் கலந்த பாயஸத்தை ஹோமம் செய்யும் சண்டிகா ஹோமத்தைச் செய்வேன்; அதன் அங்கமாகக் கலசஸ்தாபனம், ஸ்தண்டில உல்லேகனம், அக்னிப்ரதிஷ்டை செய்வேன்.",
        '3.0': "ஓ வருணா, என் இந்த அழைப்பைக் கேள், இன்று எங்களுக்கு அருள்செய்; உன் பாதுகாப்பை விரும்பி உன்னை அழைக்கிறேன். (ரிக்வேதம் 1.25.19; கலசத்தில் வருண ஆவாஹனம்)",
        '3.1': "மஹாகாளீ–மஹாலக்ஷ்மீ–மஹாஸரஸ்வதீ ஸ்வரூபிணியான ஸ்ரீசண்டிகையைத் தியானிக்கிறேன்; கலசத்தில் ஆவாஹனம் செய்கிறேன்.",
        '3.2': "ஓம். ஜயந்தீ, மங்களா, காளீ, பத்ரகாளீ, கபாலினீ, துர்கா, க்ஷமா, சிவா, தாத்ரீ, ஸ்வாஹா, ஸ்வதா: உனக்கு நமஸ்காரம்.",
        '3.3': "தியானிக்கிறேன், ஆவாஹனம் செய்கிறேன்; ஆஸனம், பாத்யம், அர்க்யம், ஆசமனீயம், ஸ்நானம், வஸ்திரம், சந்தனம், புஷ்பங்கள், தூபம், தீபம், நைவேத்யம், தாம்பூலம் ஸமர்ப்பிக்கிறேன். (கலச தேவதையின் சுருக்கமான பூஜை.)",
        '3.4': "மங்கலங்களுக்கெல்லாம் மங்கலமானவளே, எல்லா நோக்கங்களையும் நிறைவேற்றும் சிவையே, அனைவருக்கும் அடைக்கலமே, முக்கண்ணுடைய கௌரியே: நாராயணியே, உனக்கு நமஸ்காரம்.",
        '4.0': "ஆஜ்யபாகம் வரையிலான பூர்வாங்கத்தை (“ஹோமவிதி — பூர்வாங்க உத்தராங்கம்” பாடத்திலிருந்து) செய்து…",
        '5.0': "விநியோகம்: இந்த ஸ்ரீசண்டீ கவசத்திற்கு ரிஷி பிரம்மா, சந்தஸ் அனுஷ்டுப், தேவதை சாமுண்டா; அங்கந்யாஸத்தில் சொல்லப்பட்ட மாத்ருகைகள் பீஜம், திக்பந்த தேவதைகள் தத்துவம். ஸ்ரீஜகதம்பாவின் ப்ரீதிக்காக ஸப்தஶதீ பாராயணத்தின் அங்கமாக இது ஜபிக்கப்படுகிறது.",
        '5.1': "ஓம், சண்டிகைக்கு நமஸ்காரம்.",
        '5.2': "மார்க்கண்டேயர் கூறினார்:",
        '5.3': "பிதாமஹரே, உலகில் மிக ரகசியமானதும், மனிதர்களுக்கு எல்லாவிதப் பாதுகாப்பும் அளிப்பதும், இதுவரை யாருக்கும் சொல்லப்படாததுமான ஒன்றை எனக்குச் சொல்லுங்கள்.",
        '5.4': "பிரம்மா கூறினார்:",
        '5.5': "விப்ரரே, எல்லா உயிர்களுக்கும் நன்மை செய்யும் மிக ரகசியமான ஒன்று உண்டு: அது தேவியின் புண்ணியமான கவசம். மகாமுனிவரே, அதைக் கேளுங்கள்.",
        '5.6': "முதலாமவள் ஶைலபுத்ரீ, இரண்டாமவள் பிரம்மசாரிணீ, மூன்றாமவள் சந்திரகண்டா, நான்காமவள் கூஷ்மாண்டா;",
        '5.7': "ஐந்தாமவள் ஸ்கந்தமாதா, ஆறாமவள் காத்யாயனீ, ஏழாமவள் காலராத்ரீ, எட்டாமவள் மகாகௌரீ;",
        '5.8': "ஒன்பதாமவள் ஸித்திதாத்ரீ. இவர்கள் நவதுர்கைகள் எனப் போற்றப்படுகின்றனர்; இந்தப் பெயர்களை மகாத்மாவான பிரம்மாவே கூறியுள்ளார்.",
        '5.9': "நெருப்பில் எரிந்துகொண்டிருப்பவன், போரில் பகைவர் நடுவே சிக்கியவன், கடினமான அணுக முடியாத இடங்களில் இருப்பவர்கள் — பயத்தால் வாடி அவளைச் சரணடைந்தவர்கள் —",
        '5.10': "அவர்களுக்குப் போரின் ஆபத்தில் எந்தத் தீங்கும் நேராது. அப்படிப்பட்டவனுக்கு நான் எந்த ஆபத்தையும் காணவில்லை; துயரமோ துன்பமோ பயமோ இல்லை.",
        '5.11': "பக்தியுடன் அவளை நினைப்பவர்கள் நிச்சயமாக வளம் பெறுவர். தேவர்களின் தலைவியே, உன்னை நினைப்பவர்களை நீ காக்கிறாய்; இதில் ஐயமில்லை.",
        '5.12': "சாமுண்டா பிணத்தின் மேல் அமர்ந்தவள், வாராஹீ எருமையின் மேல், ஐந்த்ரீ யானையின் மேல், வைஷ்ணவீ கருடன் மேல் அமர்ந்தவள்;",
        '5.13': "மாஹேஶ்வரீ காளையின் மேல், கௌமாரீ மயிலை வாகனமாகக் கொண்டவள்; ஹரியின் அன்புக்குரிய லக்ஷ்மீ தேவி தாமரையில் அமர்ந்து கையில் தாமரை ஏந்தியவள்;",
        '5.14': "வெண்மையான உருவம் கொண்ட ஈஶ்வரீ தேவி காளையை வாகனமாகக் கொண்டவள்; பிராஹ்மீ அன்னத்தின் மேல் அமர்ந்து எல்லா ஆபரணங்களாலும் அலங்கரிக்கப்பட்டவள்.",
        '5.15': "இந்த மாத்ருகைகள் அனைவரும் எல்லா யோக சக்திகளும் உடையவர்கள், பலவித ஆபரணங்களால் ஒளிர்பவர்கள், பலவித ரத்தினங்களால் அலங்கரிக்கப்பட்டவர்கள்.",
        '5.16': "அந்தத் தேவியர் கோபம் நிறைந்து தேர்களில் ஏறியவர்களாகக் காணப்படுகின்றனர்; சங்கு, சக்கரம், கதை, சக்தி, கலப்பை, உலக்கை ஆகிய ஆயுதங்களையும்,",
        '5.17': "கேடயம், தோமரம், கோடரி, பாசம், ஈட்டி, திரிசூலம், சிறந்த ஆயுதமான ஶார்ங்க வில் ஆகியவற்றையும் ஏந்தியுள்ளனர்.",
        '5.18': "அசுரர்களின் உடல்களை அழிக்கவும், பக்தர்களுக்கு அபயம் அளிக்கவும், தேவர்களின் நன்மைக்காகவும் அவர்கள் இவ்வாறு ஆயுதங்களைத் தாங்குகின்றனர்.",
        '5.19': "மகாரௌத்ரியே, மிகக் கொடிய வீரம் உடையவளே, மகாபலம் உடையவளே, மிகுந்த உற்சாகம் உடையவளே, பெரும் பயத்தை அழிப்பவளே, உனக்கு நமஸ்காரம்.",
        '5.20': "தேவியே, காண்பதற்கு அரியவளே, பகைவரின் பயத்தைப் பெருக்குபவளே, என்னைக் காப்பாற்று. கிழக்கில் ஐந்த்ரீயும், தென்கிழக்கில் அக்னி தேவதையும் என்னைக் காக்கட்டும்;",
        '5.21': "தெற்கில் வாராஹீயும், தென்மேற்கில் கட்கதாரிணீயும் காக்கட்டும்; மேற்கில் வாருணீயும், வடமேற்கில் ம்ருகவாஹினீயும் காக்கட்டும்;",
        '5.22': "வடக்கில் கௌமாரீயும், வடகிழக்கில் ஶூலதாரிணீயும் காக்கட்டும்; மேலே பிரம்மாணீயும், கீழே வைஷ்ணவீயும் என்னைக் காக்கட்டும்.",
        '5.23': "இவ்வாறு பிணத்தை வாகனமாகக் கொண்ட சாமுண்டா பத்துத் திசைகளையும் காக்கட்டும். முன்னே ஜயாவும், பின்னே விஜயாவும் என்னைக் காக்கட்டும்;",
        '5.24': "இடப்பக்கம் அஜிதாவும், வலப்பக்கம் அபராஜிதாவும். உத்யோதினீ குடுமியைக் காக்கட்டும்; உச்சந்தலையில் உமா நிலைகொண்டு காக்கட்டும்.",
        '5.25': "நெற்றியை மாலாதரீயும், புருவங்களை யஶஸ்வினீயும், புருவ மத்தியை த்ரிநேத்ராவும், நாசித் துவாரங்களை யமகண்டாவும் காக்கட்டும்;",
        '5.26': "கண்களின் நடுவே ஶங்கினீயும், காதுகளை த்வாரவாஸினீயும்; கன்னங்களைக் காளிகாவும், காதுகளின் அடியை ஶாங்கரீயும் காக்கட்டும்;",
        '5.27': "மூக்கில் ஸுகந்தாவும், மேல் உதட்டில் சர்ச்சிகாவும், கீழ் உதட்டில் அம்ருதகலாவும், நாவில் ஸரஸ்வதியும் காக்கட்டும்;",
        '5.28': "பற்களைக் கௌமாரீயும், கழுத்துப் பகுதியைச் சண்டிகாவும், உள்நாக்கைச் சித்ரகண்டாவும், அண்ணத்தை மகாமாயாவும் காக்கட்டும்;",
        '5.29': "முகவாயைக் காமாக்ஷீயும், என் வாக்கை ஸர்வமங்களாவும், கழுத்தைப் பத்ரகாளீயும், முதுகுத்தண்டைத் தனுர்தரீயும் காக்கட்டும்;",
        '5.30': "வெளிக்கழுத்தை நீலக்ரீவாவும், மூச்சுக்குழாயை நலகூபரீயும், தோள்களைக் கட்கினீயும், என் கைகளை வஜ்ரதாரிணீயும் காக்கட்டும்;",
        '5.31': "கைகளைத் தண்டினீயும், விரல்களை அம்பிகாவும், நகங்களை ஶூலேஶ்வரீயும், வயிற்றின் பக்கங்களைக் குலேஶ்வரீயும் காக்கட்டும்;",
        '5.32': "மார்பகங்களை மகாதேவீயும், மனத்தை ஶோகவிநாஶினீயும், இதயத்தில் லலிதா தேவியும், வயிற்றில் ஶூலதாரிணீயும் காக்கட்டும்;",
        '5.33': "தொப்புளைக் காமினீயும், மறைவிடத்தை குஹ்யேஶ்வரீயும், பிறப்புறுப்பைப் பூதனா, காமிகா ஆகியோரும், குதத்தை மஹிஷவாஹினீயும் காக்கட்டும்;",
        '5.34': "இடுப்பைப் பகவதியும், முழங்கால்களை விந்த்யவாஸினீயும், எல்லா விருப்பங்களையும் அருளும் மகாபலா கணுக்கால்களுக்கு மேலுள்ள கால்களையும் காக்கட்டும்;",
        '5.35': "கணுக்கால்களை நாரஸிம்ஹீயும், பாதங்களின் மேற்புறத்தைத் தைஜஸீயும், கால்விரல்களை ஸ்ரீதேவியும், உள்ளங்கால்களைத் தலவாஸினீயும் காக்கட்டும்.",
        '5.36': "நகங்களைத் தம்ஷ்ட்ராகராலீயும், கேசங்களை ஊர்த்வகேஶினீயும், மயிர்க்கால்களைக் கௌபேரீயும், தோலை வாகீஶ்வரீயும் காக்கட்டும்.",
        '5.37': "ரத்தம், மஜ்ஜை, வஸை, மாமிசம், எலும்பு, மேதஸ் ஆகியவற்றைப் பார்வதியும், குடல்களைக் காலராத்ரீயும், பித்தத்தை முகுடேஶ்வரீயும் காக்கட்டும்.",
        '5.38': "பத்மகோஶத்தைப் பத்மாவதியும், கபத்தைச் சூடாமணியும், நகங்களின் ஒளியை ஜ்வாலாமுகீயும், எல்லா மூட்டுகளையும் அபேத்யாவும் காக்கட்டும்.",
        '5.39': "என் சுக்கிலத்தைப் பிரம்மாணீயும், நிழலைச் சத்ரேஶ்வரீயும், அகங்காரம், மனம், புத்தி ஆகியவற்றைத் தர்மதாரிணீயும் காக்கட்டும்.",
        '5.40': "பிராணன், அபானன், வ்யானன், உதானன், ஸமானன் ஆகிய வாயுக்களை வஜ்ரஹஸ்தாவும், என் உயிரைக் கல்யாணஶோபனாவும் காக்கட்டும்.",
        '5.41': "சுவை, உருவம், மணம், ஒலி, ஸ்பர்ஶம் ஆகியவற்றில் யோகினீயும், ஸத்வம், ரஜஸ், தமஸ் ஆகியவற்றை நாராயணீயும் எப்போதும் காக்கட்டும்.",
        '5.42': "ஆயுளை வாராஹீயும், தர்மத்தை வைஷ்ணவீயும், புகழ், கீர்த்தி, செல்வச் சிறப்பு, பொருள், கல்வி ஆகியவற்றைச் சக்ரிணீயும் காக்கட்டும்.",
        '5.43': "என் கோத்திரத்தை இந்த்ராணீ காக்கட்டும்; சண்டிகையே, என் பசுக்களைக் காப்பாற்று. புதல்வர்களை மகாலக்ஷ்மியும், மனைவியைப் பைரவீயும் காக்கட்டும்.",
        '5.44': "என் வழியை ஸுபதாவும், பாதையைக் க்ஷேமகரீயும், அரசவாயிலில் மகாலக்ஷ்மியும், எங்கும் நிலைத்திருக்கும் விஜயாவும் எல்லாப் பக்கங்களிலும் காக்கட்டும்.",
        '5.45': "பாதுகாப்பின்றி, கவசத்தில் விடுபட்ட இடம் எதுவோ அவை அனைத்தையும், பாவங்களை அழிக்கும் ஜயந்தீ தேவியே, எனக்காகக் காப்பாற்று.",
        '5.46': "தனக்கு நன்மையை விரும்புபவன் இக்கவசமின்றி ஓர் அடியும் எடுத்துவைக்கக் கூடாது. கவசத்தால் எப்போதும் மூடப்பட்டவன் எங்கெங்கு செல்கிறானோ,",
        '5.47': "அங்கங்கே அவனுக்குப் பொருள் லாபமும் எல்லா விருப்பங்களையும் நிறைவேற்றும் வெற்றியும் கிடைக்கும். எந்த எந்த விருப்பத்தை நினைக்கிறானோ அதை நிச்சயம் அடைவான்; பூமியில் ஒப்பற்ற பரம ஐஶ்வர்யத்தைப் பெறுவான்.",
        '5.48': "கவசத்தால் மூடப்பட்ட மனிதன் அச்சமற்றவனாகிறான், போர்களில் தோல்வியற்றவனாகிறான், மூவுலகிலும் போற்றத்தக்கவனாகிறான்.",
        '5.49': "தேவியின் இந்தக் கவசம் தேவர்களுக்கும் அரிதானது. இதைத் தூய்மையுடனும் ஶ்ரத்தையுடனும் தினமும் மூன்று ஸந்தியா வேளைகளிலும் பாராயணம் செய்பவன் —",
        '5.50': "அவனுக்குத் தெய்வீகக் கலை உண்டாகும், மூவுலகிலும் வெல்லப்படாதவனாவான்; அகால மரணமின்றி நூறு ஆண்டுகளுக்கும் மேலாக வாழ்வான்.",
        '5.51': "சிலந்தி விஷம், கொப்புளங்கள் முதலான எல்லா நோய்களும் அழியும்; தாவரம், ஜங்கமம் (உயிரினம்), செயற்கை ஆகியவற்றிலிருந்து வரும் எந்த விஷமும் —",
        '5.52': "பூமியிலுள்ள எல்லா அபிசாரங்களும் (தீய மந்திர ப்ரயோகங்கள்), மந்திர யந்திரங்களும்; நிலத்தில், வானில், நீரில் திரிபவர்களும், பிறர் ஏவலால் அனுப்பப்பட்டவர்களும் —",
        '5.53': "ஸஹஜா, குலஜா, மாலா எனப்படும் பீடைகளும், டாகினீ, ஶாகினீகளும், வானில் திரியும் கொடிய வலிமைமிக்க டாகினீகளும் —",
        '5.54': "கிரகங்கள், பூதங்கள், பிஶாசங்கள், யக்ஷர்கள், கந்தர்வர்கள், ராக்ஷஸர்கள், பிரம்மராக்ஷஸர்கள், வேதாளங்கள், கூஷ்மாண்டர்கள், பைரவர்கள் முதலானோர் —",
        '5.55': "இதயத்தில் இக்கவசம் நிலைபெற்றவனைக் கண்ட மாத்திரத்தில் இவை அனைத்தும் அழியும். அரசனிடமிருந்து அவனுக்கு மதிப்பும் உயர்வும் கிடைக்கும்; இது ஒளியைப் பெரிதும் வளர்க்கும்.",
        '5.56': "அவனும் புகழால் வளர்கிறான்; பூமி அவனது கீர்த்தியால் அலங்கரிக்கப்படுகிறது. முதலில் கவசத்தைப் பாராயணம் செய்து பின்னர் ஸப்தஶதீ சண்டீயை ஜபிக்க வேண்டும்.",
        '5.57': "மலைகள், வனங்கள், காடுகளுடன் பூமி எவ்வளவு காலம் நிலைத்திருக்குமோ அவ்வளவு காலம் அவனது புத்ர பௌத்ர ஸந்ததி பூமியில் நிலைத்திருக்கும்.",
        '5.58': "உடலின் முடிவில், மகாமாயையின் அருளால், அம்மனிதன் தேவர்களுக்கும் அரிதான நித்தியமான பரம ஸ்தானத்தை அடைகிறான்.",
        '5.59': "அவன் பரம ரூபத்தைப் பெற்று ஶிவனுடன் ஆனந்திக்கிறான்.",
        '5.60': "இவ்வாறு ஸ்ரீவராஹ புராணத்தில் ஹரி, ஹரன், பிரம்மா இயற்றிய தேவீ கவசம் நிறைவுற்றது.",
        '6.0': "விநியோகம்: இந்த அர்கலா ஸ்தோத்திர மந்திரத்திற்கு விஷ்ணு ரிஷி, அனுஷ்டுப் சந்தஸ், ஸ்ரீ மஹாலக்ஷ்மீ தேவதை; உலகன்னையான ஸ்ரீ ஜகதம்பாவின் ப்ரீதிக்காக ஸப்தசதீ பாராயணத்தின் அங்கமாக இதன் ஜபம்.",
        '6.1': "ஓம், சண்டிகைக்கு நமஸ்காரம்.",
        '6.2': "மார்க்கண்டேயர் கூறினார்:",
        '6.3': "ஓம். ஜயந்தீ, மங்களா, காளீ, பத்ரகாளீ, கபாலினீ, துர்கா, க்ஷமா, சிவா, தாத்ரீ, ஸ்வாஹா, ஸ்வதா: உனக்கு நமஸ்காரம்.",
        '6.4': "சாமுண்டா தேவியே, உனக்கு ஜயம்; உயிர்களின் துயரைப் போக்குபவளே, உனக்கு ஜயம்; எங்கும் நிறைந்த தேவியே, உனக்கு ஜயம். காளராத்ரியே, உனக்கு நமஸ்காரம்.",
        '6.5': "மது கைடபரை விரட்டிப் பிரம்மாவுக்கு வரம் அருளியவளே, உனக்கு நமஸ்காரம். அழகு அருள், வெற்றி அருள், புகழ் அருள்; என் பகைவரை அழி.",
        '6.6': "மகிஷாசுரனை அழித்தவளே, பக்தர்களுக்கு இன்பம் தருபவளே, உனக்கு நமஸ்காரம். அழகு அருள், வெற்றி அருள், புகழ் அருள்; என் பகைவரை அழி.",
        '6.7': "ரக்தபீஜனை வதைத்த தேவியே, சண்ட முண்டரை அழித்தவளே: அழகு அருள், வெற்றி அருள், புகழ் அருள்; என் பகைவரை அழி.",
        '6.8': "சும்பன், நிசும்பன், தூம்ராக்ஷன் ஆகியோரை நசுக்கியவளே: அழகு அருள், வெற்றி அருள், புகழ் அருள்; என் பகைவரை அழி.",
        '6.9': "அனைவரும் வணங்கும் திருவடிகளுடைய தேவியே, எல்லா நற்பேறும் அருள்பவளே: அழகு அருள், வெற்றி அருள், புகழ் அருள்; என் பகைவரை அழி.",
        '6.10': "சிந்தைக்கெட்டா வடிவும் செயல்களும் உடையவளே, எல்லாப் பகைவரையும் அழிப்பவளே: அழகு அருள், வெற்றி அருள், புகழ் அருள்; என் பகைவரை அழி.",
        '6.11': "பாவம் போக்கும் சண்டிகையே, பக்தியுடன் எப்போதும் உன்னை வணங்குவோருக்கு, அவர்களுக்கு அழகும் வெற்றியும் புகழும் அருளி, அவர்கள் பகைவரை அழி.",
        '6.12': "நோய் அழிக்கும் சண்டிகையே, பக்தியுடன் உன்னைப் போற்றுவோருக்கு, அவர்களுக்கு அழகும் வெற்றியும் புகழும் அருளி, அவர்கள் பகைவரை அழி.",
        '6.13': "சண்டிகையே, இங்கே இடையறாது பக்தியுடன் உன்னை வழிபடுவோருக்கு, அவர்களுக்கு அழகும் வெற்றியும் புகழும் அருளி, அவர்கள் பகைவரை அழி.",
        '6.14': "நற்பேறும் ஆரோக்கியமும் அருள்; எனக்கு மேலான இன்பத்தை அருள். அழகு அருள், வெற்றி அருள், புகழ் அருள்; என் பகைவரை அழி.",
        '6.15': "என்னை வெறுப்போருக்கு முடிவைக் கொணர்; எனக்குப் பெரும் வலிமையைத் தா. அழகு அருள், வெற்றி அருள், புகழ் அருள்; என் பகைவரை அழி.",
        '6.16': "தேவியே, என் நலனைச் செய்; எனக்கு மேலான செல்வத்தைத் தா. அழகு அருள், வெற்றி அருள், புகழ் அருள்; என் பகைவரை அழி.",
        '6.17': "உன்னை வணங்கும் தேவர், அசுரர்களின் முடிமணிகள் தீண்டும் திருவடிகளுடைய அம்பிகையே: அழகு அருள், வெற்றி அருள், புகழ் அருள்; என் பகைவரை அழி.",
        '6.18': "உன் பக்தனைக் கற்றவனாகவும் புகழ்பெற்றவனாகவும் செல்வந்தனாகவும் ஆக்கு. அழகு அருள், வெற்றி அருள், புகழ் அருள்; என் பகைவரை அழி.",
        '6.19': "கொடிய அசுரர்களின் செருக்கை முறிக்கும் சண்டிகையே: உன்னை வணங்கும் எனக்கு அழகும் வெற்றியும் புகழும் அருளி, என் பகைவரை அழி.",
        '6.20': "நான்முக பிரம்மாவால் போற்றப்படும் நான்கு கரப் பரமேச்வரியே: அழகு அருள், வெற்றி அருள், புகழ் அருள்; என் பகைவரை அழி.",
        '6.21': "இடையறாத பக்தியுடன் கிருஷ்ணனால் போற்றப்படும் அம்பிகா தேவியே: அழகு அருள், வெற்றி அருள், புகழ் அருள்; என் பகைவரை அழி.",
        '6.22': "இமயமகளின் நாதனான சிவனால் போற்றப்படும் பரமேச்வரியே: அழகு அருள், வெற்றி அருள், புகழ் அருள்; என் பகைவரை அழி.",
        '6.23': "இந்திராணியின் கணவனான இந்திரனால் உண்மைப் பக்தியுடன் வழிபடப்படும் பரமேச்வரியே: அழகு அருள், வெற்றி அருள், புகழ் அருள்; என் பகைவரை அழி.",
        '6.24': "வலிய கரமுடைய அசுரர்களின் செருக்கை அழிக்கும் தேவியே: அழகு அருள், வெற்றி அருள், புகழ் அருள்; என் பகைவரை அழி.",
        '6.25': "பக்தர்களுக்கு எல்லையற்ற ஆனந்தத்தை எழச் செய்யும் அம்பிகையே: அழகு அருள், வெற்றி அருள், புகழ் அருள்; என் பகைவரை அழி.",
        '6.26': "என் மனத்துக்கு இசைந்தவளும், நல்ல குலத்தில் பிறந்தவளும், கடினமான ஸம்ஸாரக் கடலைக் கடக்க உதவுபவளுமான அழகிய மனைவியைத் தா.",
        '6.27': "இந்தத் துதியைச் சொல்லிப் பின் மகா ஸ்தோத்திரமான ஸப்தசதியைச் சொல்பவன் அதன் எழுநூறு ஸ்லோகங்களின் முழுப் பலனையும் மிகுந்த செல்வத்தையும் பெறுகிறான்.",
        '6.28': "இவ்வாறு தேவியின் அர்கலா ஸ்தோத்திரம் நிறைவுற்றது.",
        '7.0': "விநியோகம்: இந்த ஸ்ரீகீலக மந்திரத்திற்கு ரிஷி ஶிவன், சந்தஸ் அனுஷ்டுப், தேவதை ஸ்ரீமகாஸரஸ்வதீ. ஸ்ரீஜகதம்பாவின் ப்ரீதிக்காக ஸப்தஶதீ பாராயணத்தின் அங்கமாக இது ஜபிக்கப்படுகிறது.",
        '7.1': "ஓம், சண்டிகைக்கு நமஸ்காரம்.",
        '7.2': "மார்க்கண்டேயர் கூறினார்:",
        '7.3': "ஓம். தூய ஞானமே உடலாகக் கொண்டவரும், மூன்று வேதங்களையே தெய்வீகக் கண்களாகக் கொண்டவரும், மேலான நன்மையை அடைவதற்குக் காரணமானவரும், பிறைச்சந்திரனைத் தரித்தவருமான ஶிவனுக்கு நமஸ்காரம்.",
        '7.4': "இவை அனைத்தையும் மந்திரங்களின் கீலகம் (மந்திரங்களைத் திறக்கும் ஆணி) என அறிய வேண்டும். இதன் ஜபத்தில் எப்போதும் ஈடுபட்டிருப்பவனும் நலம் அடைகிறான்.",
        '7.5': "உச்சாடனம் முதலான எல்லாக் காரியங்களும் கைகூடும். இதனால் துதிப்பவர்களுக்கு தேவி இந்தத் துதியாலேயே அருள்புரிகிறாள்.",
        '7.6': "அதற்கு வேறு மந்திரமோ மருந்தோ வேறெதுவுமோ தேவையில்லை; வேறு ஜபமின்றியே உச்சாடனம் முதலான அனைத்தும் கைகூடும்.",
        '7.7': "\"இவ்வாறு எல்லாருக்கும் எல்லாம் கைகூடிவிடும்\" என்ற மக்களின் இந்த ஐயத்தைக் கண்டு, ஹரன் (ஶிவன்) இந்த மங்களமான முழு நூலையும் கட்டுப்படுத்தினார்.",
        '7.8': "அவர் சண்டிகையின் இந்தத் துதியை ரகசியமாக்கினார். அந்த நியமத்தை முறைப்படி கடைப்பிடிப்பவனின் புண்ணியத்திற்கு முடிவே இல்லை.",
        '7.9': "தேய்பிறை சதுர்தஶீ அல்லது அஷ்டமி அன்று ஒருமுகப்பட்ட மனத்துடன் —",
        '7.10': "(தேவிக்குத் தன்னுடையதை எல்லாம்) அர்ப்பணித்து (அவளது ப்ரஸாதமாக) மீண்டும் பெற்றுக்கொள்பவனும் ஐயமின்றி முழு நலம் அடைகிறான்; இல்லையெனில் அவள் மகிழ்வதில்லை. இவ்வாறு மகாதேவன் இத்தகைய ஆணியால் இதைப் பூட்டினார்.",
        '7.11': "இதை ஆணியிலிருந்து விடுவித்துத் தினமும் தெளிவாக ஜபிக்கும் மனிதன் ஸித்தனாகிறான், தேவியின் கணமாகிறான், கந்தர்வனும் ஆகிறான்.",
        '7.12': "அவன் எங்கு திரிந்தாலும் இவ்வுலகில் எங்கும் அவனுக்குப் பயம் உண்டாவதில்லை. அவன் அகால மரணத்திற்கு ஆளாவதில்லை; இறந்தபின் மோக்ஷத்தை அடைகிறான்.",
        '7.13': "இதை அறிந்தே பாராயணத்தைத் தொடங்கிச் செய்ய வேண்டும்; அறியாமல் செய்பவன் அழிகிறான். ஆகவே அறிஞர்கள் இதை முழுமையாக அறிந்த பின்னரே தொடங்குகின்றனர்.",
        '7.14': "பெண்களிடம் காணப்படும் ஸௌபாக்கியம் முதலான அனைத்தும் அவளது அருளாலேயே; ஆகவே இந்த மங்களமான துதியை ஜபிக்க வேண்டும்.",
        '7.15': "இந்தத் துதியை மெதுவாக ஜபித்தாலும் முழுமையான செல்வம் மிகுதியாக உண்டாகும்; ஆகவே இதை நிச்சயமாகத் தொடங்க வேண்டும்.",
        '7.16': "யாருடைய அருளால் ஐஶ்வர்யம், ஸௌபாக்கியம், ஆரோக்கியம், செல்வம், பகைவர் அழிவு, பரம மோக்ஷம் ஆகியவை கிடைக்கின்றனவோ அவளை மக்கள் ஏன் துதிக்கக் கூடாது?",
        '7.17': "இவ்வாறு தேவியின் கீலக ஸ்தோத்திரம் நிறைவுற்றது.",
        '8.0': "விநியோகம்: “ராத்ரீ” என்று தொடங்கும் எட்டு ருக்குகள் கொண்ட இந்த ஸூக்தத்திற்கு குசிக ஸௌபரர், அல்லது ராத்ரி, அல்லது பாரத்வாஜர் ரிஷி; ராத்ரி (இரவு) தேவதை; காயத்ரீ சந்தஸ்; தேவீ மாஹாத்ம்ய பாராயணத்தில் இதன் விநியோகம்.",
        '8.1': "வரும் இரவு தேவி நட்சத்திரங்களாகிய தன் கண்களால் எங்கும் நோக்கியுள்ளாள்; தன் எல்லா ஒளியையும் அணிந்துள்ளாள்.",
        '8.2': "அழியாத தேவி அகன்ற வெளியையும், ஆழங்களையும் உயரங்களையும் நிறைத்துள்ளாள்; தன் ஒளியால் இருளைப் பின்தள்ளுகிறாள்.",
        '8.3': "வரும் தேவி தன் சகோதரியான உஷைக்கு இடம் தந்துள்ளாள்; இருளும் விலகும்.",
        '8.4': "மரத்தில் கூட்டுக்குப் பறவைகள் செல்வது போல், அவள் வருகையில் நாங்கள் ஓய்வுக்குச் சென்றோம்; அவள் இன்று எங்களிடம் கனிவாக இருக்கட்டும்.",
        '8.5': "ஊர்கள் ஓய்ந்துவிட்டன; நடப்பன, பறப்பன அனைத்தும், இரைதேடும் பருந்துகளும் கூட ஓய்ந்துவிட்டன.",
        '8.6': "இரவே, பெண் ஓநாயையும் ஓநாயையும் விலக்கு, திருடனை விலக்கு; எங்களுக்கு எளிதில் கடக்கத் தக்கவளாவாய்.",
        '8.7': "அனைத்துக்கும் வண்ணம் பூசும் கரிய அடர்ந்த இருள் என்னை நெருங்கியுள்ளது; உஷையே, கடனைத் தீர்ப்பது போல் அதை அகற்றுவாய்.",
        '8.8': "பசுக்களைக் கொணர்வது போல் இதை உனக்குக் கொணர்ந்தேன், வானின் மகளே: இரவே, வெற்றியாளனின் புகழ்ச்சியை ஏற்பது போல் இந்தத் துதியை ஏற்பாய்.",
        '8.9': "இவ்வாறு வேதத்தில் கூறப்பட்ட ராத்ரி ஸூக்தம் நிறைவுற்றது.",
        '9.0': "ரிஷிகள் பிரம்மா–விஷ்ணு–ருத்ரர்; சந்தஸ்கள் காயத்ரீ, உஷ்ணிக், அனுஷ்டுப்; தேவதைகள் மஹாகாளீ–மஹாலக்ஷ்மீ–மஹாஸரஸ்வதீ; ஐம் பீஜம், ஹ்ரீம் சக்தி, க்லீம் கீலகம்; மஹாகாளீ–மஹாலக்ஷ்மீ–மஹாஸரஸ்வதியரின் ப்ரீதிக்காக ஜபத்தில் வினியோகம். (நவார்ண மந்திர வினியோகம், கீதா ப்ரஸ்.)",
        '9.1': "சண்டிகையின் நவார்ண (ஒன்பது எழுத்து) மந்திரம்: ஐம் ஹ்ரீம் க்லீம் சாமுண்டாயை விச்சே. (வினியோகம், ந்யாஸங்களுடன் குருவிடம் பெற வேண்டும்.)",
        '9.2': "ஐம் ஹ்ரீம் க்லீம் சாமுண்டாயை விச்சே ஸ்வாஹா. இது ஸ்ரீசண்டிகைக்கு, எனக்கு அல்ல. (நெய்யால் ஹோமம் செய்யும் நவார்ண மந்திரம்.)",
        '10.0': "ஒவ்வொரு ஸ்லோகத்துடனும் எள்–நெய் கலந்த பாயஸத்தை ஹோமம் செய்ய வேண்டும்; அல்லது ஸ்தோத்திர மந்திரங்களால் சண்டிகைக்கு மங்கல ஹவிஸ்ஸை அர்ப்பணிக்க வேண்டும்; பின்னர் ஒருமனத்துடன் அவளது நாமங்களால் தேவியை மீண்டும் பூஜிக்க வேண்டும். (வைக்ருதிக ரஹஸ்யம் 35)",
        '10.1': "இது ஸ்ரீசண்டிகைக்கு, எனக்கு அல்ல. (ஸப்தசதியின் ஒவ்வொரு ஆஹுதிக்குப் பின் சொல்லும் த்யாகம்.)",
        '11.0': "முதல் சரித்திரம்: ரிஷி பிரம்மா, தேவதை மஹாகாளீ, சந்தஸ் காயத்ரீ, சக்தி நந்தா, பீஜம் ரக்ததந்திகா, தத்வம் அக்னி, ஸ்வரூபம் ரிக்வேதம்; ஸ்ரீமஹாகாளீ ப்ரீதிக்காக முதல் சரித்திர ஜபத்தில் (அல்லது ஹோமத்தில்) வினியோகம்.",
        '11.1': "தியானம்: வாள், சக்கரம், கதை, அம்பு, வில், பரிகம், சூலம், புஶுண்டீ, தலை, சங்கு ஆகியவற்றைக் கைகளில் ஏந்தியவளும், முக்கண்ணியும், எல்லா அங்கங்களிலும் ஆபரணம் அணிந்தவளும், நீலக்கல் போல் ஒளிர்பவளும், பத்து முகங்களும் பத்துப் பாதங்களும் உடையவளுமான மகாகாளியை வணங்குகிறேன்; ஹரி உறங்கியபோது மது கைடபர்களைக் கொல்லத் தாமரையில் தோன்றிய பிரம்மா துதித்தது இவளையே.",
        '11.2': "ஓம், சண்டிகைக்கு நமஸ்காரம்.",
        '11.3': "மார்க்கண்டேயர் கூறினார்:",
        '11.4': "சூரியனின் மகனான ஸாவர்ணி எட்டாவது மனு எனப்படுகிறார். அவரது பிறப்பின் கதையை நான் விரிவாகச் சொல்கிறேன், கேள்.",
        '11.5': "மகாமாயையின் மகிமையால் சூரியனின் மகனான அந்தப் பெரும்பேறு பெற்ற ஸாவர்ணி மன்வந்தரத்தின் அதிபதியானது எப்படி என்பதைக் கேள்.",
        '11.6': "முன்பு ஸ்வாரோசிஷ மன்வந்தரத்தில் சைத்ர வம்சத்தில் பிறந்த ஸுரதன் என்ற அரசன் முழு பூமண்டலத்தையும் ஆண்டு வந்தான்.",
        '11.7': "அவன் குடிமக்களைத் தன் சொந்த மக்களைப் போல நன்கு காத்து வந்தபோது, கோலாவித்வம்ஸிகள் எனப்படும் அரசர்கள் அவனுக்குப் பகைவர்களாயினர்.",
        '11.8': "மிக வலிய படைபலம் உடைய அவனுக்கும் அவர்களுக்கும் போர் நடந்தது; அவர்கள் எண்ணிக்கையில் குறைவாக இருந்தும் அந்தக் கோலாவித்வம்ஸிகளால் அவன் போரில் தோற்கடிக்கப்பட்டான்.",
        '11.9': "பின்னர் அவன் தன் நகரத்திற்குத் திரும்பித் தன் நாட்டிற்கு மட்டும் அரசனானான்; அங்கும் அந்தப் பெரியோன் அந்த வலிய பகைவர்களால் தாக்கப்பட்டான்.",
        '11.10': "அங்கே தன் நகரத்திலேயே வலிமையும் தீமையும் கெட்ட எண்ணமும் கொண்ட அமைச்சர்கள் பலவீனமான அவனது கருவூலத்தையும் படையையும் பறித்துக்கொண்டனர்.",
        '11.11': "அப்போது ஆட்சியை இழந்த அந்த அரசன் வேட்டை என்ற சாக்கில் தனியாகக் குதிரையில் ஏறி அடர்ந்த காட்டிற்குச் சென்றான்.",
        '11.12': "அங்கே அவன் அந்தணர்களில் சிறந்த மேதஸ் முனிவரின் ஆஶ்ரமத்தைக் கண்டான்; அது அமைதியான காட்டு மிருகங்களால் நிறைந்து, முனிவரின் சீடர்களால் அழகுற்றிருந்தது.",
        '11.13': "அந்த முனிவரால் உபசரிக்கப்பட்டு, அவன் அந்தச் சிறந்த முனிவரின் ஆஶ்ரமத்தில் அங்குமிங்கும் உலாவியபடி சிறிது காலம் அங்கே தங்கினான்.",
        '11.14': "அங்கே \"என்னுடையது\" என்ற பற்றால் இழுக்கப்பட்ட மனத்துடன் அவன் இவ்வாறு எண்ணினான்: \"முன்பு என் முன்னோர்கள் காத்த அந்த நகரம் இப்போது என்னை விட்டுப் போய்விட்டது.",
        '11.15': "தீய நடத்தையுடைய என் அந்த வேலைக்காரர்கள் அதை அறவழியில் ஆள்கிறார்களா இல்லையா என்று நான் அறியேன். எப்போதும் மதம் கொண்ட என் முதன்மையான வீர யானை —",
        '11.16': "என் பகைவர்களின் வசமாகி இப்போது என்ன சுகங்களை அனுபவிக்குமோ? என் அருளையும் செல்வத்தையும் உணவையும் பெற்று எப்போதும் என்னைப் பின்பற்றியவர்கள் —",
        '11.17': "இப்போது நிச்சயம் வேறு அரசர்களுக்குப் பணிவிடை செய்துகொண்டிருப்பார்கள். முறையற்றுச் செலவழிக்கும் இயல்புடைய அவர்கள் இடைவிடாது செலவு செய்வதால்,",
        '11.18': "மிகுந்த சிரமத்துடன் சேர்த்த அந்தக் கருவூலம் தீர்ந்துவிடும்.\" இதையும் இன்னும் பிறவற்றையும் அந்த அரசன் இடைவிடாது எண்ணிக்கொண்டிருந்தான்.",
        '11.19': "அங்கே அந்தணரின் ஆஶ்ரமத்தின் அருகில் அவன் ஒரு வைஶ்யனைக் கண்டான். அரசன் அவனைக் கேட்டான்: \"ஐயா, நீ யார்? இங்கு வந்ததன் காரணம் என்ன?",
        '11.20': "நீ ஏன் துயருற்றவன் போலவும் மனம் கலங்கியவன் போலவும் காணப்படுகிறாய்?\" அன்புடன் சொன்ன அரசனின் இச்சொற்களைக் கேட்டு,",
        '11.21': "அந்த வைஶ்யன் பணிவுடன் தலைவணங்கி அரசனுக்குப் பதில் கூறினான்.",
        '11.22': "வைஶ்யன் கூறினான்:",
        '11.23': "நான் ஸமாதி என்னும் பெயருடைய வைஶ்யன்; செல்வந்தர் குலத்தில் பிறந்தவன்.",
        '11.24': "பொருளாசையால் தீயவர்களான என் மகன்களும் மனைவியும் என்னை வெளியேற்றினர். என் செல்வத்தைப் பறித்துக்கொண்ட மனைவி மக்களையும் செல்வத்தையும் இழந்து,",
        '11.25': "நம்பிக்கைக்குரிய உறவினர்களாலும் புறக்கணிக்கப்பட்டுத் துயருடன் காட்டிற்கு வந்துள்ளேன். இங்கிருக்கும் எனக்கு என் மகன்களின் நலம் கேடு பற்றிய செய்தி தெரியாது,",
        '11.26': "என் உறவினர்கள், மனைவி பற்றிய செய்தியும் தெரியாது. இப்போது அவர்கள் வீட்டில் நலமா, கேடா?",
        '11.27': "அவர்கள் எப்படி இருக்கிறார்கள்? என் மகன்கள் நன்னடத்தையுடன் இருக்கிறார்களா, தீய வழியில் செல்கிறார்களா?",
        '11.28': "அரசன் கூறினான்:",
        '11.29': "செல்வத்திற்காக உங்களை வெளியேற்றிய அந்தப் பேராசைக்கார மகன்கள், மனைவி முதலானோர் மீது —",
        '11.30': "உங்கள் மனம் ஏன் இன்னும் அன்பால் கட்டுண்டிருக்கிறது?",
        '11.31': "வைஶ்யன் கூறினான்:",
        '11.32': "என்னைப் பற்றி நீங்கள் சொன்னது அப்படியே உண்மை.",
        '11.33': "ஆனால் நான் என்ன செய்வேன்? தந்தையிடம் கொண்ட அன்பைத் துறந்து பொருளாசையால் என்னை விரட்டியவர்களிடம் என் மனம் கடினமாவதில்லை;",
        '11.34': "கணவன், உறவினர் மீதான அன்பைத் துறந்த அவர்களிடமே என் மனம் அன்பு நிறைந்துள்ளது. பேரறிவாளரே, அறிந்திருந்தும் இது ஏன் என்று எனக்குப் புரியவில்லை.",
        '11.35': "குணமற்ற உறவினர்களிடமும் என் சித்தம் அன்பில் சாய்ந்திருக்கிறது; அவர்களுக்காக எனக்குப் பெருமூச்சும் மனவருத்தமும் உண்டாகின்றன.",
        '11.36': "என்மீது அன்பில்லாத அவர்களிடம் என் மனம் கடினமாகாதபோது நான் என்ன செய்வேன்?",
        '11.37': "மார்க்கண்டேயர் கூறினார்:",
        '11.38': "விப்ரரே, பின்னர் அவர்கள் இருவரும் சேர்ந்து அந்த முனிவரை அணுகினர் —",
        '11.39': "ஸமாதி என்ற அந்த வைஶ்யனும் அந்தச் சிறந்த அரசனும். இருவரும் முறைப்படியும் தகுந்தவாறும் அவரை வணங்கி,",
        '11.40': "அந்த வைஶ்யனும் அரசனும் அமர்ந்து சில உரையாடல்களை நிகழ்த்தினர்.",
        '11.41': "அரசன் கூறினான்:",
        '11.42': "பகவானே, நான் உங்களிடம் ஒன்று கேட்க விரும்புகிறேன்; அதைக் கூறுங்கள்.",
        '11.43': "என் மனம் என் கட்டுப்பாட்டில் இல்லாமல் எனக்குத் துன்பம் தருகிறது: அரசை இழந்தும் அந்த அரசின் எல்லா அங்கங்களிடமும் எனக்குப் பற்று இருக்கிறது.",
        '11.44': "அறிந்திருந்தும் அறியாதவன் போல் இருக்கிறேன் — முனிவர்களில் சிறந்தவரே, இது என்ன? இவனும் மகன்களால் வஞ்சிக்கப்பட்டு, மனைவியாலும் வேலையாட்களாலும் கைவிடப்பட்டு,",
        '11.45': "உறவினர்களாலும் கைவிடப்பட்டும் அவர்களிடம் இன்னும் மிகுந்த அன்பு கொண்டுள்ளான். இவ்வாறு இவனும் நானும் இருவரும் மிகவும் துயருற்றிருக்கிறோம்,",
        '11.46': "குறைகளைக் கண்டிருந்தும் விஷயங்களிடம் எங்கள் மனம் பற்றால் இழுக்கப்படுகிறது. பெரியோரே, அறிந்தவர்களான எங்களுக்கும் இந்த மோகம் ஏன்?",
        '11.47': "விவேகமின்றிக் குருடர்களான எனக்கும் இவனுக்கும் இந்த மடமை உண்டாகியுள்ளது.",
        '11.48': "ரிஷி கூறினார்:",
        '11.49': "ஒவ்வொரு உயிருக்கும் புலன் விஷயங்களின் எல்லைக்குள் ஞானம் இருக்கிறது.",
        '11.50': "பெரியோனே, விஷயங்களும் தனித்தனி விதமாகவே புலப்படுகின்றன: சில உயிர்கள் பகலில் குருடு, வேறு சில இரவில் குருடு;",
        '11.51': "சில உயிர்கள் பகலிலும் இரவிலும் சமமாகக் காண்கின்றன. மனிதர்கள் அறிவுடையவர்கள் என்பது உண்மைதான், ஆனால் அவர்கள் மட்டுமல்லர்;",
        '11.52': "ஏனெனில் பசுக்கள், பறவைகள், விலங்குகள் முதலிய அனைத்தும் அறிவுடையவையே. மனிதர்களிடம் உள்ள அறிவே அந்த விலங்கு பறவைகளிடமும் உள்ளது;",
        '11.53': "அவற்றிடம் உள்ளது மனிதர்களிடமும் உள்ளது; மற்றவற்றிலும் இருவரும் ஒப்பானவர்களே. அறிவிருந்தும் இந்தப் பறவைகளைப் பார்: தம் குஞ்சுகளின் அலகுகளில் தானியத்தை இடுகின்றன,",
        '11.54': "தாமே பசியால் வாடினாலும் மோகத்தால் இவ்வாறு செய்கின்றன. மனிதர்களில் புலியே, மனிதர்களும் தம் மக்கள் மீது ஆசை கொண்டவர்கள்,",
        '11.55': "பதில் உதவியை எதிர்பார்க்கும் ஆசையால் — இதை நீ காணவில்லையா? அப்படியிருந்தும் அவர்கள் \"என்னுடையது\" என்ற சுழலில், மோகக் குழியில் தள்ளப்படுகின்றனர்,",
        '11.56': "ஸம்ஸாரத்தை நிலைநிறுத்தும் மகாமாயையின் மகிமையால். ஆகவே இதில் வியப்படைய வேண்டியதில்லை. உலகின் தலைவனுடைய யோகநித்திரையே —",
        '11.57': "ஹரியின் மகாமாயை இவளே; இவளாலேயே உலகம் மயங்குகிறது. அந்தப் பகவதீ தேவி ஞானிகளின் மனங்களையும் வலிந்து இழுத்து",
        '11.58': "மோகத்தில் ஆழ்த்துகிறாள். அசையும் அசையாப் பொருள்களுடன் கூடிய இந்த முழு உலகமும் அவளாலேயே படைக்கப்படுகிறது.",
        '11.59': "மகிழ்ந்தால் அவளே மனிதர்களுக்கு முக்திக்காக வரமளிப்பவள் ஆகிறாள். அவளே பரம வித்யை, முக்திக்குக் காரணமான என்றுமுள்ளவள்,",
        '11.60': "ஸம்ஸார பந்தத்திற்கும் அவளே காரணம் — அவள் எல்லா ஈஶ்வரர்களுக்கும் ஈஶ்வரி.",
        '11.61': "அரசன் கூறினான்:",
        '11.62': "பகவானே, நீங்கள் மகாமாயை என்று கூறும் அந்தத் தேவி யார்?",
        '11.63': "இருபிறப்பாளரே, அவள் எப்படித் தோன்றினாள்? அவளது செயல்கள் என்ன? அந்தத் தேவியின் மகிமை என்ன, இயல்பு என்ன, அவள் எதிலிருந்து தோன்றினாள்?",
        '11.64': "பிரம்மத்தை அறிந்தவர்களில் சிறந்தவரே, இவை அனைத்தையும் உங்களிடமிருந்து கேட்க விரும்புகிறேன்.",
        '11.65': "ரிஷி கூறினார்:",
        '11.66': "அவள் நித்தியமானவளே; உலகமே அவளது வடிவம்; இவை அனைத்தும் அவளால் வியாபிக்கப்பட்டுள்ளன.",
        '11.67': "அப்படியிருந்தும் அவள் பலவிதமாகத் தோன்றுவதை என்னிடமிருந்து கேள். தேவர்களின் காரியம் நிறைவேற அவள் எப்போது தோன்றுகிறாளோ,",
        '11.68': "அப்போது நித்தியமானவளாயினும் உலகில் \"தோன்றினாள்\" எனப்படுகிறாள். கல்பத்தின் முடிவில் உலகம் ஒரே கடலாக ஆனபோது, விஷ்ணு —",
        '11.69': "பகவானான பிரபு — ஶேஷனைப் படுக்கையாக விரித்து யோகநித்திரையில் ஆழ்ந்தார். அப்போது மது, கைடபன் எனப் புகழ்பெற்ற இரண்டு கொடிய அசுரர்கள்,",
        '11.70': "விஷ்ணுவின் காதுகளின் அழுக்கிலிருந்து தோன்றியவர்கள், பிரம்மாவைக் கொல்ல முற்பட்டனர். விஷ்ணுவின் நாபிக் கமலத்தில் இருந்த பிரஜாபதி பிரம்மா,",
        '11.71': "அந்தக் கொடிய அசுரர் இருவரையும் உறங்கும் ஜனார்த்தனரையும் கண்டு, ஒருமுகப்பட்ட உள்ளத்துடன் அந்த யோகநித்திரையைத் துதித்தார் —",
        '11.72': "ஹரியை எழுப்புவதற்காக; ஹரியின் கண்களில் உறைபவளும், உலகின் ஈஶ்வரியும், உலகைத் தாங்குபவளும், காத்தலையும் அழித்தலையும் செய்பவளும்,",
        '11.73': "ஒப்பற்ற பகவதியான விஷ்ணுவின் நித்திரையைத் தேஜஸின் பிரபுவான பிரம்மா துதித்தார்.",
        '11.74': "பிரம்மா கூறினார்:",
        '11.75': "நீயே ஸ்வாஹா, நீயே ஸ்வதா, நீயே வஷட்காரம்; ஸ்வரங்களின் ஆத்மாவும் நீயே.",
        '11.76': "நீயே அமுதம். நித்தியமான அக்ஷரத்தில் (ஓங்காரத்தில்) மூன்று மாத்திரைகளின் வடிவில் நிலைத்திருக்கிறாய்; தனியாக உச்சரிக்க இயலாத நித்தியமான அரை மாத்திரையும் நீயே.",
        '11.77': "நீயே ஸந்த்யா, ஸாவித்ரீ; தேவியே, நீயே பரம அன்னை. உன்னாலேயே இவ்வுலகம் தாங்கப்படுகிறது, உன்னாலேயே இவ்வுலகம் படைக்கப்படுகிறது,",
        '11.78': "தேவியே, உன்னாலேயே இது காக்கப்படுகிறது; இறுதியில் எப்போதும் நீயே இதை விழுங்குகிறாய். படைப்பில் படைப்பின் வடிவினள், காத்தலில் நிலைபெறுதலின் வடிவினள்,",
        '11.79': "அவ்வாறே இவ்வுலகின் முடிவில் அழித்தலின் வடிவினள், உலகமயமானவளே. நீயே மகாவித்யை, மகாமாயை, மகாமேதை, மகாஸ்ம்ருதி,",
        '11.80': "மகாமோகை, மகாதேவீ, மகாஸுரீ நீயே. மூன்று குணங்களையும் வெளிப்படுத்தும், அனைத்திற்கும் மூலமான ப்ரக்ருதியும் நீயே.",
        '11.81': "நீயே காலராத்ரி, மகாராத்ரி, கொடிய மோகராத்ரி. நீயே ஸ்ரீ, நீயே ஈஶ்வரி, நீயே ஹ்ரீ (நாணம்), அறிவையே அடையாளமாகக் கொண்ட புத்தியும் நீயே.",
        '11.82': "நாணம், வளம், நிறைவு, அமைதி, பொறுமை நீயே. வாள், சூலம், கதை, சக்கரம் ஏந்திய கொடியவளும் நீயே,",
        '11.83': "சங்கு, வில், அம்பு, புஶுண்டீ, பரிகம் ஆகியவற்றை ஆயுதங்களாகக் கொண்டவள். நீ மென்மையானவள், எல்லா மென்மையானவற்றையும் விட மென்மையானவள், மிக அழகியவள்;",
        '11.84': "உயர்ந்தவை தாழ்ந்தவை அனைத்திற்கும் மேலானவள், நீயே பரமேஶ்வரி. அனைத்தின் ஆத்மாவே, எங்கேனும் உள்ள உண்மையோ இன்மையோ ஆன எந்தப் பொருளாயினும்,",
        '11.85': "அவை அனைத்தின் சக்தியும் நீயே; அப்படியிருக்க உன்னை எப்படித் துதிப்பது? உலகைப் படைத்துக் காத்து விழுங்குபவரையும் நீ",
        '11.86': "உறக்கத்தின் வசமாக்கினாய் — இங்கு உன்னைத் துதிக்க யாருக்குத் திறன் உண்டு? விஷ்ணுவும் நானும் ஈஶானனும் உடல்களைத் தாங்கும்படி",
        '11.87': "உன்னாலேயே செய்யப்பட்டோம்; ஆகவே உன்னைத் துதிக்க யாருக்கு வல்லமை இருக்கும்? தேவியே, உன் உயர்ந்த மகிமைகளால் இவ்வாறு துதிக்கப்பட்ட நீ,",
        '11.88': "வெல்ல முடியாத இந்த மது கைடபர் என்னும் அசுரர்களை மயக்கு; உலகின் தலைவனான அச்யுதனை விரைவில் எழுப்பு,",
        '11.89': "இந்த இரு மகா அசுரர்களைக் கொல்ல அவரை விழிப்படையச் செய்.",
        '11.90': "ரிஷி கூறினார்:",
        '11.91': "இவ்வாறு அங்கே படைப்போனால் (பிரம்மாவால்) துதிக்கப்பட்ட தாமஸீ தேவி,",
        '11.92': "மது கைடபர்களைக் கொல்ல விஷ்ணுவை எழுப்புவதற்காக அவரது கண்கள், வாய், மூக்கு, கைகள், இதயம், மார்பு ஆகியவற்றிலிருந்து",
        '11.93': "வெளிப்பட்டு, தோற்றம் புலப்படாத பிரம்மாவின் கண்முன் நின்றாள். அவளால் விடுவிக்கப்பட்ட உலகநாதன் ஜனார்த்தனன் எழுந்தார்,",
        '11.94': "ஒரே கடலில் இருந்த பாம்புப் படுக்கையிலிருந்து. பின்னர் அவர் தீய உள்ளமும் மிகுந்த வீரமும் பராக்கிரமமும் கொண்ட மது கைடபர்களைக் கண்டார்,",
        '11.95': "கோபத்தால் சிவந்த கண்களுடன் பிரம்மாவை விழுங்க முனைந்திருந்தனர். அப்போது எழுந்து பகவான் ஹரி அவர்களுடன் போரிட்டார்,",
        '11.96': "ஐயாயிரம் ஆண்டுகள், எங்கும் நிறைந்த அவர் கைகளையே ஆயுதமாகக் கொண்டு. அவர்களும் மிகுந்த வலிமையால் வெறிகொண்டு, மகாமாயையால் மயக்கப்பட்டு,",
        '11.97': "கேஶவனிடம் \"எங்களிடமிருந்து ஒரு வரம் கேள்\" என்று கூறினர்.",
        '11.98': "ஸ்ரீபகவான் கூறினார்:",
        '11.99': "நீங்கள் என்னிடம் மகிழ்ந்திருந்தால், இப்போது நீங்கள் இருவரும் என்னால் கொல்லப்பட வேண்டும்.",
        '11.100': "இங்கு வேறு வரம் எதற்கு? நான் கேட்பது இதுவே.",
        '11.101': "ரிஷி கூறினார்:",
        '11.102': "இவ்வாறு ஏமாற்றப்பட்ட அவ்விருவரும் அப்போது உலகம் முழுவதும் நீர் நிறைந்திருப்பதைக் கண்டு,",
        '11.103': "தாமரைக் கண்ணனான பகவானிடம் கூறினர்: \"பூமி நீரில் மூழ்காத இடத்தில் எங்களைக் கொல்.\"",
        '11.104': "ரிஷி கூறினார்:",
        '11.105': "\"அப்படியே ஆகட்டும்\" என்று கூறி, சங்கு சக்கரம் கதை ஏந்திய பகவான் அவர்களின் தலைகளைத் தன் தொடையின் மேல் வைத்துச் சக்கரத்தால் அறுத்தார்.",
        '11.106': "இவ்வாறு பிரம்மாவாலேயே துதிக்கப்பட்டு இவள் தோன்றினாள். இந்தத் தேவியின் மகிமையை மேலும் சொல்கிறேன், கேள்.",
        '11.107': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் தேவீ மாஹாத்ம்யத்தில் \"மது கைடப வதம்\" என்னும் முதல் அத்தியாயம் நிறைவுற்றது.",
        '12.0': "நடுச் சரித்திரம்: ரிஷி விஷ்ணு, தேவதை மஹாலக்ஷ்மீ, சந்தஸ் உஷ்ணிக், சக்தி சாகம்பரீ, பீஜம் துர்கா, தத்வம் வாயு, ஸ்வரூபம் யஜுர்வேதம்; ஸ்ரீமஹாலக்ஷ்மீ ப்ரீதிக்காக நடுச் சரித்திர ஜபத்தில் (அல்லது ஹோமத்தில்) வினியோகம்.",
        '12.1': "தியானம்: அக்ஷமாலை, கோடரி, கதை, அம்பு, வஜ்ரம், தாமரை, வில், கமண்டலம், தண்டம், சக்தி, வாள், கேடயம், சங்கு, மணி, மதுக்கிண்ணம், சூலம், பாசம், ஸுதர்ஶன சக்கரம் ஆகியவற்றைக் கைகளில் ஏந்தியவளும், மலர்ந்த முகமுடையவளும், தாமரையில் அமர்ந்தவளும், மஹிஷனை அழித்தவளுமான மகாலக்ஷ்மியை இங்கு வணங்குகிறேன். ஓம் ஹ்ரீம்.",
        '12.2': "ரிஷி கூறினார்:",
        '12.3': "முன்பு மஹிஷன் அசுரர்களின் தலைவனாகவும் புரந்தரன் (இந்திரன்) தேவர்களின் தலைவனாகவும் இருந்தபோது, தேவர்களுக்கும் அசுரர்களுக்கும் முழுமையாக நூறு ஆண்டுகள் போர் நடந்தது.",
        '12.4': "அப்போரில் பெரும் வீரம் கொண்ட அசுரர்களால் தேவர் படை தோற்கடிக்கப்பட்டது; எல்லாத் தேவர்களையும் வென்று மஹிஷாஸுரன் இந்திரனானான்.",
        '12.5': "அப்போது தோற்ற தேவர்கள் தாமரையில் பிறந்த பிரஜாபதியான பிரம்மாவை முன்னிட்டுக்கொண்டு ஈஶனும் கருடக்கொடியோனான விஷ்ணுவும் இருந்த இடத்திற்குச் சென்றனர்.",
        '12.6': "நடந்ததை நடந்தபடியே, மஹிஷாஸுரனின் செயல்களையும் தேவர்கள் தோற்கடிக்கப்பட்டதன் விவரத்தையும் தேவர்கள் அவ்விருவருக்கும் கூறினர்.",
        '12.7': "\"சூரியன், இந்திரன், அக்னி, வாயு, சந்திரன், யமன், வருணன் மற்றும் பிறரின் அதிகாரங்களை அவனே தானாக ஏற்றுக்கொண்டுள்ளான்.",
        '12.8': "அந்தத் தீய மஹிஷனால் சொர்க்கத்திலிருந்து விரட்டப்பட்ட எல்லாத் தேவகணங்களும் மனிதர்களைப் போலப் பூமியில் அலைகின்றனர்.",
        '12.9': "அமரர்களின் பகைவனுடைய இச்செயல்கள் அனைத்தையும் உங்களிடம் கூறினோம். உங்களைச் சரணடைந்துள்ளோம்; அவனைக் கொல்லும் வழியைச் சிந்தியுங்கள்.\"",
        '12.10': "தேவர்களின் இச்சொற்களைக் கேட்டு மதுஸூதனனும் ஶம்புவும் கோபம் கொண்டனர்; அவர்களின் முகங்கள் புருவச் சுளிப்பால் கோணின.",
        '12.11': "அப்போது பெருங்கோபம் நிறைந்த சக்கரதாரியின் முகத்திலிருந்து மகத்தான ஒளி வெளிப்பட்டது; பிரம்மா, ஶங்கரர் ஆகியோரிடமிருந்தும் அவ்வாறே.",
        '12.12': "இந்திரன் முதலான பிற தேவர்களின் உடல்களிலிருந்தும் மிகப் பெரிய ஒளி வெளிப்பட்டது; அவை அனைத்தும் ஒன்றாகச் சேர்ந்தன.",
        '12.13': "தீச்சுடர்களால் திசைகளை நிறைத்த, எரியும் மலை போன்ற மிகுந்த ஒளிக்குவியலைத் தேவர்கள் அங்கே கண்டனர்.",
        '12.14': "எல்லாத் தேவர்களின் உடல்களிலிருந்தும் தோன்றிய அந்த ஒப்பற்ற ஒளி ஓரிடத்தில் திரண்டு, தன் ஒளியால் மூவுலகையும் நிறைத்த ஒரு பெண்ணாக ஆனது.",
        '12.15': "ஶம்புவின் ஒளியால் அவளது முகம் உண்டானது; யமனின் ஒளியால் கேசம்; விஷ்ணுவின் ஒளியால் கைகள்;",
        '12.16': "சந்திரனின் ஒளியால் இரு மார்பகங்கள்; இந்திரனின் ஒளியால் இடை; வருணனின் ஒளியால் கால்களும் தொடைகளும்; பூமியின் ஒளியால் இடுப்பின் பின்புறம்;",
        '12.17': "பிரம்மாவின் ஒளியால் பாதங்கள்; சூரியனின் ஒளியால் கால்விரல்கள்; வஸுக்களின் ஒளியால் கைவிரல்கள்; குபேரனின் ஒளியால் மூக்கு.",
        '12.18': "பிரஜாபதியின் ஒளியால் அவளது பற்கள் உண்டாயின; அவ்வாறே அக்னியின் ஒளியால் மூன்று கண்கள் தோன்றின.",
        '12.19': "இரு ஸந்தியைகளின் ஒளியால் புருவங்கள், வாயுவின் ஒளியால் காதுகள்; பிற தேவர்களின் ஒளிகளாலும் மங்களமான ஶிவா உருவெடுத்தாள்.",
        '12.20': "அப்போது எல்லாத் தேவர்களின் ஒளிக்குவியலிலிருந்து தோன்றிய அவளைக் கண்டு மஹிஷனால் துன்புற்ற தேவர்கள் மகிழ்ந்தனர்.",
        '12.21': "பினாகம் ஏந்திய ஶிவன் தன் சூலத்திலிருந்து ஒரு சூலத்தை எடுத்து அவளுக்கு அளித்தார்; கிருஷ்ணன் (விஷ்ணு) தன் சக்கரத்திலிருந்து ஒரு சக்கரத்தை உண்டாக்கி அளித்தார்.",
        '12.22': "வருணன் சங்கையும், அக்னி சக்தி ஆயுதத்தையும் அவளுக்கு அளித்தனர்; வாயு வில்லையும் அம்புகள் நிறைந்த இரண்டு அம்பறாத்தூணிகளையும் அளித்தான்.",
        '12.23': "அமரர்களின் தலைவனான ஆயிரம் கண்ணுடைய இந்திரன் தன் வஜ்ரத்திலிருந்து ஒரு வஜ்ரத்தை உண்டாக்கியும், ஐராவத யானையிடமிருந்து ஒரு மணியையும் அவளுக்கு அளித்தான்.",
        '12.24': "யமன் தன் காலதண்டத்திலிருந்து ஒரு தண்டத்தையும், நீரின் தலைவன் பாசத்தையும் அளித்தனர்; பிரஜாபதி அக்ஷமாலையையும், பிரம்மா கமண்டலத்தையும் அளித்தனர்.",
        '12.25': "சூரியன் அவளது எல்லா மயிர்க்கால்களிலும் தன் கதிர்களை நிரப்பினான்; காலன் அவளுக்கு வாளையும் களங்கமற்ற கேடயத்தையும் அளித்தான்.",
        '12.26': "பாற்கடல் களங்கமற்ற மாலையையும், ஒருபோதும் பழையதாகாத இரண்டு ஆடைகளையும், தெய்வீகச் சூடாமணியையும், குண்டலங்களையும், கடகங்களையும்,",
        '12.27': "வெண்மையான பிறைச்சந்திர அணிகலனையும், எல்லாக் கைகளுக்கும் தோள்வளைகளையும், களங்கமற்ற இரண்டு சிலம்புகளையும், ஒப்பற்ற கழுத்தணியையும்,",
        '12.28': "எல்லா விரல்களுக்கும் ரத்தின மோதிரங்களையும் அளித்தது. விஶ்வகர்மா அவளுக்கு மிகத் தூய்மையான கோடரியையும்,",
        '12.29': "பலவித அஸ்திரங்களையும், துளைக்க முடியாத கவசத்தையும் அளித்தான். கடல் தலைக்கு வாடாத தாமரை மாலையையும், மார்புக்கு மற்றொன்றையும்,",
        '12.30': "மிக அழகிய தாமரையையும் அவளுக்கு அளித்தது. இமவான் வாகனமாகச் சிங்கத்தையும் பலவித ரத்தினங்களையும் அளித்தான்.",
        '12.31': "செல்வத்தின் தலைவனான குபேரன் ஒருபோதும் வற்றாத மதுக்கிண்ணத்தை அளித்தான். இப்பூமியைத் தாங்கும் எல்லா நாகங்களின் தலைவனான ஶேஷன்,",
        '12.32': "பெரும் மணிகளால் அலங்கரிக்கப்பட்ட நாகமாலையை அவளுக்கு அளித்தான். பிற தேவர்களாலும் ஆபரணங்களாலும் ஆயுதங்களாலும் கௌரவிக்கப்பட்ட தேவி",
        '12.33': "மீண்டும் மீண்டும் அட்டகாசச் சிரிப்புடன் உரக்க முழங்கினாள். அவளது பயங்கர முழக்கத்தால் வானம் முழுவதும் நிரம்பியது,",
        '12.34': "அளவிட முடியாத அப்பெரும் ஒலியால் பெரிய எதிரொலி எழுந்தது. எல்லா உலகங்களும் கலங்கின, கடல்கள் நடுங்கின.",
        '12.35': "பூமி அதிர்ந்தது, எல்லா மலைகளும் அசைந்தன. தேவர்கள் மகிழ்ச்சியுடன் சிங்கவாஹினியை நோக்கி \"ஜய!\" என்று முழங்கினர்.",
        '12.36': "பக்தியால் பணிந்த உடலுடன் முனிவர்கள் அவளைத் துதித்தனர். மூவுலகும் கலங்கியிருப்பதைக் கண்டு தேவர்களின் பகைவர்கள்",
        '12.37': "தங்கள் படைகள் அனைத்தையும் அணிவகுத்து ஆயுதங்களை உயர்த்தி எழுந்தனர். \"ஆ! இது என்ன?\" என்று மஹிஷாஸுரன் கோபத்துடன் கூவி,",
        '12.38': "எல்லா அசுரர்களும் சூழ அந்த ஒலியை நோக்கி ஓடினான். அப்போது தன் ஒளியால் மூவுலகையும் நிறைத்திருந்த தேவியைக் கண்டான்,",
        '12.39': "அவளது பாதங்களின் அழுத்தத்தால் பூமி தாழ்ந்தது, மகுடம் வானத்தை உரசியது, வில்நாணின் ஓசையால் பாதாளம் முழுவதும் கலங்கியது,",
        '12.40': "ஆயிரம் கைகளால் சுற்றிலும் திசைகளை நிறைத்து நின்றாள். பின்னர் அந்தத் தேவிக்கும் தேவர்களின் பகைவர்களுக்கும் போர் தொடங்கியது,",
        '12.41': "பலவிதமாக எய்யப்பட்ட ஆயுதங்களாலும் அஸ்திரங்களாலும் திசைகள் ஒளிர்ந்தன. மஹிஷாஸுரனின் சேனாதிபதியான சிக்ஷுரன் என்னும் மகா அசுரன்",
        '12.42': "போரிட்டான்; சாமரனும் பிறருடன் நால்வகைப் படையுடன் போரிட்டான். உதக்ரன் என்னும் மகா அசுரன் அறுபதாயிரம் தேர்களுடன்,",
        '12.43': "மகாஹனு ஆயிரம் அயுதம் (ஒரு கோடி) தேர்களுடனும், அஸிலோமன் என்னும் மகா அசுரன் ஐம்பது நியுதங்களுடனும் போரிட்டனர்.",
        '12.44': "பாஷ்கலன் அறுநூறு அயுதம் (அறுபது லட்சம்) தேர்களுடன் களத்தில் போரிட்டான். பல்லாயிரக்கணக்கான யானை குதிரைக் கூட்டங்களால் சூழப்பட்டு,",
        '12.45': "ஒரு கோடித் தேர்களுடன் (பரிவாரிதன் என்பவன்) அப்போரில் போரிட்டான். பிடாலன் என்பவன் ஐம்பது அயுதம் அயுதங்கள் (ஐந்நூறு கோடி) தேர்களுடன்,",
        '12.46': "தேர்கள் சூழ அச்சமரில் போரிட்டான். அங்கே பிற மகா அசுரர்களும் பத்தாயிரக் கணக்கில் தேர், யானை, குதிரைகளால் சூழப்பட்டு,",
        '12.47': "அப்போரில் தேவியுடன் போரிட்டனர். கோடிகோடி ஆயிரம் தேர்களாலும் யானைகளாலும்",
        '12.48': "குதிரைகளாலும் சூழப்பட்டு மஹிஷாஸுரன் அப்போரில் இருந்தான். தோமரங்கள், பிந்திபாலங்கள், சக்திகள், உலக்கைகள்,",
        '12.49': "வாள்கள், கோடரிகள், பட்டிஶங்கள் ஆகியவற்றால் அவர்கள் களத்தில் தேவியுடன் போரிட்டனர். சிலர் சக்திகளை வீசினர், வேறு சிலர் பாசங்களை,",
        '12.50': "வாள் வீச்சுகளால் தேவியைக் கொல்ல முயன்றனர். அப்போது சண்டிகா தேவியும் அந்த ஆயுதங்களையும் அஸ்திரங்களையும்",
        '12.51': "விளையாட்டாகவே வெட்டி வீழ்த்தினாள், தன் ஆயுத அஸ்திரங்களைப் பொழிந்தபடி. களைப்பற்ற முகத்துடன், தேவர்களாலும் ரிஷிகளாலும் துதிக்கப்பட்டவளாக,",
        '12.52': "அந்த ஈஶ்வரி அசுரர்களின் உடல்கள் மீது ஆயுத அஸ்திரங்களை எய்தாள். தேவியின் வாகனமான சிங்கமும் கோபம் கொண்டு பிடரியை உலுக்கியபடி,",
        '12.53': "காட்டில் நெருப்பைப் போல அசுரப் படைகளுக்குள் புகுந்து திரிந்தது. களத்தில் போரிட்டுக்கொண்டிருந்த அம்பிகை விட்ட மூச்சுகளே",
        '12.54': "உடனே நூறாயிரக் கணக்கான கணங்களாகத் தோன்றின. அவர்கள் கோடரிகள், பிந்திபாலங்கள், வாள்கள், பட்டிஶங்களால் போரிட்டனர்,",
        '12.55': "தேவியின் சக்தியால் வலிமை பெற்று அசுரக் கூட்டங்களை அழித்தபடி. சில கணங்கள் முரசுகளை அறைந்தனர், வேறு சிலர் சங்குகளை ஊதினர்,",
        '12.56': "மற்றும் சிலர் அந்தப் போர்ப் பெருவிழாவில் மிருதங்கங்களை முழக்கினர். பின்னர் தேவி திரிசூலம், கதை, சக்திகளின் மழை,",
        '12.57': "வாள் முதலியவற்றால் நூற்றுக்கணக்கான மகா அசுரர்களைக் கொன்றாள்; மணியோசையால் மயங்கிய பிறரை வீழ்த்தினாள்.",
        '12.58': "வேறு சில அசுரர்களைப் பாசத்தால் கட்டித் தரையில் இழுத்தாள். சிலர் கூரிய வாள் வீச்சுகளால் இரு துண்டுகளாக்கப்பட்டனர், வேறு சிலர்",
        '12.59': "கதையின் அடியால் நசுக்கப்பட்டுத் தரையில் கிடந்தனர்; சிலர் உலக்கையால் கடுமையாக அடிக்கப்பட்டு ரத்தம் கக்கினர்.",
        '12.60': "சிலர் சூலத்தால் மார்பு பிளக்கப்பட்டுத் தரையில் வீழ்ந்தனர்; சிலர் போர்க்களத்தில் அம்பு வெள்ளத்தால் சல்லடையாகத் துளைக்கப்பட்டனர்.",
        '12.61': "பருந்துகளைப் போல வீழ்ந்து தேவர்களைத் துன்புறுத்தியவர்கள் உயிர் துறந்தனர். சிலரின் கைகள் வெட்டப்பட்டன, வேறு சிலரின் கழுத்துகள் அறுபட்டன;",
        '12.62': "மற்றும் சிலரின் தலைகள் உருண்டன; சிலர் நடுவில் பிளக்கப்பட்டனர்; இன்னும் சில மகா அசுரர்கள் கால்கள் வெட்டப்பட்டுத் தரையில் வீழ்ந்தனர்.",
        '12.63': "சிலர் தேவியால் இரண்டாகப் பிளக்கப்பட்டு ஒரு கை, ஒரு கண், ஒரு கால் உடையவர்களாயினர். வேறு சிலர் தலை வெட்டப்பட்டும் விழுந்து மீண்டும் எழுந்தனர்.",
        '12.64': "தலையற்ற முண்டங்கள் சிறந்த ஆயுதங்களைப் பற்றிக்கொண்டு தேவியுடன் போரிட்டன; வேறு சில அப்போரில் வாத்தியங்களின் தாளத்திற்கேற்ப நடனமாடின.",
        '12.65': "தலை வெட்டப்பட்ட முண்டங்களாகக் கைகளில் வாள், சக்தி, ரிஷ்டி ஏந்திய பிற மகா அசுரர்கள் \"நில், நில்\" என்று தேவியை நோக்கிக் கூவினர்.",
        '12.66': "அந்தப் பெரும்போர் நடந்த இடத்தில் வீழ்ந்த தேர்கள், யானைகள், குதிரைகள், அசுரர்களால் பூமி நடக்க முடியாததாக ஆனது.",
        '12.67': "அசுரப் படையின் நடுவே, யானைகள், அசுரர்கள், குதிரைகள் இடையே உடனே ரத்த வெள்ளத்தின் பெரு நதிகள் ஓடின.",
        '12.68': "நெருப்பு புல்லும் விறகும் கொண்ட பெருங்குவியலை அழிப்பது போல அம்பிகை கணப்பொழுதில் அசுரர்களின் அப்பெரும் படையை அழித்தாள்.",
        '12.69': "அந்தச் சிங்கமும் பிடரியை உலுக்கிப் பெருமுழக்கம் செய்தபடி, தேவர்களின் பகைவர்களுடைய உடல்களிலிருந்து உயிர்களையே தேடி எடுப்பது போலிருந்தது.",
        '12.70': "தேவியும் அந்தக் கணங்களும் அங்கே மகா அசுரர்களுடன் எத்தகைய போர் புரிந்தனர் என்றால், வானில் தேவர்கள் மகிழ்ந்து மலர் மழை பொழிந்தனர்.",
        '12.71': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் தேவீ மாஹாத்ம்யத்தில் \"மஹிஷாஸுர ஸைன்ய வதம்\" என்னும் இரண்டாம் அத்தியாயம் நிறைவுற்றது.",
        '13.0': "தியானம்: உதிக்கும் ஆயிரம் சூரியர்களின் ஒளியுடையவளும், சிவந்த பட்டாடை அணிந்தவளும், தலைமாலை தரித்தவளும், ரத்தம் பூசிய மார்பகங்களை உடையவளும், தாமரைக் கைகளில் ஜபமாலை, வித்யை (நூல்), அபயம், வரம் ஆகியவற்றைத் தாங்கியவளும், முக்கண்களால் ஒளிரும் தாமரை முகத்தவளும், சந்திரனைக் கட்டிய ரத்தின மகுடம் அணிந்தவளும், தாமரையில் அமர்ந்தவளுமான தேவியை வணங்குகிறேன்.",
        '13.1': "ரிஷி கூறினார்:",
        '13.2': "அந்தப் படை அழிக்கப்படுவதைக் கண்டு சேனாதிபதியான மகா அசுரன் சிக்ஷுரன் கோபத்துடன் அம்பிகையுடன் போரிட முன்வந்தான்.",
        '13.3': "மேகம் மேரு மலையின் சிகரத்தின் மீது மழை பொழிவது போல அந்த அசுரன் போரில் தேவியின் மீது அம்பு மழை பொழிந்தான்.",
        '13.4': "அப்போது தேவி அவனது அம்புக் கூட்டங்களை விளையாட்டாக வெட்டி, தன் அம்புகளால் அவனது குதிரைகளையும் சாரதியையும் கொன்றாள்.",
        '13.5': "உடனே அவனது வில்லையும் மிக உயர்ந்த கொடியையும் வெட்டினாள்; வில்லை இழந்த அவனது அங்கங்களை விரைந்த அம்புகளால் துளைத்தாள்.",
        '13.6': "வில் முறிந்து, தேரின்றி, குதிரைகளும் சாரதியும் கொல்லப்பட்ட நிலையில், அந்த அசுரன் வாளும் கேடயமும் ஏந்தித் தேவியை நோக்கி ஓடினான்.",
        '13.7': "கூரிய முனையுடைய வாளால் சிங்கத்தின் தலையில் அடித்து, மிக வேகமாகத் தேவியின் இடது கையிலும் அடித்தான்.",
        '13.8': "அரசகுமாரா, அவனது வாள் அவளது கையைத் தொட்டதும் உடைந்து சிதறியது. அப்போது கோபத்தால் சிவந்த கண்களுடன் அவன் சூலத்தைப் பற்றினான்.",
        '13.9': "அந்த மகா அசுரன் வானிலிருந்து விழும் சூரிய வட்டம் போல ஒளியுடன் சுடர்விட்ட அதைப் பத்ரகாளியின் மீது எறிந்தான்.",
        '13.10': "அந்தச் சூலம் வருவதைக் கண்டு தேவி தன் சூலத்தை எறிந்தாள்; அதனால் அவனது சூலமும் அந்த மகா அசுரனும் நூறு துண்டுகளாயினர்.",
        '13.11': "மஹிஷனின் அந்த மாவீர சேனாதிபதி கொல்லப்பட்டதும், தேவர்களைத் துன்புறுத்தும் சாமரன் யானையின் மீது ஏறி வந்தான்.",
        '13.12': "அவனும் தேவியின் மீது சக்தி ஆயுதத்தை எறிந்தான்; அம்பிகை உடனே \"ஹும்\" என்ற ஒலியாலேயே அதைத் தாக்கி ஒளியிழக்கச் செய்து தரையில் வீழ்த்தினாள்.",
        '13.13': "சக்தி முறிந்து விழுந்ததைக் கண்டு கோபம் கொண்ட சாமரன் சூலத்தை எறிந்தான்; அதையும் அவள் அம்புகளால் வெட்டினாள்.",
        '13.14': "அப்போது சிங்கம் பாய்ந்து யானையின் மத்தகத்தின் இடையே நின்று அந்தத் தேவப் பகைவனுடன் கைகலப்புப் போர் புரிந்தது.",
        '13.15': "போரிட்டபடியே அவ்விருவரும் அந்த யானையிலிருந்து தரைக்கு வந்து, மிகக் கொடிய அடிகளுடன் பெருங்கோபத்துடன் சண்டையிட்டனர்.",
        '13.16': "அப்போது சிங்கம் வேகமாக வானில் பாய்ந்து கீழே பாய்ந்து, பாதத்தின் அடியால் சாமரனின் தலையைத் துண்டித்தது.",
        '13.17': "உதக்ரன் போரில் தேவியால் கற்கள், மரங்கள் முதலியவற்றால் கொல்லப்பட்டான்; கராலனும் பற்கள், முஷ்டிகள், அறைகளால் வீழ்த்தப்பட்டான்.",
        '13.18': "கோபம் கொண்ட தேவி கதையின் அடிகளால் உத்ததனைப் பொடியாக்கினாள்; பிந்திபாலத்தால் பாஷ்கலனையும், அம்புகளால் தாம்ரனையும் அந்தகனையும் கொன்றாள்.",
        '13.19': "முக்கண்ணியான பரமேஶ்வரி உக்ராஸ்யன், உக்ரவீர்யன், மகாஹனு ஆகியோரைத் திரிசூலத்தால் கொன்றாள்.",
        '13.20': "வாளால் பிடாலனின் தலையை உடலிலிருந்து துண்டித்தாள்; துர்தரன், துர்முகன் இருவரையும் அம்புகளால் யமலோகத்திற்கு அனுப்பினாள்.",
        '13.21': "இவ்வாறு தன் படை அழிந்துகொண்டிருக்க, மஹிஷாஸுரன் தன் எருமை வடிவத்தால் அந்தக் கணங்களை அச்சுறுத்தினான்.",
        '13.22': "சிலரை மூக்கின் அடியாலும், சிலரைக் குளம்புகளின் உதையாலும், சிலரை வாலின் அடியாலும், சிலரைக் கொம்புகளால் கிழித்தும்,",
        '13.23': "சிலரை வேகத்தாலும், சிலரை முழக்கத்தாலும் சுழற்சியாலும், சிலரை மூச்சுக் காற்றாலும் தரையில் வீழ்த்தினான்.",
        '13.24': "பிரமத கணங்களின் படையை வீழ்த்தி அந்த அசுரன் மகாதேவியின் சிங்கத்தைக் கொல்ல ஓடினான். அப்போது அம்பிகை கோபம் கொண்டாள்.",
        '13.25': "மாவீரனான அவனும் கோபத்துடன் குளம்புகளால் பூமியை மிதித்து, கொம்புகளால் உயர்ந்த மலைகளை எறிந்து முழங்கினான்.",
        '13.26': "அவனது வேகத்தாலும் சுழற்சியாலும் மிதிக்கப்பட்ட பூமி பிளவுபட்டது; வாலின் அடிபட்ட கடல் எல்லாப் பக்கமும் பொங்கி வழிந்தது.",
        '13.27': "அசைக்கும் கொம்புகளால் கிழிக்கப்பட்ட மேகங்கள் துண்டுதுண்டாயின; அவனது மூச்சுக் காற்றால் எறியப்பட்ட மலைகள் நூற்றுக்கணக்கில் வானிலிருந்து விழுந்தன.",
        '13.28': "இவ்வாறு கோபத்தால் பொங்கித் தன்மீது பாய்ந்துவரும் மகா அசுரனைக் கண்டு சண்டிகை அவனைக் கொல்லக் கோபம் கொண்டாள்.",
        '13.29': "அவள் அவன் மீது பாசத்தை வீசி அந்த மகா அசுரனைக் கட்டினாள். பெரும்போரில் கட்டுண்ட அவன் எருமை வடிவத்தைக் கைவிட்டான்.",
        '13.30': "அப்போது அவன் உடனே சிங்கமானான். அம்பிகை அதன் தலையை வெட்டிக்கொண்டிருக்கும்போதே கையில் வாளுடன் ஒரு மனிதன் தோன்றினான்.",
        '13.31': "உடனே தேவி அந்த மனிதனை வாள் கேடயத்துடன் அம்புகளால் வெட்டினாள். அப்போது அவன் பெரிய யானையானான்.",
        '13.32': "துதிக்கையால் அந்தப் பெருஞ்சிங்கத்தை இழுத்துப் பிளிறினான். அவன் இழுக்கும்போது தேவி வாளால் அவனது துதிக்கையை வெட்டினாள்.",
        '13.33': "பின்னர் அந்த மகா அசுரன் மீண்டும் எருமை உடலை எடுத்து, முன்போலவே அசையும் அசையாப் பொருள்களுடன் மூவுலகையும் கலக்கினான்.",
        '13.34': "அப்போது கோபம் கொண்ட உலக அன்னை சண்டிகை சிறந்த பானத்தை மீண்டும் மீண்டும் அருந்தினாள்; சிவந்த கண்களுடன் சிரித்தாள்.",
        '13.35': "வலிமை, வீரம் ஆகியவற்றின் செருக்கால் வெறிகொண்ட அந்த அசுரனும் முழங்கி, கொம்புகளால் மலைகளைச் சண்டிகையை நோக்கி எறிந்தான்.",
        '13.36': "அவன் எறிந்தவற்றை அம்புக் கூட்டங்களால் பொடியாக்கியபடி, மயக்கத்தால் சிவந்த முகத்துடன் தடுமாறும் சொற்களில் அவள் அவனிடம் கூறினாள்.",
        '13.37': "தேவி கூறினாள்:",
        '13.38': "மூடனே, நான் இந்த மதுவை அருந்தும் வரை கணப்பொழுது முழங்கு, முழங்கு. இங்கேயே என்னால் நீ கொல்லப்பட்டதும் விரைவில் தேவர்கள் முழங்குவர்.",
        '13.39': "ரிஷி கூறினார்:",
        '13.40': "இவ்வாறு கூறி அவள் பாய்ந்து அந்த மகா அசுரன் மீது ஏறி, காலால் அவனது கழுத்தை மிதித்து, சூலத்தால் அவனைக் குத்தினாள்.",
        '13.41': "அப்போது அவளது பாதத்தின் கீழ் அழுத்தப்பட்ட அவன் தன் வாயிலிருந்தே பாதி மட்டுமே வெளிவந்தான்; தேவியின் வல்லமை அவனை அப்படியே பிடித்து நிறுத்தியது.",
        '13.42': "பாதி மட்டுமே வெளிவந்து அப்படியே போரிட்டுக்கொண்டிருந்த அந்த மகா அசுரனின் தலையைத் தேவி தன் பெரிய வாளால் வெட்டி வீழ்த்தினாள்.",
        '13.43': "அப்போது ஓலமிட்டபடி அந்த அசுரப் படை முழுவதும் அழிந்தது; எல்லாத் தேவகணங்களும் பெருமகிழ்ச்சி அடைந்தனர்.",
        '13.44': "தேவர்கள் தெய்வீக மகரிஷிகளுடன் சேர்ந்து அந்தத் தேவியைத் துதித்தனர்; கந்தர்வத் தலைவர்கள் பாடினர், அப்ஸரஸ் கூட்டங்கள் நடனமாடினர்.",
        '13.45': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் தேவீ மாஹாத்ம்யத்தில் \"மஹிஷாஸுர வதம்\" என்னும் மூன்றாம் அத்தியாயம் நிறைவுற்றது.",
        '14.0': "தியானம்: கரிய மேகம் போன்ற ஒளியுடையவளும், கடைக்கண் பார்வையால் பகைவர் கூட்டத்திற்கு அச்சம் தருபவளும், முடியில் பிறைச்சந்திரனைக் கட்டியவளும், சங்கு, சக்கரம், வாள், திரிசூலம் ஆகியவற்றைக் கைகளில் ஏந்தியவளும், முக்கண்ணியும், சிங்கத்தின் தோளில் ஏறியவளும், தன் ஒளியால் மூவுலகையும் நிரப்புபவளும், தேவர்கள் சூழ்ந்தவளும், ஸித்தியை விரும்புவோரால் வணங்கப்படுபவளுமான ஜயா எனும் துர்கையைத் தியானிக்க வேண்டும்.",
        '14.1': "ரிஷி கூறினார்:",
        '14.2': "மிக வலிமையான அந்தத் தீயவனும் தேவர்களின் பகைவர் படையும் தேவியால் கொல்லப்பட்டபோது, இந்திரன் முதலான தேவகணங்கள் வணக்கத்தால் தாழ்ந்த கழுத்தும் தோள்களும் உடையவர்களாய், மகிழ்ச்சியால் மயிர்சிலிர்த்த அழகிய உடல்களுடன் சொற்களால் அவளைத் துதித்தனர்.",
        '14.3': "தன் ஆத்ம சக்தியால் இவ்வுலகை நிறைத்தவளும், எல்லாத் தேவகணங்களின் சக்தித் தொகுப்பையே வடிவாகக் கொண்டவளும், எல்லாத் தேவர்களாலும் மகரிஷிகளாலும் வணங்கத்தக்கவளுமான அந்த அம்பிகையைப் பக்தியுடன் வணங்குகிறோம். அவள் எங்களுக்கு நன்மைகளை அருளட்டும்.",
        '14.4': "யாருடைய ஒப்பற்ற மகிமையையும் வலிமையையும் பகவான் அனந்தனோ, பிரம்மாவோ, ஹரனோ சொல்ல இயலாதோ, அந்தச் சண்டிகை முழு உலகையும் காப்பதற்கும் தீமையின் அச்சத்தை அழிப்பதற்கும் திருவுளம் கொள்ளட்டும்.",
        '14.5': "புண்ணியவான்களின் வீடுகளில் தானே திருமகளாகவும், பாவிகளின் வீடுகளில் அலக்ஷ்மியாகவும், அறிஞர்களின் இதயங்களில் புத்தியாகவும், நல்லோரிடம் ஶ்ரத்தையாகவும், உயர்குடியினரிடம் நாணமாகவும் இருக்கும் உன்னை வணங்குகிறோம். தேவியே, உலகைக் காப்பாற்று.",
        '14.6': "தேவியே, சிந்தனைக்கு எட்டாத உனது இந்த வடிவத்தை எப்படி வர்ணிப்போம்? அசுரர்களை அழிக்கும் உனது அளவற்ற மிகுந்த வீரத்தை எப்படி? அசுரர், தேவர் முதலான எல்லாக் கூட்டங்களுக்கிடையே போர்களில் நீ செய்த அற்புதச் செயல்களை எப்படி?",
        '14.7': "நீயே எல்லா உலகங்களுக்கும் காரணம்; மூன்று குணங்களும் உடையவளாயினும் அவற்றின் குறைகள் உன்னிடம் காணப்படுவதில்லை; ஹரி, ஹரன் முதலியோருக்கும் நீ எல்லையற்றவள். நீயே அனைத்திற்கும் புகலிடம்; இவ்வுலகம் முழுவதும் உன் அம்சமே; நீயே வெளிப்படாத, ஆதியான பரம ப்ரக்ருதி.",
        '14.8': "தேவியே, யாருடைய உச்சரிப்பால் எல்லா யாகங்களிலும் தேவர் கூட்டம் முழுவதும் திருப்தி அடைகிறதோ அந்த ஸ்வாஹா நீயே; பித்ருக்களின் திருப்திக்கும் நீயே காரணம்; ஆகவேதான் மக்கள் உன்னை ஸ்வதா என்றும் உச்சரிக்கின்றனர்.",
        '14.9': "தேவியே, முக்திக்குக் காரணமானவளும் சிந்தனைக்கு எட்டாத மகாவிரதங்கள் உடையவளுமான உன்னைப் புலன்களை நன்கு அடக்கியவர்களும், தத்துவத்தின் சாரத்தில் நிலைத்தவர்களும், எல்லாக் குறைகளையும் நீக்கியவர்களுமான மோக்ஷத்தை நாடும் முனிவர்கள் பயில்கின்றனர்; அந்தப் பகவதியான பரம வித்யை நீயே.",
        '14.10': "நீ ஒலியின் வடிவினள்; மிகத் தூய்மையான ரிக், யஜுஸ் வேதங்களுக்கும், உத்கீதத்தால் இனிய பதபாடம் கொண்ட ஸாமங்களுக்கும் நீயே களஞ்சியம். நீயே மூன்று வேதங்களின் வடிவான பகவதீ தேவி; உலகைப் பேணுவதற்காக வார்த்தை (வாழ்வாதாரம்) நீயே; எல்லா உலகங்களின் பெருந்துயரை அழிப்பவளும் நீயே.",
        '14.11': "தேவியே, எல்லா ஶாஸ்திரங்களின் சாரத்தையும் அறியச் செய்யும் மேதை நீயே. கடக்க அரிய ஸம்ஸாரக் கடலைக் கடக்கப் பற்றற்ற படகான துர்கை நீயே. கைடபனின் பகைவனான விஷ்ணுவின் இதயத்தையே ஒரே உறைவிடமாகக் கொண்ட ஸ்ரீ நீயே; சந்திரனை முடியில் கொண்ட ஶிவனிடம் நிலைகொண்ட கௌரியும் நீயே.",
        '14.12': "புன்முறுவலுடன் கூடிய, களங்கமற்ற, முழுநிலவு போன்ற, சிறந்த பொன்னின் ஒளியால் அழகிய உன் முகத்தைத் திடீரெனக் கண்டும், மஹிஷாஸுரன் கோபத்தால் அதைத் தாக்கியது மிகவும் வியப்பானது.",
        '14.13': "தேவியே, புருவச் சுளிப்பால் பயங்கரமான, உதிக்கும் சந்திரன் போலச் சிவந்த உன் கோப முகத்தைக் கண்டும் மஹிஷன் உடனே உயிர் விடவில்லை என்பது இன்னும் விசித்திரம்; கோபம் கொண்ட யமனைக் கண்டு யார்தான் உயிர் வாழ்வர்?",
        '14.14': "தேவியே, அருள்புரி. பரமையான நீ மகிழ்ந்தால் வளர்ச்சிக்குக் காரணமாகிறாய்; கோபம் கொண்டால் உடனே குலங்களையே அழிக்கிறாய். மஹிஷாஸுரனின் மிகப் பெரிய படை அழிக்கப்பட்டதால் இது இப்போதே தெரிந்தது.",
        '14.15': "வளம் அருளும் நீ யாரிடம் எப்போதும் மகிழ்ந்திருக்கிறாயோ அவர்களே நாடுகளில் மதிக்கப்படுகின்றனர்; அவர்களுக்கே செல்வம், அவர்களுக்கே புகழ்; அவர்களின் அறச்செயல்கள் குன்றுவதில்லை; பணிவான மக்கள், பணியாளர், மனைவி உடைய அவர்களே பாக்கியசாலிகள்.",
        '14.16': "தேவியே, உன் அருளாலேயே புண்ணியவான் மிகுந்த மதிப்புடன் தினமும் எல்லா அறச் செயல்களையும் செய்கிறான்; அதனால் சொர்க்கம் அடைகிறான். ஆகவே தேவியே, மூவுலகிலும் பலனை அருள்பவள் நீயே அல்லவா?",
        '14.17': "துர்கையே, நினைக்கப்பட்டால் எல்லா உயிர்களின் அச்சத்தையும் நீக்குகிறாய்; நலமுடன் இருப்பவர்கள் நினைத்தால் மிக நல்ல புத்தியை அருள்கிறாய். வறுமை, துன்பம், அச்சம் ஆகியவற்றை நீக்குபவளே, எல்லோருக்கும் நன்மை செய்ய எப்போதும் இரங்கிய உள்ளம் கொண்டவள் உன்னைத் தவிர வேறு யார்?",
        '14.18': "\"இவர்களைக் கொன்றால் உலகம் சுகம் அடையும்; இவர்கள் நீண்ட காலம் நரகத்தில் இருக்கும் அளவு பாவம் செய்திருந்தாலும் போரில் மரணமடைந்து சொர்க்கம் செல்லட்டும்\" — என்று எண்ணியே, தேவியே, நீ பகைவர்களைக் கொல்கிறாய்.",
        '14.19': "பார்வையாலேயே எல்லா அசுரர்களையும் சாம்பலாக்காமல், பகைவர் மீது ஆயுதத்தை ஏன் எய்கிறாய்? \"பகைவர்களும் என் ஆயுதத்தால் தூய்மையடைந்து மேலான உலகங்களை அடையட்டும்\" — இவ்வாறு அவர்களிடமும் உன் எண்ணம் மிகக் கருணையானது.",
        '14.20': "உன் வாளின் ஒளிக் குவியலின் கொடிய மின்னல்களாலும் சூல முனையின் ஒளித் திரளாலும் அசுரர்களின் கண்கள் அழியவில்லை என்றால், அதற்குக் காரணம் அவர்கள் ஒளிமிக்க சந்திரனின் துண்டு போன்ற உன் முகத்தைப் பார்த்துக்கொண்டிருந்ததே.",
        '14.21': "தேவியே, தீயோரின் நடத்தையை அடக்குவதே உன் இயல்பு; உனது இந்த வடிவம் சிந்தனைக்கு எட்டாதது, பிறருடன் ஒப்பிட முடியாதது; தேவர்களின் வீரத்தைப் பறித்தவர்களை அழிப்பது உன் வீரம்; இவ்வாறு பகைவர்களிடமும் நீ கருணையையே காட்டியுள்ளாய்.",
        '14.22': "உன் இந்த வீரத்திற்கு எதனுடன் ஒப்புமை? பகைவர்களுக்கு அச்சம் தருவதாயினும் மிக இனிய இத்தகைய வடிவம் வேறெங்கே உள்ளது? வரம் அருளும் தேவியே, உள்ளத்தில் கருணையும் போரில் கடுமையும் மூவுலகிலும் உன்னிடம் மட்டுமே காணப்படுகின்றன.",
        '14.23': "பகைவர்களை அழித்து இந்த மூவுலகம் முழுவதையும் நீ காத்தாய்; போர்முனையில் அந்தப் பகைக் கூட்டங்களைக் கொன்று அவர்களையும் சொர்க்கத்திற்கு அனுப்பினாய்; வெறிகொண்ட தேவப் பகைவர்களால் எங்களுக்கு உண்டான அச்சத்தையும் நீக்கினாய். உனக்கு நமஸ்காரம்.",
        '14.24': "தேவியே, சூலத்தால் எங்களைக் காப்பாற்று; அம்பிகையே, வாளால் காப்பாற்று; மணியோசையாலும் வில்நாணின் ஒலியாலும் எங்களைக் காப்பாற்று.",
        '14.25': "சண்டிகையே, கிழக்கிலும் மேற்கிலும் காப்பாற்று; தெற்கில் காப்பாற்று; ஈஶ்வரியே, உன் சூலத்தைச் சுழற்றி வடக்கிலும் காப்பாற்று.",
        '14.26': "மூவுலகிலும் திரியும் உன் சாந்த வடிவங்களாலும், மிகக் கொடிய வடிவங்களாலும் எங்களையும் பூமியையும் காப்பாற்று.",
        '14.27': "அம்பிகையே, தளிர் போன்ற உன் கைகளில் உள்ள வாள், சூலம், கதை முதலிய எல்லா ஆயுதங்களாலும் எங்களை எல்லாப் பக்கங்களிலும் காப்பாற்று.",
        '14.28': "ரிஷி கூறினார்:",
        '14.29': "இவ்வாறு தேவர்களால் துதிக்கப்பட்டு, நந்தன வனத்தில் மலர்ந்த தெய்வீக மலர்களாலும் சந்தனம் முதலிய பூச்சுகளாலும் அர்ச்சிக்கப்பட்ட உலகைத் தாங்குபவள்,",
        '14.30': "எல்லாத் தேவர்களாலும் பக்தியுடன் தெய்வீகத் தூபங்களால் தூபம் காட்டப்பட்டு, மலர்ந்த முகத்துடன் வணங்கி நின்ற எல்லாத் தேவர்களிடமும் கூறினாள்.",
        '14.31': "தேவி கூறினாள்:",
        '14.32': "தேவர்களே, நீங்கள் அனைவரும் என்னிடமிருந்து எதை விரும்புகிறீர்களோ அதைக் கேளுங்கள்.",
        '14.33': "தேவர்கள் கூறினர்:",
        '14.34': "பகவதி அனைத்தையும் செய்துவிட்டாள்; எதுவும் மீதமில்லை,",
        '14.35': "ஏனெனில் எங்கள் பகைவனான இந்த மஹிஷாஸுரன் கொல்லப்பட்டான். இருப்பினும் மகேஶ்வரியே, நீ எங்களுக்கு வரம் தர வேண்டுமெனில்,",
        '14.36': "நாங்கள் நினைக்கும்போதெல்லாம் எங்கள் பெரும் ஆபத்துகளை அழிப்பாயாக. களங்கமற்ற முகமுடையவளே, எந்த மனிதன் இத்துதிகளால் உன்னைத் துதிப்பானோ,",
        '14.37': "அவனது செல்வம், வளம், சிறப்பு ஆகியவையும், பொருள், மனைவி முதலான செல்வங்களும் பெருகும்படி, அம்பிகையே, எங்களிடம் மகிழ்ந்தது போல அவனிடமும் எப்போதும் மகிழ்ந்திருப்பாயாக.",
        '14.38': "ரிஷி கூறினார்:",
        '14.39': "அரசே, இவ்வாறு உலகிற்காகவும் தங்களுக்காகவும் தேவர்களால் மகிழ்விக்கப்பட்ட பத்ரகாளி \"அப்படியே ஆகட்டும்\" என்று கூறி மறைந்தாள்.",
        '14.40': "அரசே, மூவுலகின் நலனை விரும்பும் அந்தத் தேவி முன்பு தேவர்களின் உடல்களிலிருந்து எவ்வாறு தோன்றினாள் என்பதை இவ்வாறு உனக்குக் கூறினேன்.",
        '14.41': "மீண்டும் தீய அசுரர்களையும் ஶும்ப நிஶும்பர்களையும் கொல்வதற்காக அவள் கௌரியின் உடலிலிருந்து எவ்வாறு தோன்றினாளோ,",
        '14.42': "உலகங்களைக் காப்பதற்காக, தேவர்களுக்கு உதவுபவளாக — அதை நான் கூறுவதைக் கேள்; நடந்தபடியே உனக்குச் சொல்கிறேன்.",
        '14.43': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் தேவீ மாஹாத்ம்யத்தில் \"ஶக்ராதி ஸ்துதி\" என்னும் நான்காம் அத்தியாயம் நிறைவுற்றது.",
        '15.0': "உத்தர சரித்திரம்: ரிஷி ருத்ரன், தேவதை மஹாஸரஸ்வதீ, சந்தஸ் அனுஷ்டுப், சக்தி பீமா, பீஜம் ப்ராமரீ, தத்வம் சூரியன், ஸ்வரூபம் ஸாமவேதம்; மஹாஸரஸ்வதீ ப்ரீதிக்காக உத்தர சரித்திர ஜபத்தில் (அல்லது ஹோமத்தில்) வினியோகம்.",
        '15.1': "ஓம். தாமரைக் கரங்களில் மணி, சூலம், கலப்பை, சங்கு, உலக்கை, சக்கரம், வில், அம்பு ஏந்தியவளும், மழைக்கால முடிவில் ஒளிரும் சந்திரனைப் போன்ற ஒளியுடையவளும், கௌரியின் உடலிலிருந்து தோன்றியவளும், மூவுலகுக்கும் ஆதாரமானவளும், சும்பன் முதலிய அசுரர்களை அழித்தவளுமான மகாஸரஸ்வதியை இங்கே தியானிக்கிறேன்.",
        '15.2': "ரிஷி கூறினார்:",
        '15.3': "முன்னொரு காலத்தில் சும்ப நிசும்பர் என்னும் அசுரர்கள் தம் செருக்கையும் வலிமையையும் சார்ந்து, சசீபதியான இந்திரனிடமிருந்து மூவுலகையும் யக்ஞ பாகங்களையும் பறித்துக்கொண்டனர்.",
        '15.4': "அவ்விருவருமே சூரியனின் அதிகாரத்தையும், அவ்வாறே சந்திரன், குபேரன், யமன், வருணன் ஆகியோரின் அதிகாரங்களையும் ஏற்றுக்கொண்டனர்.",
        '15.5': "அவர்களே வாயுவின் வளத்தையும் அக்னியின் பணியையும் ஏற்றனர். அப்போது தேவர்கள் துரத்தப்பட்டு, தோற்று, அரசிழந்து,",
        '15.6': "அவ்விரு மகாசுரர்களால் அதிகாரம் பறிக்கப்பட்டு எல்லோரும் விரட்டப்பட்டு, வெல்லப்பட முடியாத அந்தத் தேவியை நினைத்தனர்.",
        '15.7': "(அவர்கள் எண்ணினர்:) “‘ஆபத்துகளில் என்னை நினைக்கும்போது அக்கணமே உங்கள் பெரும் ஆபத்துகள் அனைத்தையும் அழிப்பேன்’ என்று அவள் நமக்கு வரம் தந்திருக்கிறாள்.”",
        '15.8': "இவ்வாறு தீர்மானித்துத் தேவர்கள் மலைகளின் அரசனான இமயத்துக்குச் சென்று, அங்கே விஷ்ணுமாயையான தேவியைத் துதித்தனர்.",
        '15.9': "தேவர்கள் கூறினர்:",
        '15.10': "தேவிக்கு, மகாதேவிக்கு நமஸ்காரம்; மங்கள வடிவான சிவைக்கு எப்போதும் நமஸ்காரம். பிரக்ருதிக்கு, பத்ரைக்கு நமஸ்காரம். அடக்கத்துடன் நாங்கள் அவளை வணங்குகிறோம்.",
        '15.11': "ரௌத்ரிக்கு, நித்யைக்கு, கௌரிக்கு, தாத்ரிக்கு மீண்டும் மீண்டும் நமஸ்காரம்; நிலவொளியானவளுக்கு, சந்திர வடிவினளுக்கு, இன்ப வடிவினளுக்கு எப்போதும் நமஸ்காரம்.",
        '15.12': "வணங்குவோருக்கு வளர்ச்சியும் வெற்றியுமான கல்யாணியை மீண்டும் மீண்டும் வணங்குகிறோம். நைர்ருதியும், அரசர்களின் லக்ஷ்மியும், சர்வாணியுமான உனக்கு மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.13': "துன்பங்களைக் கடக்கச் செய்யும் துர்கைக்கு, சாரமானவளுக்கு, எல்லாவற்றையும் செய்பவளுக்கு, க்யாதிக்கு, அவ்வாறே க்ருஷ்ணைக்கும் தூம்ரைக்கும் எப்போதும் நமஸ்காரம்.",
        '15.14': "மிக மென்மையானவளும் மிகக் கடுமையானவளுமான அவளுக்குத் தலைவணங்கி மீண்டும் மீண்டும் நமஸ்கரிக்கிறோம். உலகுக்கு ஆதாரமானவளும் செயல் வடிவினளுமான தேவிக்கு மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.15': "எல்லா உயிர்களிலும் விஷ்ணுமாயை என்று அழைக்கப்பட்டு நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.16': "எல்லா உயிர்களிலும் சேதனை (உணர்வு) என்று அழைக்கப்பட்டு நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.17': "எல்லா உயிர்களிலும் புத்தியின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.18': "எல்லா உயிர்களிலும் உறக்கத்தின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.19': "எல்லா உயிர்களிலும் பசியின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.20': "எல்லா உயிர்களிலும் நிழலின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.21': "எல்லா உயிர்களிலும் சக்தியின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.22': "எல்லா உயிர்களிலும் தாகத்தின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.23': "எல்லா உயிர்களிலும் பொறுமையின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.24': "எல்லா உயிர்களிலும் பிறப்பின் (ஜாதியின்) வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.25': "எல்லா உயிர்களிலும் நாணத்தின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.26': "எல்லா உயிர்களிலும் அமைதியின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.27': "எல்லா உயிர்களிலும் சிரத்தையின் (நம்பிக்கையின்) வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.28': "எல்லா உயிர்களிலும் காந்தியின் (ஒளியின்) வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.29': "எல்லா உயிர்களிலும் லக்ஷ்மியின் (செல்வத்தின்) வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.30': "எல்லா உயிர்களிலும் வாழ்வுத் தொழிலின் (வ்ருத்தியின்) வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.31': "எல்லா உயிர்களிலும் நினைவின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.32': "எல்லா உயிர்களிலும் கருணையின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.33': "எல்லா உயிர்களிலும் மனநிறைவின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.34': "எல்லா உயிர்களிலும் தாயின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.35': "எல்லா உயிர்களிலும் மயக்கத்தின் (பிராந்தியின்) வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.36': "உயிர்களின் புலன்களை ஆள்பவளும், எல்லா உயிர்களிலும் எப்போதும் நிறைந்திருப்பவளுமான வ்யாப்தி தேவிக்கு மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.37': "சித் (உணர்வு) வடிவில் இந்த உலகம் முழுவதையும் வியாபித்து நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '15.38': "முன்பு விருப்பம் நிறைவேறத் தேவர்களால் துதிக்கப்பட்டவளும், தேவேந்திரனால் நாள்தோறும் வழிபடப்பட்டவளும், நலத்துக்குக் காரணமானவளுமான அந்த ஈச்வரி எங்களுக்கு நன்மையும் மங்களமும் செய்யட்டும்; எங்கள் ஆபத்துகளை அழிக்கட்டும்.",
        '15.39': "செருக்குற்ற அசுரர்களால் துன்புறுத்தப்பட்ட தேவர்களான எங்களால் இப்போது வணங்கப்படுபவளும், பக்தியால் பணிந்தோர் நினைத்த கணமே எங்கள் ஆபத்துகள் அனைத்தையும் அழிப்பவளுமான அந்த ஈச்வரி (எங்களைக் காக்கட்டும்).",
        '15.40': "ரிஷி கூறினார்:",
        '15.41': "அரசகுமாரனே, தேவர்கள் இவ்வாறு துதித்துக்கொண்டிருந்தபோது பார்வதி ஜாஹ்னவியின் (கங்கையின்) நீரில் நீராட அங்கே வந்தாள்.",
        '15.42': "அழகிய புருவமுடைய அவள் தேவர்களிடம் “இங்கே நீங்கள் யாரைத் துதிக்கிறீர்கள்?” என்று கேட்டாள். அப்போது அவள் உடலின் கோசத்திலிருந்து வெளிப்பட்ட சிவை கூறினாள்:",
        '15.43': "“சும்ப அசுரனால் விரட்டப்பட்டு, போரில் நிசும்பனால் தோற்கடிக்கப்பட்டு ஒன்றுகூடிய தேவர்கள் இந்தத் துதியை எனக்கே செய்கின்றனர்.”",
        '15.44': "பார்வதியின் உடல் கோசத்திலிருந்து அம்பிகை வெளிப்பட்டதால், எல்லா உலகங்களிலும் அவள் ‘கௌசிகீ’ என்று போற்றப்படுகிறாள்.",
        '15.45': "அவள் வெளிப்பட்டதும் அந்தப் பார்வதியும் கருநிறமானாள்; இமயத்தில் வசிக்கும் அவள் ‘காளிகா’ என்று புகழ்பெற்றாள்.",
        '15.46': "அப்போது சும்ப நிசும்பரின் பணியாளர்களான சண்டனும் முண்டனும் மிக மனங்கவரும் மேலான வடிவம் தாங்கிய அம்பிகையைக் கண்டனர்.",
        '15.47': "அவர்கள் சும்பனிடம் கூறினர்: “மகாராஜா, மிக அழகிய ஒரு பெண் இமயத்தை ஒளிரச் செய்தவாறு அங்கே இருக்கிறாள்.”",
        '15.48': "“அத்தகைய உயர்ந்த அழகை எங்கும் எவரும் கண்டதில்லை. அசுரேச்வரனே, அந்தத் தேவி யார் என்று அறிந்து அவளைக் கைக்கொள்.”",
        '15.49': "“அசுர அரசே, மிக அழகிய அங்கங்களுடைய, தன் ஒளியால் திசைகளை ஒளிரச் செய்யும் அந்தப் பெண்களில் ரத்தினம் அங்கே இருக்கிறாள்; நீ அவளைக் காண வேண்டும்.”",
        '15.50': "“பிரபுவே, மூவுலகிலும் உள்ள ரத்தினங்கள், மணிகள், யானைகள், குதிரைகள் முதலிய அனைத்தும் இப்போது உன் இல்லத்தில் ஒளிர்கின்றன.”",
        '15.51': "“யானைகளில் ரத்தினமான ஐராவதம் இந்திரனிடமிருந்து கொண்டுவரப்பட்டது; அவ்வாறே இந்தப் பாரிஜாத மரமும் உச்சைச்ரவஸ் என்னும் குதிரையும்.”",
        '15.52': "“பிரம்மாவுக்கு உரியதாக இருந்த, அன்னங்கள் பூட்டிய அற்புதமான ரத்தினம் போன்ற இந்த விமானம் இங்கே கொண்டுவரப்பட்டு உன் முற்றத்தில் நிற்கிறது.”",
        '15.53': "“மகாபத்மம் என்னும் இந்த நிதி செல்வத்தின் தலைவனான குபேரனிடமிருந்து கொண்டுவரப்பட்டது; கடல் மகரந்தமுள்ள வாடாத தாமரை மாலையைத் தந்தது.”",
        '15.54': "“பொன்னைப் பொழியும் வருணனின் குடை உன் இல்லத்தில் இருக்கிறது; முன்பு பிரஜாபதிக்கு உரியதாக இருந்த இந்தச் சிறந்த தேரும் இருக்கிறது.”",
        '15.55': "“ஈசனே, மிருத்யுவின் ‘உத்க்ராந்திதா’ என்னும் சக்தி ஆயுதத்தை நீ பறித்துக்கொண்டாய்; நீரின் அரசனான வருணனின் பாசம் உன் தம்பியின் வசம் இருக்கிறது.”",
        '15.56': "“கடலில் பிறந்த எல்லா வகை ரத்தினங்களும் நிசும்பனுடையவை; அக்னியும் நெருப்பால் தூய்மையான இரண்டு ஆடைகளை உனக்குத் தந்தான்.”",
        '15.57': "“அசுர அரசே, இவ்வாறு எல்லா ரத்தினங்களும் உனக்குக் கொண்டுவரப்பட்டுள்ளன. மங்களமான இந்தப் பெண்களில் ரத்தினத்தை நீ ஏன் கைக்கொள்ளவில்லை?”",
        '15.58': "ரிஷி கூறினார்:",
        '15.59': "சண்ட முண்டரின் இச்சொற்களைக் கேட்டுச் சும்பன் அப்போது ஸுக்ரீவன் என்னும் மகாசுரனைத் தூதனாகத் தேவியிடம் அனுப்பினான்.",
        '15.60': "“சென்று என் சொல்லாக அவளிடம் இன்னின்னவாறு கூறு; அவள் மகிழ்வுடன் வரும்படி விரைவில் செயல்படு.”",
        '15.61': "அவன் மலையின் மிக அழகிய இடத்தில் அவள் இருந்த இடத்துக்குச் சென்று, மென்மையான இனிய சொற்களால் தேவியிடம் பேசினான்.",
        '15.62': "தூதன் கூறினான்:",
        '15.63': "“தேவியே, அசுரர் தலைவனான சும்பன் மூவுலகுக்கும் பரமேச்வரன். அவனால் அனுப்பப்பட்ட தூதனான நான் உன்னிடம் இங்கே வந்துள்ளேன்.”",
        '15.64': "“எல்லா தேவ இனங்களிலும் எவனுடைய கட்டளை எப்போதும் தடையின்றி நடக்கிறதோ, அசுரர்களின் பகைவர் அனைவரையும் எவன் வென்றானோ, அவன் சொல்வதைக் கேள்.”",
        '15.65': "“(சும்பன் கூறுகிறான்:) மூவுலகம் முழுதும் என்னுடையது; தேவர்கள் என் வசத்தில் உள்ளனர். யக்ஞ பாகங்கள் அனைத்தையும் தனித்தனியே நானே அனுபவிக்கிறேன்.”",
        '15.66': "“மூவுலகின் சிறந்த ரத்தினங்கள் அனைத்தும் முழுமையாக என் வசம் உள்ளன; அவ்வாறே தேவேந்திரனின் வாகனமான யானை ரத்தினத்தையும் நான் கவர்ந்தேன்.”",
        '15.67': "“பாற்கடலைக் கடைந்தபோது பிறந்த உச்சைச்ரவஸ் என்னும் குதிரை ரத்தினத்தை அமரர்கள் வணங்கி எனக்கு ஒப்படைத்தனர்.”",
        '15.68': "“அழகியே, தேவர்கள், கந்தர்வர்கள், நாகர்களிடையே ரத்தினம் போன்ற மற்றப் பொருள்கள் அனைத்தும் என்னிடமே உள்ளன.”",
        '15.69': "“தேவியே, உலகில் உன்னைப் பெண்களில் ரத்தினமாக நாங்கள் கருதுகிறோம். ரத்தினங்களை அனுபவிப்பவர்கள் நாங்களே என்பதால் நீ எங்களிடம் வா.”",
        '15.70': "“அலையும் கடைக்கண் பார்வையுடையவளே, நீ உண்மையில் ரத்தினமானவள் என்பதால் என்னையோ, பெரும் வீரனான என் தம்பி நிசும்பனையோ மணந்துகொள்.”",
        '15.71': "“என்னை மணப்பதால் ஒப்பற்ற பேரரசுச் செல்வத்தைப் பெறுவாய். இதை அறிவால் நன்கு ஆராய்ந்து என் மனைவியாகு.”",
        '15.72': "ரிஷி கூறினார்:",
        '15.73': "இவ்வாறு கூறப்பட்டபோது, இந்த உலகைத் தாங்குபவளும் பகவதியும் பத்ரையுமான துர்கா தேவி உள்ளுக்குள் புன்னகைத்துக் கம்பீரமாகக் கூறினாள்.",
        '15.74': "தேவி கூறினாள்:",
        '15.75': "“நீ உண்மையையே கூறினாய்; இதில் சிறிதும் பொய் சொல்லவில்லை. சும்பன் மூவுலகின் தலைவன்; நிசும்பனும் அத்தகையவனே.”",
        '15.76': "“ஆனால் இவ்விஷயத்தில் நான் செய்த சபதத்தை எவ்வாறு பொய்யாக்குவேன்? சிற்றறிவால் முன்பு நான் செய்த சபதத்தைக் கேள்.”",
        '15.77': "“எவன் போரில் என்னை வெல்கிறானோ, எவன் என் செருக்கை அகற்றுகிறானோ, உலகில் எவன் எனக்கு நிகரான வலிமையுடையவனோ, அவனே என் கணவனாவான்.”",
        '15.78': "“ஆகவே சும்பனோ மகாசுரனான நிசும்பனோ இங்கே வரட்டும். என்னை வென்று விரைவில் என் கரம் பற்றட்டும்; தாமதம் ஏன்?”",
        '15.79': "தூதன் கூறினான்:",
        '15.80': "“தேவியே, நீ செருக்குற்றிருக்கிறாய்; என் முன் இவ்வாறு பேசாதே. மூவுலகிலும் எந்த ஆண் சும்ப நிசும்பர் முன் நிற்க முடியும்?”",
        '15.81': "“தேவியே, மற்ற அசுரர்களின் முன்கூடப் போரில் எல்லாத் தேவர்களும் நிற்க முடியாது; தனியொரு பெண்ணான நீ எம்மாத்திரம்?”",
        '15.82': "“இந்திரன் முதலிய எல்லாத் தேவர்களும் போரில் எவர் முன் நிற்கவில்லையோ, அந்தச் சும்பன் முதலியோர் முன் பெண்ணான நீ எப்படிச் செல்வாய்?”",
        '15.83': "“ஆகவே நான் சொன்னபடி நீயே சும்ப நிசும்பரிடம் செல்; கூந்தலைப் பற்றி இழுக்கப்பட்டு மதிப்பிழந்து செல்லாதே.”",
        '15.84': "தேவி கூறினாள்:",
        '15.85': "“அப்படியே: சும்பன் வலிமையானவன், நிசும்பன் மிகுந்த வீரமுடையவன். ஆனால் நான் என்ன செய்வேன்? ஆராயாமல் முன்பே சபதம் செய்துவிட்டேன்.”",
        '15.86': "“ஆகவே நீ சென்று நான் சொன்னதை எல்லாம் மதிப்புடன் அசுர அரசனிடம் தெரிவி; அவன் தகுந்ததைச் செய்யட்டும்.”",
        '15.87': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “தேவீ-தூத ஸம்வாதம்” என்னும் ஐந்தாம் அத்தியாயம் நிறைவுற்றது.",
        '16.0': "ஓம். நாகராஜனை ஆசனமாகக் கொண்டவளும், படங்களிலுள்ள பெரிய ரத்தின வரிசையின் ஒளியால் ஒளிரும் கொடி போன்ற உடலுடையவளும், சூரியனைப் போல் ஒளிர்பவளும், மூன்று கண்களால் விளங்குபவளும், ஜபமாலை, கலசம், கபாலம், தாமரை ஆகியவற்றைக் கைகளில் ஏந்தியவளும், பிறைச் சந்திரனை முடியில் அணிந்தவளும், எல்லாம் அறிந்த ஈசனான பைரவனின் மடியில் அமர்ந்தவளுமான பரா தேவி பத்மாவதியைத் தியானிக்கிறேன்.",
        '16.1': "ரிஷி கூறினார்:",
        '16.2': "தேவியின் சொற்களைக் கேட்டுச் சினம் நிறைந்த அந்தத் தூதன் திரும்பி வந்து அசுர அரசனிடம் அனைத்தையும் விரிவாகக் கூறினான்.",
        '16.3': "தூதனின் சொற்களைக் கேட்ட அசுர அரசன் சினத்துடன் அசுரர்களின் தலைவனான தூம்ரலோசனனிடம் கூறினான்:",
        '16.4': "“தூம்ரலோசனா, நீ உன் படையுடன் விரைந்து சென்று, அந்தக் கொடியவளைக் கூந்தலைப் பற்றி இழுத்துக் கலங்கச் செய்து பலவந்தமாகக் கொண்டு வா.”",
        '16.5': "“அவளைக் காக்க வேறு எவனாவது எழுந்தால், அவன் தேவனானாலும் யக்ஷனானாலும் கந்தர்வனானாலும் கொல்லப்பட வேண்டும்.”",
        '16.6': "ரிஷி கூறினார்:",
        '16.7': "இவ்வாறு கட்டளையிடப்பட்ட தூம்ரலோசனன் என்னும் அசுரன் அறுபதாயிரம் அசுரர்கள் சூழ விரைந்து புறப்பட்டான்.",
        '16.8': "பனிமலையில் இருந்த அந்தத் தேவியைக் கண்டு அவன் “சும்ப நிசும்பரிடம் வா” என்று உரக்கக் கூவினான்.",
        '16.9': "“இன்று நீ விருப்பத்துடன் என் தலைவனிடம் வராவிட்டால், கூந்தலைப் பற்றி இழுத்துக் கலங்கச் செய்து பலவந்தமாகக் கொண்டு செல்வேன்.”",
        '16.10': "தேவி கூறினாள்:",
        '16.11': "“அசுரர் தலைவனால் அனுப்பப்பட்டவனும், வலிமையுள்ளவனும், படை சூழ்ந்தவனுமான நீ இவ்வாறு என்னைப் பலவந்தமாகக் கொண்டு சென்றால் நான் உன்னை என்ன செய்ய முடியும்?”",
        '16.12': "ரிஷி கூறினார்:",
        '16.13': "இவ்வாறு கூறப்பட்ட அசுரன் தூம்ரலோசனன் அவளை நோக்கிப் பாய்ந்தான்; அம்பிகை வெறும் ‘ஹும்’ ஒலியாலேயே அவனைச் சாம்பலாக்கினாள்.",
        '16.14': "அப்போது சினமுற்ற அசுரர்களின் பெரும் படை மீது அம்பிகை கூரிய அம்புகளையும் சக்திகளையும் கோடரிகளையும் பொழிந்தாள்.",
        '16.15': "அப்போது தேவியின் வாகனமான சிங்கம் சினத்துடன் பிடரியை உலுக்கி அச்சந்தரும் கர்ஜனை செய்து அசுரப் படை மீது பாய்ந்தது.",
        '16.16': "சில அசுரர்களை அது பாதத்தின் அடியாலும், சிலரை வாயாலும், மற்றும் சில மகாசுரர்களைக் காலால் மிதித்தும் கொன்றது.",
        '16.17': "அந்தச் சிங்கம் சிலரின் வயிறுகளை நகங்களால் கிழித்தது; பாதத்தின் அடியால் மற்றவர்களின் தலைகளைத் துண்டித்தது.",
        '16.18': "மேலும் சிலரின் கைகளும் தலைகளும் அதனால் துண்டிக்கப்பட்டன; பிடரியை உலுக்கியவாறு அது மற்றவர்களின் வயிற்றிலிருந்து குருதியைப் பருகியது.",
        '16.19': "ஒரு கணத்தில் அந்தப் படை முழுவதும் மிகுந்த சினமுற்ற, தேவியின் வாகனமான அந்தப் பெரும் சிங்கத்தால் அழிக்கப்பட்டது.",
        '16.20': "அசுரன் தூம்ரலோசனன் தேவியால் கொல்லப்பட்டான் என்றும், அவன் படை முழுவதும் தேவியின் சிங்கத்தால் அழிக்கப்பட்டது என்றும் கேட்டு,",
        '16.21': "அசுரர் தலைவனான சும்பன் உதடுகள் துடிக்கும் அளவுக்குச் சினமுற்று, சண்டன் முண்டன் என்னும் இரு மகாசுரர்களுக்குக் கட்டளையிட்டான்:",
        '16.22': "“சண்டா, முண்டா, பெரும் படைகள் சூழ அங்கே சென்று அவளை விரைவில் இங்கே கொண்டு வாருங்கள்.”",
        '16.23': "“அவளைக் கூந்தலைப் பற்றி இழுத்தோ கட்டியோ கொண்டு வாருங்கள். போரில் உங்களுக்கு ஐயம் ஏற்பட்டால், எல்லா அசுரர்களும் எல்லா ஆயுதங்களாலும் அவளைக் கொல்லட்டும்.”",
        '16.24': "“அந்தக் கொடியவள் அடிபட்டு, சிங்கம் வீழ்த்தப்பட்டதும், அந்த அம்பிகையைப் பிடித்துக் கட்டி விரைவில் திரும்புங்கள்.”",
        '16.25': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “சும்ப நிசும்பரின் சேனாபதி தூம்ரலோசனன் வதம்” என்னும் ஆறாம் அத்தியாயம் நிறைவுற்றது.",
        '17.0': "ஓம். ரத்தின பீடத்தில் அமர்ந்து கிளியின் இனிய மொழியைக் கேட்பவளும், கருநீல மேனியளும், ஒரு பாதத்தைத் தாமரையில் வைத்தவளும், பிறைச் சந்திரனை அணிந்தவளும், வீணை மீட்டுபவளும், கல்ஹார மலர் மாலை அணிந்தவளும், ஒளிரும் ரவிக்கையைக் கட்டியவளும், சிவந்த ஆடை உடுத்தவளும், சங்குப் பாத்திரம் ஏந்தியவளும், இனிய மதுவின் மயக்கம் கொண்டவளும், நெற்றியில் திலகத்தால் ஒளிர்பவளுமான மாதங்கியைத் தியானிக்கிறேன்.",
        '17.1': "ரிஷி கூறினார்:",
        '17.2': "அப்போது கட்டளை பெற்ற அந்த அசுரர்கள் சண்ட முண்டரைத் தலைமையாகக் கொண்டு நால்வகைப் படையுடன் ஆயுதங்களை உயர்த்தியவாறு புறப்பட்டனர்.",
        '17.3': "மலையரசனின் பெரிய பொன் சிகரத்தில் சிங்கத்தின் மீது அமர்ந்து புன்னகைக்கும் தேவியை அவர்கள் கண்டனர்.",
        '17.4': "அவளைக் கண்டு அவர்கள் பிடிக்க முனைந்தனர்; சிலர் விற்களை வளைத்தனர், சிலர் வாள்களை ஏந்தினர், மற்றும் சிலர் அவள் அருகே வந்தனர்.",
        '17.5': "அப்போது அம்பிகை அந்தப் பகைவர்கள் மீது கடும் சினம் கொண்டாள்; சினத்தால் அவள் முகம் மையைப் போலக் கருத்தது.",
        '17.6': "சுளித்த புருவங்களால் வளைந்த அவள் நெற்றியிலிருந்து உடனே கோர முகமுடைய, வாளும் பாசமும் ஏந்திய காளி வெளிப்பட்டாள்.",
        '17.7': "அவள் விசித்திரமான கட்வாங்கத்தை ஏந்தி, மனிதத் தலை மாலையை அணிந்து, புலித்தோலை உடுத்து, வற்றிய சதையால் மிகக் கொடூரமாக இருந்தாள்.",
        '17.8': "அவள் வாய் மிக அகன்றிருந்தது; தொங்கும் நாக்கால் அச்சமூட்டினாள்; கண்கள் உட்குழிந்து சிவந்திருந்தன; கர்ஜனையால் திசைகளை நிரப்பினாள்.",
        '17.9': "அவள் வேகமாகப் பாய்ந்து மகாசுரர்களைக் கொன்றவாறு, தேவர்களின் பகைவர்களான அந்தப் படையை விழுங்கினாள்.",
        '17.10': "பின்புறக் காவலர், அங்குசம் ஏந்திய பாகர், வீரர், மணிகள் ஆகியவற்றுடன் யானைகளை ஒரே கையால் எடுத்து அவள் வாயில் எறிந்தாள்.",
        '17.11': "அவ்வாறே குதிரைகளுடன் வீரர்களையும், சாரதியுடன் தேர்களையும் வாயில் இட்டுப் பற்களால் மிகக் கொடூரமாக மென்றாள்.",
        '17.12': "ஒருவனைக் கூந்தலைப் பற்றியும், இன்னொருவனைக் கழுத்தைப் பற்றியும் பிடித்தாள்; வேறொருவனைக் காலால் மிதித்தாள், மற்றொருவனை மார்பால் நசுக்கினாள்.",
        '17.13': "அந்த அசுரர்கள் எறிந்த ஆயுதங்களையும் பேரஸ்திரங்களையும் அவள் சினத்துடன் வாயால் பற்றிப் பற்களால் நொறுக்கினாள்.",
        '17.14': "வலிமையுள்ள தீய அசுரர்களின் அந்தப் படை முழுவதையும் அவள் நசுக்கினாள்; சிலரை விழுங்கினாள், மற்றவர்களை அடித்து வீழ்த்தினாள்.",
        '17.15': "சில அசுரர்கள் வாளால் கொல்லப்பட்டனர், சிலர் கட்வாங்கத்தால் அடிக்கப்பட்டனர், மற்றும் சிலர் பற்களின் நுனியால் கிழிக்கப்பட்டு அழிந்தனர்.",
        '17.16': "ஒரு கணத்தில் அசுரர்களின் அந்தப் படை முழுதும் வீழ்ந்ததைக் கண்டு சண்டன் மிகக் கொடூரமான அந்தக் காளியை நோக்கிப் பாய்ந்தான்.",
        '17.17': "அந்த மகாசுரன் அச்சந்தரும் கண்களுடைய அவளை மிகக் கொடிய அம்பு மழையால் மூடினான்; முண்டன் ஆயிரக்கணக்கில் எறிந்த சக்கரங்களால் மூடினான்.",
        '17.18': "அவள் வாயினுள் நுழைந்த அந்தப் பல சக்கரங்கள் மேகத்தின் வயிற்றுக்குள் நுழையும் பல சூரிய வட்டங்களைப் போல விளங்கின.",
        '17.19': "அப்போது கொடூரமாக முழங்கும் காளி பெருஞ்சினத்துடன் அச்சந்தரச் சிரித்தாள்; அவள் கோர வாயினுள் காண இயலாத பற்கள் ஒளிர்ந்தன.",
        '17.20': "தேவி எழுந்து பெரிய வாளை உயர்த்தி ‘ஹம்’ என்று சண்டனை நோக்கிப் பாய்ந்தாள்; அவன் கூந்தலைப் பற்றி அந்த வாளால் அவன் தலையை வெட்டினாள்.",
        '17.21': "சண்டன் வீழ்ந்ததைக் கண்ட முண்டன் அவளை நோக்கிப் பாய்ந்தான்; அவள் சினத்துடன் வாளால் வெட்டி அவனையும் தரையில் வீழ்த்தினாள்.",
        '17.22': "சண்டனும் பெரும் வீரனான முண்டனும் வீழ்ந்ததைக் கண்டு எஞ்சிய படை அஞ்சித் திசைதோறும் ஓடியது.",
        '17.23': "காளி சண்ட முண்டரின் தலைகளை எடுத்துக்கொண்டு சண்டிகையிடம் வந்து கடும் அட்டகாசச் சிரிப்புடன் கூறினாள்:",
        '17.24': "“சண்டன் முண்டன் என்னும் இரண்டு பெரும் பலிப் பசுக்களை நான் உனக்கு இங்கே கொண்டு வந்துள்ளேன். போர் என்னும் யக்ஞத்தில் சும்ப நிசும்பரை நீயே கொல்வாய்.”",
        '17.25': "ரிஷி கூறினார்:",
        '17.26': "கொண்டு வரப்பட்ட மகாசுரர்களான சண்ட முண்டரைக் கண்டு மங்களமான சண்டிகை காளியிடம் இனிமையாகக் கூறினாள்:",
        '17.27': "“தேவியே, நீ சண்டனையும் முண்டனையும் பிடித்துக் கொண்டு வந்ததால் உலகில் ‘சாமுண்டா’ என்று புகழ்பெறுவாய்.”",
        '17.28': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “சண்ட முண்ட வதம்” என்னும் ஏழாம் அத்தியாயம் நிறைவுற்றது.",
        '18.0': "ஓம். செந்நிறமானவளும், கருணை அலைபாயும் கண்களுடையவளும், பாசம், அங்குசம், அம்பு, வில் ஆகியவற்றைக் கைகளில் ஏந்தியவளும், அணிமா முதலிய சித்திகள் என்னும் கதிர்களால் சூழப்பட்டவளுமான பவானியை ‘நானே அவள்’ என்ற பாவனையுடன் தியானிக்கிறேன்.",
        '18.1': "ரிஷி கூறினார்:",
        '18.2': "சண்ட அசுரன் கொல்லப்பட்டு, முண்டனும் வீழ்த்தப்பட்டு, பல படைகள் அழிந்தபோது அசுரர் தலைவன் —",
        '18.3': "வலிமைமிக்க சும்பன் சினத்துக்கு அடிமையான மனத்துடன் அசுரர்களின் எல்லாப் படைகளையும் போருக்கு ஆயத்தமாகும்படி கட்டளையிட்டான்.",
        '18.4': "“இன்று ஆயுதம் ஏந்திய எண்பத்தாறு அசுரர்களும், எண்பத்து நான்கு கம்புக்களும் தத்தம் படைகள் சூழ முழு வலிமையுடன் புறப்படட்டும்.”",
        '18.5': "“கோடிவீர்யர் என்னும் ஐம்பது அசுரக் குலங்களும் தௌம்ரர்களின் நூறு குலங்களும் என் ஆணைப்படி புறப்படட்டும்.”",
        '18.6': "“காலகர், தௌர்ஹ்ருதர், மௌர்யர், காலகேயர் என்னும் அசுரர்கள் போருக்கு ஆயத்தமாகி என் ஆணைப்படி விரைந்து புறப்படட்டும்.”",
        '18.7': "இவ்வாறு கட்டளையிட்டு, கொடிய ஆட்சியுடைய அசுர அரசன் சும்பன் ஆயிரக்கணக்கான பெரும் படைகள் சூழப் புறப்பட்டான்.",
        '18.8': "மிகக் கொடிய அந்தப் படை வருவதைக் கண்டு சண்டிகை வில்நாணின் ஓசையால் மண்ணுக்கும் விண்ணுக்கும் இடையிலான வெளியை நிரப்பினாள்.",
        '18.9': "அரசனே, அப்போது சிங்கம் பெரும் கர்ஜனை செய்தது; அம்பிகை மணியோசையால் அந்த ஒலியை மேலும் பெருக்கினாள்.",
        '18.10': "வில்நாண், சிங்கம், மணி ஆகியவற்றின் ஓசையால் திசைகள் நிரம்பியிருக்க, வாயை அகலத் திறந்த காளி தன் கொடிய முழக்கங்களால் அவை அனைத்தையும் விஞ்சினாள்.",
        '18.11': "அந்த ஒலியைக் கேட்டுச் சினமுற்ற அசுரப் படைகள் தேவியையும் சிங்கத்தையும் காளியையும் நான்கு திசைகளிலிருந்தும் சூழ்ந்தன.",
        '18.12': "அரசனே, இதற்கிடையே தேவர்களின் பகைவர் அழிவுக்காகவும், தேவர்களில் சிறந்தோரின் நலனுக்காகவும், மிகுந்த வீரமும் வலிமையும் உடைய —",
        '18.13': "— பிரம்மா, ஈசன், குகன் (ஸ்கந்தன்), விஷ்ணு, இந்திரன் ஆகியோரின் சக்திகள் அவர்கள் உடல்களிலிருந்து வெளிப்பட்டு அவரவர் வடிவங்களில் சண்டிகையிடம் சென்றன.",
        '18.14': "எந்தத் தேவனுக்கு எந்த வடிவமும், அணிகலன்களும், வாகனமும் இருந்தனவோ, அதே விதமாக அவன் சக்தி அசுரர்களுடன் போரிட வந்தது.",
        '18.15': "அன்னங்கள் பூட்டிய விமானத்தில் ஜபமாலையும் கமண்டலமும் ஏந்திப் பிரம்மாவின் சக்தி வந்தாள்; அவள் ‘ப்ரஹ்மாணீ’ எனப்படுகிறாள்.",
        '18.16': "மாஹேச்வரி காளையின் மீது ஏறி, சிறந்த திரிசூலம் ஏந்தி, பெரும் பாம்புகளைக் கடகங்களாக அணிந்து, பிறைச் சந்திரனை அணிகலனாகத் தரித்து வந்தாள்.",
        '18.17': "கையில் வேல் ஏந்தி, சிறந்த மயிலை வாகனமாகக் கொண்டு, குகனின் வடிவம் தாங்கிய அம்பிகை கௌமாரி அசுரர்களுடன் போரிட வந்தாள்.",
        '18.18': "அவ்வாறே விஷ்ணுவின் சக்தியான வைஷ்ணவி கருடன் மீது அமர்ந்து சங்கு, சக்கரம், கதை, சார்ங்க வில், வாள் ஏந்தி வந்தாள்.",
        '18.19': "ஒப்பற்ற யக்ஞ வராக வடிவம் தாங்கிய ஹரியின் சக்தியும் வராக உடலைத் தாங்கி அங்கே வந்தாள் (வாராஹீ).",
        '18.20': "நரசிம்மனைப் போன்ற உடலைத் தாங்கிய நாரஸிம்ஹீ, பிடரியின் அசைவால் விண்மீன் கூட்டங்களைச் சிதறடித்தவாறு அங்கே வந்தாள்.",
        '18.21': "அவ்வாறே ஐந்த்ரீ வஜ்ரத்தைக் கையில் ஏந்தி யானைகளின் அரசன் மீது அமர்ந்து ஆயிரம் கண்களுடன் வந்தாள்; சக்ரன் (இந்திரன்) எப்படியோ அவளும் அப்படியே.",
        '18.22': "அப்போது அந்தத் தேவசக்திகளால் சூழப்பட்ட ஈசானன் (சிவன்) சண்டிகையிடம் “என் மகிழ்ச்சிக்காக அசுரர்களை விரைவில் கொல்” என்றான்.",
        '18.23': "அப்போது தேவியின் உடலிலிருந்து மிகக் கொடிய, மிகக் கடுமையான, நூறு நரிகளைப் போல ஊளையிடும் சண்டிகா சக்தி வெளிப்பட்டாள்.",
        '18.24': "அந்த வெல்லற்கரியவள் புகை நிறச் சடையுடைய ஈசானனிடம் கூறினாள்: “பகவானே, நீ தூதனாகச் சும்ப நிசும்பரிடம் செல்.”",
        '18.25': "“மிகுந்த செருக்குடைய தானவர்களான சும்ப நிசும்பரிடமும், அங்கே போருக்குக் கூடியுள்ள மற்ற தானவர்களிடமும் இவ்வாறு சொல்:”",
        '18.26': "“இந்திரன் மூவுலகையும் பெறட்டும்; தேவர்கள் அவிர்பாகத்தை அனுபவிக்கட்டும். நீங்கள் வாழ விரும்பினால் பாதாளத்துக்குச் செல்லுங்கள்.”",
        '18.27': "“ஆனால் வலிமைச் செருக்கால் நீங்கள் போரை விரும்பினால் வாருங்கள்; என் நரிகள் உங்கள் சதையால் நிறைவுறட்டும்.”",
        '18.28': "அந்தத் தேவி சிவனையே தூதுப் பணிக்கு அமர்த்தியதால், இவ்வுலகில் அவள் ‘சிவதூதீ’ என்று புகழ்பெற்றாள்.",
        '18.29': "சர்வன் (சிவன்) தெரிவித்த தேவியின் சொற்களைக் கேட்டு அந்த மகாசுரர்கள் சினம் நிறைந்து காத்யாயனி இருந்த இடத்துக்குச் சென்றனர்.",
        '18.30': "அப்போது தொடக்கத்திலேயே பொங்கிய சினத்துடன் தேவர்களின் பகைவர்கள் அந்தத் தேவி மீது அம்புகள், சக்திகள், ருஷ்டிகள் ஆகியவற்றின் மழையைப் பொழிந்தனர்.",
        '18.31': "அவள் வளைத்த வில்லிலிருந்து விடுத்த பேரம்புகளால் அவர்கள் எறிந்த அம்புகள், சூலங்கள், சக்திகள், கோடரிகள் ஆகியவற்றை விளையாட்டாக வெட்டினாள்.",
        '18.32': "அவள் முன்னே காளி சூலத்தின் தாக்குதலால் பகைவர்களைப் பிளந்தும், கட்வாங்கத்தால் நசுக்கியும் திரிந்தாள்.",
        '18.33': "பிரம்மாணி எங்கெங்கு ஓடினாளோ அங்கெல்லாம் கமண்டல நீரைத் தெளித்துப் பகைவர்களை வீரமும் ஒளியும் இழந்தவர்களாக்கினாள்.",
        '18.34': "மாஹேச்வரி திரிசூலத்தாலும், வைஷ்ணவி சக்கரத்தாலும், பெருஞ்சினம் கொண்ட கௌமாரி வேலாலும் அசுரர்களைக் கொன்றனர்.",
        '18.35': "ஐந்த்ரீயின் வஜ்ராயுதத் தாக்குதலால் பிளக்கப்பட்ட நூற்றுக்கணக்கான தைத்ய தானவர்கள் குருதி வெள்ளத்தைப் பொழிந்தவாறு தரையில் வீழ்ந்தனர்.",
        '18.36': "வராக வடிவினளின் மூக்கின் தாக்குதலால் நொறுங்கியும், கோரைப் பற்களின் நுனியால் மார்பு கிழிந்தும், சக்கரத்தால் பிளக்கப்பட்டும் அவர்கள் வீழ்ந்தனர்.",
        '18.37': "நாரஸிம்ஹீ நகங்களால் கிழித்த மற்ற மகாசுரர்களை விழுங்கியவாறு, தன் முழக்கத்தால் திசைகளையும் வானையும் நிரப்பியவாறு போர்க்களத்தில் திரிந்தாள்.",
        '18.38': "சிவதூதீயின் கொடிய அட்டகாசச் சிரிப்பால் தாக்கப்பட்ட அசுரர்கள் தரையில் வீழ்ந்தனர்; வீழ்ந்த அவர்களை அவள் அப்போது விழுங்கினாள்.",
        '18.39': "இவ்வாறு சினமுற்ற மாத்ருகணம் பல வழிகளில் மகாசுரர்களை நசுக்குவதைக் கண்டு தேவர்களின் பகைவர் படைவீரர்கள் ஓடிப்போயினர்.",
        '18.40': "மாத்ருகணத்தால் துன்புறுத்தப்பட்டு ஓடும் அசுரர்களைக் கண்டு ரக்தபீஜன் என்னும் மகாசுரன் சினத்துடன் போரிட வந்தான்.",
        '18.41': "அவன் உடலிலிருந்து ஒரு துளி குருதி தரையில் விழும்போதெல்லாம், அவனுக்கு நிகரான அளவுடைய ஓர் அசுரன் பூமியிலிருந்து எழுந்தான்.",
        '18.42': "கதை ஏந்திய அந்த மகாசுரன் இந்திர சக்தியுடன் போரிட்டான்; அப்போது ஐந்த்ரீ தன் வஜ்ரத்தால் ரக்தபீஜனைத் தாக்கினாள்.",
        '18.43': "வஜ்ரத்தால் தாக்கப்பட்ட அவனிடமிருந்து விரைவில் மிகுந்த குருதி வழிந்தது; அதிலிருந்து அவனுடைய வடிவும் வீரமும் கொண்ட வீரர்கள் எழுந்தனர்.",
        '18.44': "அவன் உடலிலிருந்து எத்தனை குருதித் துளிகள் விழுந்தனவோ, அத்தனை ஆண்கள் அவனுடைய ஆற்றல், வலிமை, வீரத்துடன் பிறந்தனர்.",
        '18.45': "குருதியிலிருந்து பிறந்த அந்த ஆண்களும் அங்கே மாத்ருகைகளுடன் கொடிய ஆயுதங்களின் தாக்குதலுடன் மிகப் பயங்கரமான போர் புரிந்தனர்.",
        '18.46': "மீண்டும் வஜ்ரத் தாக்குதலால் அவன் தலை காயமடைந்தபோது குருதி பெருகியது; அதிலிருந்து ஆயிரக்கணக்கான ஆண்கள் பிறந்தனர்.",
        '18.47': "வைஷ்ணவி போரில் அவனைச் சக்கரத்தால் தாக்கினாள்; ஐந்த்ரீ அந்த அசுரர் தலைவனைக் கதையால் அடித்தாள்.",
        '18.48': "வைஷ்ணவியின் சக்கரத்தால் பிளக்கப்பட்ட அவன் குருதிப் பெருக்கிலிருந்து பிறந்த, அவனுக்கு நிகரான ஆயிரக்கணக்கான மகாசுரர்களால் உலகம் நிறைந்தது.",
        '18.49': "கௌமாரி வேலாலும், வாராஹீ வாளாலும், மாஹேச்வரி திரிசூலத்தாலும் மகாசுரன் ரக்தபீஜனைத் தாக்கினர்.",
        '18.50': "சினம் நிறைந்த மகா அசுரன் ரக்தபீஜனும் எல்லா மாத்ருகைகளையும் தனித்தனியே கதையால் தாக்கினான்.",
        '18.51': "சக்தி, சூலம் முதலியவற்றால் மீண்டும் மீண்டும் தாக்கப்பட்ட அவனிடமிருந்து தரையில் விழுந்த குருதிப் பெருக்கிலிருந்து நூற்றுக்கணக்கான அசுரர்கள் தோன்றினர்.",
        '18.52': "அசுரனின் குருதியிலிருந்து பிறந்த அந்த அசுரர்களால் உலகம் முழுதும் நிறைந்தது; அப்போது தேவர்கள் பெரும் அச்சம் அடைந்தனர்.",
        '18.53': "வருந்திய தேவர்களைக் கண்டு சண்டிகை சிரித்து விரைவாகக் காளியிடம் “சாமுண்டே, உன் வாயை அகலத் திற” என்றாள்.",
        '18.54': "“என் ஆயுதத் தாக்குதலால் விழும் குருதித் துளிகளையும், ரக்தபீஜனின் குருதித் துளிகளிலிருந்து பிறக்கும் மகாசுரர்களையும் உன் இந்த வேகமான வாயால் ஏந்திக்கொள்.”",
        '18.55': "“அவற்றிலிருந்து பிறக்கும் மகாசுரர்களை விழுங்கியவாறு போர்க்களத்தில் திரி. இவ்வாறு குருதி வற்றி இந்த அசுரன் அழிவான்.”",
        '18.56': "“நீ அந்தக் கொடியவர்களை விழுங்கினால் வேறு யாரும் தோன்ற மாட்டார்கள்.” என்று அவளிடம் கூறித் தேவி அவனைச் சூலத்தால் தாக்கினாள்.",
        '18.57': "காளி ரக்தபீஜனின் குருதியை வாயால் ஏந்தினாள். அப்போது அவன் அங்கே சண்டிகையைக் கதையால் தாக்கினான்.",
        '18.58': "ஆனால் அந்தக் கதைத் தாக்குதல் அவளுக்குச் சிறிதும் வலியை ஏற்படுத்தவில்லை. காயமுற்ற அவன் உடலிலிருந்து மிகுந்த குருதி வழிந்தது.",
        '18.59': "அது எங்கெங்கு வழிந்ததோ அங்கெல்லாம் சாமுண்டா தன் வாயால் அதை ஏந்தினாள்; குருதி விழுந்ததால் அவள் வாயிலேயே தோன்றிய மகாசுரர்களை —",
        '18.60': "— சாமுண்டா விழுங்கினாள்; அவன் குருதியையும் பருகினாள். தேவி சூலம், வஜ்ரம், அம்புகள், வாள்கள், ருஷ்டிகள் ஆகியவற்றால்,",
        '18.61': "சாமுண்டா குருதியைப் பருகிய அந்த ரக்தபீஜனைக் கொன்றாள். ஆயுதக் கூட்டத்தால் தாக்கப்பட்ட அவன் தரையில் வீழ்ந்தான் —",
        '18.62': "— அரசனே, மகாசுரன் ரக்தபீஜன் குருதியற்றவனாகி வீழ்ந்தான். அப்போது மன்னா, தேவர்கள் அளவற்ற மகிழ்ச்சி அடைந்தனர்.",
        '18.63': "தேவர்களிடமிருந்து தோன்றிய மாத்ருகணம் குருதி மயக்கத்தால் களிப்புற்று நடனமாடியது.",
        '18.64': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “ரக்தபீஜ வதம்” என்னும் எட்டாம் அத்தியாயம் நிறைவுற்றது.",
        '19.0': "ஓம். பந்தூக மலரைப் போலவும் பொன்னைப் போலவும் ஒளிர்வதும், தன் கரங்களில் அழகிய ஜபமாலை, பாசம், அங்குசம், வரமுத்திரை ஆகியவற்றைத் தாங்கியதும், பிறைச் சந்திரனை அணிகலனாகக் கொண்டதும், முக்கண்ணுடையதுமான அர்த்தநாரீச்வர வடிவை எப்போதும் சரணடைகிறேன்.",
        '19.1': "அரசன் கூறினான்:",
        '19.2': "“பகவானே, ரக்தபீஜ வதம் தொடர்பான தேவியின் சரித்திர மகிமையை நீங்கள் எனக்குக் கூறியது வியப்பானது.”",
        '19.3': "“ரக்தபீஜன் வீழ்ந்த பின் சும்பனும், மிகுந்த சினமுடைய நிசும்பனும் என்ன செய்தனர் என்பதை மேலும் கேட்க விரும்புகிறேன்.”",
        '19.4': "ரிஷி கூறினார்:",
        '19.5': "ரக்தபீஜன் வீழ்ந்து, போரில் மற்றவர்களும் கொல்லப்பட்டபோது சும்பாசுரனும் நிசும்பனும் அளவற்ற சினம் கொண்டனர்.",
        '19.6': "தன் பெரும் படை அழிக்கப்படுவதைக் கண்டு கொதிப்புடன் நிசும்பன் அசுரர்களின் முதன்மைப் படையுடன் முன்னே பாய்ந்தான்.",
        '19.7': "அவனுக்கு முன்னும் பின்னும் இரு பக்கங்களிலும் சினத்துடன் உதடுகளைக் கடித்தவாறு மகாசுரர்கள் தேவியைக் கொல்ல வந்தனர்.",
        '19.8': "பெரும் வீரனான சும்பனும் தன் படைகள் சூழ, மாத்ருகைகளுடன் போரிட்டு, சினத்துடன் சண்டிகையைக் கொல்ல வந்தான்.",
        '19.9': "அப்போது தேவிக்கும் சும்ப நிசும்பருக்கும் கடும் போர் நடந்தது; மழை பொழியும் இரு மேகங்களைப் போல அவர்கள் மிகக் கொடிய அம்பு மழையைப் பொழிந்தனர்.",
        '19.10': "அவ்விருவர் எய்த அம்புகளைச் சண்டிகை தன் அம்புக் கூட்டங்களால் வெட்டினாள்; ஆயுதக் கூட்டங்களால் அவ்விரு அசுரர் தலைவர்களின் அங்கங்களைத் தாக்கினாள்.",
        '19.11': "நிசும்பன் கூரிய வாளையும் ஒளிரும் கேடயத்தையும் எடுத்துத் தேவியின் சிறந்த வாகனமான சிங்கத்தின் தலையில் தாக்கினான்.",
        '19.12': "வாகனம் தாக்கப்பட்டதும் தேவி கத்திமுனை அம்பால் நிசும்பனின் சிறந்த வாளையும், எட்டுச் சந்திரக் குறிகளுடைய கேடயத்தையும் விரைவில் வெட்டினாள்.",
        '19.13': "கேடயமும் வாளும் வெட்டப்பட்டதும் அந்த அசுரன் சக்தி ஆயுதத்தை எறிந்தான்; எதிரே வந்த அதையும் அவள் சக்கரத்தால் இரண்டாகப் பிளந்தாள்.",
        '19.14': "அப்போது சினத்தால் பொங்கிய தானவன் நிசும்பன் சூலத்தை எடுத்தான்; வந்த அதையும் தேவி முஷ்டியின் அடியால் தூளாக்கினாள்.",
        '19.15': "அப்போது அவன் கதையைச் சுழற்றிச் சண்டிகையை நோக்கி எறிந்தான்; தேவியின் திரிசூலத்தால் பிளக்கப்பட்ட அதுவும் சாம்பலானது.",
        '19.16': "அப்போது கோடரியுடன் வந்த அந்த அசுரர்களில் சிறந்தவனைத் தேவி அம்புக் கூட்டங்களால் தாக்கித் தரையில் வீழ்த்தினாள்.",
        '19.17': "அச்சந்தரும் வீரமுடைய தன் தம்பி நிசும்பன் தரையில் வீழ்ந்ததும் சும்பன் பெருஞ்சினத்துடன் அம்பிகையைக் கொல்லப் புறப்பட்டான்.",
        '19.18': "தேரில் நின்று, ஒப்பற்ற எட்டுக் கைகளில் சிறந்த ஆயுதங்களை உயர்த்திப் பிடித்து, அவன் வானம் முழுவதையும் நிறைத்து ஒளிர்ந்தான்.",
        '19.19': "அவன் வருவதைக் கண்டு தேவி சங்கை ஊதினாள்; வில்நாணின் தாங்க முடியாத ஓசையையும் எழுப்பினாள்.",
        '19.20': "எல்லா அசுரப் படைகளின் ஒளியையும் அழிக்கும் தன் மணியோசையால் அவள் திசைகளை நிரப்பினாள்.",
        '19.21': "அப்போது சிங்கம் பெரும் யானைகளின் மதத்தைப் போக்கும் பெரும் முழக்கங்களால் வானையும் பூமியையும் பத்துத் திசைகளையும் நிரப்பியது.",
        '19.22': "அப்போது காளி வானில் எழும்பி இரு கைகளாலும் பூமியை அறைந்தாள்; அந்த ஒலியால் முந்தைய ஒலிகள் அனைத்தும் அமிழ்ந்தன.",
        '19.23': "சிவதூதீ அமங்கலமான அட்டகாசச் சிரிப்பை எழுப்பினாள்; அந்த ஒலிகளால் அசுரர்கள் நடுங்கினர், சும்பன் பெருஞ்சினம் அடைந்தான்.",
        '19.24': "அம்பிகை “தீயவனே, நில், நில்!” என்றபோது வானில் நின்ற தேவர்கள் “ஜயம்!” என்று முழங்கினர்.",
        '19.25': "சும்பன் வந்து எறிந்த, தீச்சுடர்களால் மிகக் கொடிய, நெருப்புக் குவியல் போல் வந்த சக்தி ஆயுதத்தைத் தேவி பெரும் எரிகொள்ளியால் தடுத்தாள்.",
        '19.26': "அரசனே, சும்பனின் சிம்மநாதம் மூவுலகின் இடைவெளியை நிரப்பியது; ஆனால் (தேவியின்) இடிபோன்ற கொடிய ஒலி அதை வென்றது.",
        '19.27': "சும்பன் எய்த அம்புகளைத் தேவியும், அவள் எய்த அம்புகளைச் சும்பனும் தத்தம் கொடிய அம்புகளால் நூறு நூறாக, ஆயிரம் ஆயிரமாக வெட்டினர்.",
        '19.28': "அப்போது சினமுற்ற சண்டிகை அவனைச் சூலத்தால் தாக்கினாள்; தாக்கப்பட்ட அவன் மயங்கித் தரையில் வீழ்ந்தான்.",
        '19.29': "அப்போது நிசும்பன் நினைவு மீண்டு வில்லை எடுத்துத் தேவியையும் காளியையும் சிங்கத்தையும் அம்புகளால் தாக்கினான்.",
        '19.30': "மீண்டும் தானவர் தலைவனான அந்தத் திதியின் மகன் பத்தாயிரம் கைகளை உண்டாக்கிக்கொண்டு சக்கரங்களால் சண்டிகையை மூடினான்.",
        '19.31': "அப்போது துன்பத்தையும் துயரத்தையும் அழிக்கும் பகவதி துர்கை சினமுற்று அந்தச் சக்கரங்களையும் அம்புகளையும் தன் அம்புகளால் வெட்டினாள்.",
        '19.32': "அப்போது நிசும்பன் கதையை எடுத்துக்கொண்டு அசுரப் படை சூழச் சண்டிகையைக் கொல்ல வேகமாகப் பாய்ந்தான்.",
        '19.33': "அவன் பாய்ந்து வரும்போதே சண்டிகை கூரிய முனையுடைய வாளால் அவன் கதையை விரைவில் வெட்டினாள்; அவன் சூலத்தை எடுத்தான்.",
        '19.34': "சூலத்துடன் வந்த, தேவர்களைத் துன்புறுத்திய நிசும்பனின் இதயத்தைச் சண்டிகை வேகமாக எறிந்த சூலத்தால் துளைத்தாள்.",
        '19.35': "சூலத்தால் பிளக்கப்பட்ட அவன் இதயத்திலிருந்து பெரும் வலிமையும் பெரும் வீரமும் உடைய இன்னொரு மனிதன் “நில்!” என்று கூவியவாறு வெளிப்பட்டான்.",
        '19.36': "அவன் வெளிப்படும்போதே தேவி உரக்கச் சிரித்து வாளால் அவன் தலையை வெட்டினாள்; அப்போது அவன் தரையில் வீழ்ந்தான்.",
        '19.37': "அப்போது சிங்கம் கோரைப் பற்களால் கழுத்துகளை நசுக்கிய கொடிய அசுரர்களை விழுங்கியது; காளியும் சிவதூதீயும் மற்றவர்களை விழுங்கினர்.",
        '19.38': "சில மகாசுரர்கள் கௌமாரியின் வேலால் பிளக்கப்பட்டு அழிந்தனர்; மற்றவர்கள் பிரம்மாணியின் மந்திரத்தால் தூய்மையான நீரால் விரட்டப்பட்டனர்.",
        '19.39': "மேலும் சிலர் மாஹேச்வரியின் திரிசூலத்தால் பிளக்கப்பட்டு வீழ்ந்தனர்; சிலர் வாராஹீயின் மூக்குத் தாக்குதலால் தரையில் தூளாயினர்.",
        '19.40': "வைஷ்ணவியின் சக்கரத்தால் தானவர்கள் துண்டு துண்டாக்கப்பட்டனர்; மற்றவர்கள் ஐந்த்ரீயின் கை நுனியிலிருந்து விடுபட்ட வஜ்ரத்தால்.",
        '19.41': "சில அசுரர்கள் அழிந்தனர், சிலர் பெரும் போரிலிருந்து ஓடினர், மற்றவர்கள் காளி, சிவதூதீ, சிங்கம் ஆகியோரால் விழுங்கப்பட்டனர்.",
        '19.42': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “நிசும்ப வதம்” என்னும் ஒன்பதாம் அத்தியாயம் நிறைவுற்றது.",
        '20.0': "ஓம். உருக்கிய பொன் போல் அழகியவளும், சூரியன், சந்திரன், அக்னி ஆகியோரைக் கண்களாகக் கொண்டவளும், அழகிய கரங்களில் வில், அம்பு, அங்குசம், பாசம், சூலம் ஏந்தியவளும், சிவசக்தி வடிவினளும், பிறைச் சந்திரனை அணிந்தவளுமான காமேச்வரியை இதயத்தில் வழிபடுகிறேன்.",
        '20.1': "ரிஷி கூறினார்:",
        '20.2': "தன் உயிருக்கு நிகரான தம்பி நிசும்பன் கொல்லப்பட்டதையும், படை அழிக்கப்படுவதையும் கண்டு சும்பன் சினத்துடன் கூறினான்:",
        '20.3': "“கொடியவளே துர்கே, வலிமைச் செருக்கால் இறுமாப்புக் கொள்ளாதே. மிகுந்த அகந்தையுடைய நீ பிறரின் வலிமையைச் சார்ந்தே போரிடுகிறாய்.”",
        '20.4': "தேவி கூறினாள்:",
        '20.5': "“இவ்வுலகில் நான் ஒருத்தியே இருக்கிறேன்; என்னைத் தவிர இரண்டாமவள் யார்? கொடியவனே, என் விபூதிகளான இவர்கள் என்னுள்ளேயே புகுவதைப் பார்.”",
        '20.6': "அப்போது பிரம்மாணி முதலிய அந்தத் தேவியர் அனைவரும் அந்தத் தேவியின் உடலில் ஒடுங்கினர்; அம்பிகை ஒருத்தியே எஞ்சினாள்.",
        '20.7': "தேவி கூறினாள்:",
        '20.8': "“என் ஆற்றலால் நான் இங்கே கொண்டிருந்த பல வடிவங்களை உள்ளிழுத்துக்கொண்டேன்; இப்போது நான் ஒருத்தியே போரில் நிற்கிறேன். உறுதியாக நில்!”",
        '20.9': "ரிஷி கூறினார்:",
        '20.10': "அப்போது எல்லாத் தேவர்களும் அசுரர்களும் பார்த்துக்கொண்டிருக்கத் தேவிக்கும் சும்பனுக்கும் இடையே கொடிய போர் தொடங்கியது.",
        '20.11': "அம்பு மழைகளாலும், கூரிய ஆயுதங்களாலும், கொடிய அஸ்திரங்களாலும் அவர்களின் போர் மீண்டும் எல்லா உலகங்களையும் அஞ்சவைப்பதாயிற்று.",
        '20.12': "அம்பிகை விடுத்த நூற்றுக்கணக்கான திவ்ய அஸ்திரங்களை அசுர அரசன் அவற்றை எதிர்க்கும் அஸ்திரங்களால் முறியடித்தான்.",
        '20.13': "அவன் விடுத்த திவ்ய அஸ்திரங்களைப் பரமேச்வரி கடுமையான ‘ஹும்’ முதலிய ஒலிகளால் விளையாட்டாக முறியடித்தாள்.",
        '20.14': "அப்போது அந்த அசுரன் நூற்றுக்கணக்கான அம்புகளால் தேவியை மூடினான்; சினமுற்ற தேவி அம்புகளால் அவன் வில்லை வெட்டினாள்.",
        '20.15': "வில் வெட்டப்பட்டதும் அசுர அரசன் சக்தி ஆயுதத்தை எடுத்தான்; அவன் கையில் இருந்த அதையும் தேவி சக்கரத்தால் வெட்டினாள்.",
        '20.16': "அப்போது அசுரத் தலைவர்களின் தலைவன் ஒளிரும் வாளையும், நூறு சந்திரக் குறிகளுடைய பிரகாசமான கேடயத்தையும் எடுத்துத் தேவியை நோக்கிப் பாய்ந்தான்.",
        '20.17': "அவன் பாய்ந்து வரும்போதே சண்டிகை வில்லிலிருந்து எய்த கூரிய அம்புகளால் அவன் வாளையும், சூரியக் கதிர் போன்று தெளிவான கேடயத்தையும் விரைவில் வெட்டினாள்.",
        '20.18': "(அவள் அவன் குதிரைகளையும், சாரதியுடன் தேரையும் வீழ்த்தினாள்.) குதிரைகள் கொல்லப்பட்டு, வில் முறிந்து, சாரதியற்ற அந்த அசுரன் அம்பிகையைக் கொல்ல முனைந்து கொடிய முத்கரத்தை எடுத்தான்.",
        '20.19': "அவன் பாய்ந்து வருகையில் அவள் கூரிய அம்புகளால் அவன் முத்கரத்தை வெட்டினாள்; இருந்தும் அவன் முஷ்டியை உயர்த்தி வேகமாக அவளை நோக்கிப் பாய்ந்தான்.",
        '20.20': "அந்த அசுரர்களில் சிறந்தவன் தேவியின் மார்பில் முஷ்டியால் குத்தினான்; தேவியும் அவன் மார்பில் உள்ளங்கையால் அறைந்தாள்.",
        '20.21': "உள்ளங்கை அடியால் தாக்கப்பட்ட அந்த அசுர அரசன் தரையில் விழுந்தான்; ஆனால் உடனே மீண்டும் எழுந்தான்.",
        '20.22': "அவன் எழும்பித் தேவியைப் பற்றிக்கொண்டு உயர வானில் சென்றான்; அங்கேயும் எந்த ஆதாரமுமின்றிச் சண்டிகை அவனுடன் போரிட்டாள்.",
        '20.23': "அப்போது வானில் அசுரனும் சண்டிகையும் ஒருவரோடொருவர் மல்யுத்தம் செய்தனர்; முன்னெப்போதும் நிகழாத அது சித்தர்களையும் முனிவர்களையும் வியப்பில் ஆழ்த்தியது.",
        '20.24': "அவனுடன் நீண்ட நேரம் மல்யுத்தம் செய்த பின் அம்பிகை அவனைத் தூக்கிச் சுழற்றித் தரையில் வீசினாள்.",
        '20.25': "வீசப்பட்ட அந்தத் தீயவன் தரையை அடைந்து, முஷ்டியை உயர்த்திச் சண்டிகையைக் கொல்லும் விருப்பத்துடன் வேகமாகப் பாய்ந்தான்.",
        '20.26': "அவ்வாறு வந்த எல்லா அசுரர்களின் தலைவனைத் தேவி சூலத்தால் மார்பைப் பிளந்து பூமியில் வீழ்த்தினாள்.",
        '20.27': "தேவியின் சூல நுனியால் காயமுற்ற அவன் உயிரிழந்து, கடல்கள், தீவுகள், மலைகளுடன் கூடிய பூமி முழுவதையும் நடுங்கச் செய்தவாறு தரையில் வீழ்ந்தான்.",
        '20.28': "அந்தத் தீயவன் கொல்லப்பட்டதும் உலகம் முழுதும் தெளிவுற்றது; உலகம் முழு நலம் பெற்றது, வானம் தூய்மையானது.",
        '20.29': "முன்பு தோன்றிய எரிநட்சத்திரங்களுடன் கூடிய தீய சகுன மேகங்கள் அடங்கின; அவன் வீழ்ந்ததும் ஆறுகள் தத்தம் வழியிலேயே ஓடலாயின.",
        '20.30': "அவன் கொல்லப்பட்டதும் எல்லாத் தேவகணங்களின் மனமும் மகிழ்ச்சியால் நிறைந்தது; கந்தர்வர்கள் இனிமையாகப் பாடினர்.",
        '20.31': "மற்றவர்கள் இசைக்கருவிகளை இசைத்தனர், அப்ஸரஸ் கூட்டங்கள் நடனமாடின; புனிதமான காற்று வீசியது, சூரியன் நன்கு ஒளிர்ந்தான்.",
        '20.32': "அணைந்திருந்த வேள்வித் தீகள் மீண்டும் சுடர்விட்டன; திசைகளில் எழுந்த அச்சந்தரும் ஒலிகள் அடங்கின.",
        '20.33': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “சும்ப வதம்” என்னும் பத்தாம் அத்தியாயம் நிறைவுற்றது.",
        '21.0': "ஓம். உதய சூரியனைப் போல் ஒளிர்பவளும், சந்திரனை மகுடமாகக் கொண்டவளும், உயர்ந்த தனங்களும் மூன்று கண்களும் உடையவளும், புன்னகை முகத்தினளும், வரம், அங்குசம், பாசம், அபயம் ஆகியவற்றைக் கைகளில் காட்டுபவளுமான புவனேச்வரியை வழிபடுகிறேன்.",
        '21.1': "ரிஷி கூறினார்:",
        '21.2': "தேவி மகா அசுரத் தலைவனை வதைத்தபோது, இந்திரனும் அக்னி முதலிய தேவர்களும் தம் விருப்பத்தை நிறைவேற்றிய காத்யாயனியைப் போற்றினர்; அவர்கள் முகங்கள் தாமரை போல் மலர்ந்து திசைகளை ஒளிரச் செய்தன.",
        '21.3': "சரணடைவோரின் துயரைப் போக்கும் தேவியே, அருள்புரிவாய். உலகம் முழுவதன் அன்னையே, அருள்புரிவாய். பிரபஞ்சத்தின் ஈச்வரியே, அருள்புரிந்து அதைக் காப்பாய்: இயங்குவன அசையாதன அனைத்தையும் நீயே ஆள்கிறாய்.",
        '21.4': "பூமியாக நிலைத்திருப்பதால் நீ ஒருத்தியே உலகின் ஆதாரம்; வெல்ல முடியாத வலிமையுடையவளே, நீராக இவ்வுலகம் முழுவதையும் போஷிக்கிறாய்.",
        '21.5': "நீயே எல்லையற்ற வீரியமுடைய வைஷ்ணவீ சக்தி, பிரபஞ்சத்தின் வித்து, பரமமாயை. தேவியே, இவை அனைத்தும் உன் மயக்கில் உள்ளன; நீ மகிழ்ந்தால் இப்பூமியில் முக்திக்குக் காரணமாகிறாய்.",
        '21.6': "தேவியே, எல்லா வித்யைகளும் உன் அம்சங்கள், உலகிலுள்ள எல்லாப் பெண்களும் அவ்வாறே; அன்னையான நீ ஒருத்தியே இவை அனைத்தையும் நிறைக்கிறாய். எல்லாப் புகழ்ச்சொற்களுக்கும் அப்பாற்பட்ட உன்னை எந்தத் துதி எட்டும்?",
        '21.7': "எல்லா உயிர்களுமாகி ஸ்வர்க்கமும் முக்தியும் அருளும் தேவி என்று போற்றப்பட்ட பின், உன்னைப் போற்ற இதனினும் உயர்ந்த சொற்கள் எவை?",
        '21.8': "எல்லா உயிர்களின் இதயத்திலும் புத்தியாக உறைந்து ஸ்வர்க்கமும் முக்தியும் அருளும் தேவியே: நாராயணியே, உனக்கு நமஸ்காரம்.",
        '21.9': "கலை, காஷ்டை முதலிய காலப் பகுதிகளாக மாற்றத்தை நிகழ்த்துபவளே, பிரபஞ்சம் ஒடுங்கும் சக்தியே: நாராயணியே, உனக்கு நமஸ்காரம்.",
        '21.10': "மங்கலங்களுக்கெல்லாம் மங்கலமானவளே, எல்லா நோக்கங்களையும் நிறைவேற்றும் சிவையே, அனைவருக்கும் அடைக்கலமே, முக்கண்ணுடைய கௌரியே: நாராயணியே, உனக்கு நமஸ்காரம்.",
        '21.11': "படைத்தல், காத்தல், அழித்தல் ஆகியவற்றின் பின்னுள்ள சக்தியான நித்தியையே, குணங்களின் ஆதாரமும் குணமயமுமானவளே: நாராயணியே, உனக்கு நமஸ்காரம்.",
        '21.12': "சரணடையும் ஆதரவற்றோரையும் துன்புறுவோரையும் காப்பதில் முனைந்தவளே, அனைவரின் துயரையும் போக்கும் தேவியே: நாராயணியே, உனக்கு நமஸ்காரம்.",
        '21.13': "ப்ரஹ்மாணீ வடிவில் அன்னம் பூட்டிய விமானத்தில் சென்று தர்ப்பையால் நீர் தெளிக்கும் தேவியே: நாராயணியே, உனக்கு நமஸ்காரம்.",
        '21.14': "மாஹேச்வரீ வடிவில் திரிசூலம், சந்திரன், நாகம் தாங்கிப் பெரும் காளை மீது ஏறுபவளே: நாராயணியே, உனக்கு நமஸ்காரம்.",
        '21.15': "கௌமாரீ வடிவில் மயிலும் சேவலும் சூழப் பெரும் சக்தி ஆயுதம் தாங்கிய பாவமற்றவளே: நாராயணியே, உனக்கு நமஸ்காரம்.",
        '21.16': "சங்கு, சக்கரம், கதை, சார்ங்க வில் ஆகிய சிறந்த ஆயுதங்களை ஏந்திய வைஷ்ணவீ வடிவினளே, அருள்புரிவாய்: நாராயணியே, உனக்கு நமஸ்காரம்.",
        '21.17': "கொடிய பெரும் சக்கரம் ஏந்தித் தந்தத்தால் பூமியைத் தூக்கிய வராஹ வடிவான மங்கலமானவளே: நாராயணியே, உனக்கு நமஸ்காரம்.",
        '21.18': "மூவுலகைக் காப்பதில் முனைந்து, உக்கிர நரசிம்ம வடிவில் அசுரர்களை வதைக்கப் புறப்பட்டவளே: நாராயணியே, உனக்கு நமஸ்காரம்.",
        '21.19': "கிரீடம் அணிந்து, பெரும் வஜ்ரம் ஏந்தி, ஆயிரம் கண்களால் ஒளிர்ந்து, வ்ருத்திரனின் உயிரைப் பறித்த ஐந்த்ரீயே: நாராயணியே, உனக்கு நமஸ்காரம்.",
        '21.20': "பயங்கர வடிவும் பெரும் கர்ஜனையும் கொண்டு சிவதூதீயாக வலிய அசுரப் படைகளை வீழ்த்தியவளே: நாராயணியே, உனக்கு நமஸ்காரம்.",
        '21.21': "கோரைப்பற்களால் அச்சமூட்டும் முகமும் தலைமாலையும் உடைய, முண்டனை வதைத்த சாமுண்டையே: நாராயணியே, உனக்கு நமஸ்காரம்.",
        '21.22': "லக்ஷ்மீ, லஜ்ஜா, மகாவித்யா, ச்ரத்தா, புஷ்டி, ஸ்வதா, த்ருவா; மகாராத்ரி, மகா அவித்யா: நாராயணியே, உனக்கு நமஸ்காரம்.",
        '21.23': "மேதா, ஸரஸ்வதீ, வரா, பூதி, பழுப்பு நிற பாப்ரவீ, கரிய தாமஸீ, நியதா: அருள்புரிவாய், ஈச்வரியே. நாராயணியே, உனக்கு நமஸ்காரம்.",
        '21.24': "எல்லாவற்றின் வடிவமும், எல்லாவற்றுக்கும் ஈச்வரியும், எல்லா சக்திகளும் நிறைந்தவளுமான தேவியே, அச்சத்திலிருந்து எங்களைக் காப்பாய். துர்கா தேவியே, உனக்கு நமஸ்காரம்.",
        '21.25': "முக்கண்களால் அழகுபெற்ற உன் இந்த மென்முகம் எல்லா அச்சங்களிலிருந்தும் எங்களைக் காக்கட்டும். காத்யாயனியே, உனக்கு நமஸ்காரம்.",
        '21.26': "சுடர்களால் பயங்கரமானதும், அளவற்ற உக்கிரமுடையதும், எல்லா அசுரர்களையும் அழிப்பதுமான உன் திரிசூலம் அச்சத்திலிருந்து எங்களைக் காக்கட்டும். பத்ரகாளியே, உனக்கு நமஸ்காரம்.",
        '21.27': "தன் ஒலியால் உலகை நிறைத்து அசுரர்களின் வலிமையை அழிக்கும் உன் மணி, தேவியே, தாய் குழந்தைகளைக் காப்பது போல் எங்களைப் பாவத்திலிருந்து காக்கட்டும்.",
        '21.28': "அசுரர்களின் குருதியாலும் கொழுப்பாலும் பூசப்பட்டு உன் கையில் ஒளிரும் உன் வாள் எங்களுக்கு நலமாகட்டும், சண்டிகையே. உன்னை வணங்குகிறோம்.",
        '21.29': "மகிழ்ந்தால் எல்லா நோய்களையும் அழிக்கிறாய்; மகிழாவிடில் விரும்பியவை அனைத்தையும் பறிக்கிறாய். உன்னைச் சார்ந்தோருக்குத் தீங்கு வருவதில்லை; உன்னைச் சார்ந்தோர் பிறருக்கும் அடைக்கலமாகின்றனர்.",
        '21.30': "இன்று தர்மத்தை வெறுத்த மகா அசுரர்களை, உன் வடிவைப் பலவிதமாகப் பலவாக்கி வதைத்தாய். அம்பிகையே, வேறு யாரால் இதைச் செய்ய முடியும்?",
        '21.31': "விவேக தீபத்தை ஏற்றும் வித்யைகளிலும், சாஸ்திரங்களிலும், வேதத்தின் ஆதி வாக்கியங்களிலும் உன்னையன்றி வேறு யார் உள்ளார்? “என்னுடையது” என்னும் குழியின் ஆழ்ந்த இருளில் இவ்வுலகைச் சுழலச் செய்வதும் உன்னையன்றி வேறு யார்?",
        '21.32': "ராக்ஷஸர்களும் கொடிய நச்சுப் பாம்புகளும் உள்ள இடத்திலும், பகைவரும் கொள்ளைக் கூட்டங்களும் உள்ள இடத்திலும், காட்டுத்தீயிலும் கடலின் நடுவிலும்: அங்கே நீ நின்று உலகைக் காக்கிறாய்.",
        '21.33': "பிரபஞ்சத்தின் ஈச்வரியே, நீ பிரபஞ்சத்தைக் காக்கிறாய்; அதன் ஆத்மாவாக அதைத் தாங்குகிறாய்; பிரபஞ்ச நாதனாலும் வழிபடப்படுகிறாய்; பக்தியுடன் உன்னை வணங்குவோர் பிரபஞ்சத்துக்கே அடைக்கலமாகின்றனர்.",
        '21.34': "தேவியே, அருள்புரிவாய்: இப்போது அசுரர்களை வதைத்துச் செய்தது போல் பகைவர் அச்சத்திலிருந்து எங்களை எப்போதும் காப்பாய்; எல்லா உலகங்களின் பாவங்களையும் தீய சகுனங்களால் விளையும் பெரும் ஆபத்துகளையும் விரைவில் தணிப்பாய்.",
        '21.35': "உலகின் துயரைப் போக்கும் தேவியே, உன்னை வணங்குவோருக்கு அருள்புரிவாய்; மூவுலக வாசிகளால் போற்றப்படுபவளே, எல்லா உலகங்களுக்கும் வரம் அருள்பவளாவாய்.",
        '21.36': "தேவி கூறினாள்:",
        '21.37': "“தேவகணங்களே, நான் வரம் அருள்பவள். உலகங்களுக்கு நன்மை தரும் எந்த வரத்தை நீங்கள் மனத்தில் விரும்புகிறீர்களோ அதைக் கேளுங்கள்; நான் அருள்கிறேன்.”",
        '21.38': "தேவர்கள் கூறினர்:",
        '21.39': "“அனைத்துக்கும் ஈச்வரியே, இவ்வாறே நீ மூவுலகின் எல்லாத் துன்பங்களையும் தணிப்பாயாக; எங்கள் பகைவர்களை அழிப்பாயாக.”",
        '21.40': "தேவி கூறினாள்:",
        '21.41': "“வைவஸ்வத மன்வந்தரத்தின் இருபத்தெட்டாவது யுகத்தில் சும்பன், நிசும்பன் என்னும் வேறு இரு மகாசுரர்கள் பிறப்பார்கள்.”",
        '21.42': "“அப்போது நந்தகோபனின் இல்லத்தில் யசோதையின் கருவில் பிறந்து, விந்திய மலையில் வசித்து, அவ்விருவரையும் அழிப்பேன்.”",
        '21.43': "“மீண்டும் மிகக் கடுமையான வடிவில் பூமியில் அவதரித்து விப்ரசித்தியின் வம்சத்துத் தானவர்களைக் கொல்வேன்.”",
        '21.44': "“விப்ரசித்தி வம்சத்து அந்தக் கொடிய மகாசுரர்களை நான் விழுங்கும்போது என் பற்கள் மாதுளம்பூவைப் போலச் சிவக்கும்.”",
        '21.45': "“ஆகவே விண்ணுலகில் தேவர்களும் மண்ணுலகில் மனிதர்களும் என்னைத் துதித்து எப்போதும் ‘ரக்ததந்திகா’ (சிவந்த பல்லுடையவள்) என்று அழைப்பார்கள்.”",
        '21.46': "“மீண்டும் நூறு ஆண்டுகள் மழையின்றி நீரின்றி இருக்கும்போது முனிவர்களால் துதிக்கப்பட்டு, கருவில் பிறவாதவளாக நான் பூமியில் தோன்றுவேன்.”",
        '21.47': "“அப்போது நான் நூறு கண்களால் முனிவர்களை நோக்குவதால் மனிதர்கள் என்னை ‘சதாக்ஷீ’ (நூறு கண்ணுடையவள்) என்று போற்றுவார்கள்.”",
        '21.48': "“தேவர்களே, அப்போது மழை வரும்வரை என் உடலிலிருந்தே தோன்றிய, உயிரைக் காக்கும் கீரை காய்கறிகளால் (சாகங்களால்) உலகம் முழுவதையும் காப்பேன்.”",
        '21.49': "“அப்போது நான் பூமியில் ‘சாகம்பரீ’ என்று புகழ்பெறுவேன்; அதே காலத்தில் துர்கமன் என்னும் மகாசுரனைக் கொல்வேன்.”",
        '21.50': "“அதனால் என் பெயர் ‘துர்கா தேவீ’ என்று புகழ்பெறும். மீண்டும் நான் இமயத்தில் கொடிய வடிவம் தாங்கி —”",
        '21.51': "“— முனிவர்களைக் காப்பதற்காக ராக்ஷஸர்களை விழுங்கும்போது, எல்லா முனிவர்களும் பணிந்து என்னைத் துதிப்பார்கள்.”",
        '21.52': "“அப்போது என் பெயர் ‘பீமா தேவீ’ என்று புகழ்பெறும். அருணன் என்னும் அசுரன் மூவுலகிலும் பெரும் துன்பம் விளைவிக்கும்போது —”",
        '21.53': "“— அப்போது நான் எண்ணற்ற வண்டுகளாலான ப்ரமர வடிவம் தாங்கி மூவுலகின் நன்மைக்காக அந்த மகாசுரனைக் கொல்வேன்.”",
        '21.54': "“அப்போது மக்கள் எங்கும் என்னை ‘ப்ராமரீ’ என்று துதிப்பார்கள். இவ்வாறு எப்போதெல்லாம் தானவர்களால் துன்பம் எழுகிறதோ —”",
        '21.55': "“— அப்போதெல்லாம் நான் அவதரித்துப் பகைவர்களை அழிப்பேன்.”",
        '21.56': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “தேவீ ஸ்துதி” என்னும் பதினொன்றாம் அத்தியாயம் நிறைவுற்றது.",
        '22.0': "ஓம். மின்னல் மாலை போல் ஒளிர்பவளும், சிங்கத்தின் தோளில் அமர்ந்தவளும், அச்சமூட்டுபவளும், வாளும் கேடயமும் ஏந்திய கன்னியரால் சேவிக்கப்படுபவளும், கைகளில் சக்கரம், கதை, வாள், கேடயம், அம்புகள், வில், பாசம், தர்ஜனீ முத்திரை ஆகியவற்றைத் தாங்கியவளும், அக்னி வடிவினளும், சந்திரனை அணிந்தவளுமான முக்கண் துர்கையை வழிபடுகிறேன்.",
        '22.1': "தேவி கூறினாள்:",
        '22.2': "“எவர் ஒருமுகப்பட்ட மனத்துடன் இந்தத் துதிகளால் நாள்தோறும் என்னைத் துதிக்கிறாரோ, அவருடைய எல்லாத் துன்பங்களையும் ஐயமின்றி அழிப்பேன்.”",
        '22.3': "“மது கைடபரின் அழிவையும், மகிஷாசுர வதத்தையும், அவ்வாறே சும்ப நிசும்ப வதத்தையும் எவர் போற்றிச் சொல்வார்களோ —”",
        '22.4': "“— அஷ்டமி, சதுர்தசி, நவமி திதிகளில் ஒருமுக மனத்துடன் பக்தியோடு என் இந்த உயர்ந்த மாஹாத்ம்யத்தை எவர் கேட்பார்களோ —”",
        '22.5': "“— அவர்களுக்கு எந்தப் பாவமும் நேராது, பாவத்தால் விளையும் ஆபத்துகளும் வராது; வறுமையும் அன்பர்களைப் பிரிதலும் ஏற்படாது.”",
        '22.6': "“அவருக்குப் பகைவர், கள்வர், அரசன் ஆகியோரிடமிருந்தோ, ஆயுதம், நெருப்பு, வெள்ளம் ஆகியவற்றிடமிருந்தோ ஒருபோதும் அச்சம் ஏற்படாது.”",
        '22.7': "“ஆகவே என் இந்த மாஹாத்ம்யத்தை ஒருமுகத்துடன் படிக்க வேண்டும், எப்போதும் பக்தியுடன் கேட்க வேண்டும்; ஏனெனில் அது மேலான மங்கள வழி.”",
        '22.8': "“என் இந்த மாஹாத்ம்யம் கொள்ளைநோயால் விளையும் எல்லாத் துன்பங்களையும், மூவகைத் தீய சகுனங்களையும் தணிக்கும்.”",
        '22.9': "“என் எந்த ஆலயத்தில் இது நாள்தோறும் முறையாகப் படிக்கப்படுகிறதோ அதை நான் ஒருபோதும் விடமாட்டேன்; அங்கே என் ஸாந்நித்யம் நிலைத்திருக்கும்.”",
        '22.10': "“பலி அர்ப்பணத்திலும், பூஜையிலும், அக்னி கார்யத்திலும், பெருவிழாவிலும் என் இந்தச் சரித்திரம் முழுவதையும் ஓத வேண்டும், கேட்கச் செய்ய வேண்டும்.”",
        '22.11': "“முறை அறிந்தவரோ அறியாதவரோ, இவ்வாறு செய்யப்பட்ட பலியையும் பூஜையையும் அக்னி ஹோமத்தையும் நான் மகிழ்வுடன் ஏற்பேன்.”",
        '22.12': "“சரத்காலத்தில் செய்யப்படும் ஆண்டு மகாபூஜையில் என் இந்த மாஹாத்ம்யத்தைப் பக்தியுடன் கேட்கும் —”",
        '22.13': "“— மனிதர் என் அருளால் எல்லாத் துன்பங்களிலிருந்தும் விடுபட்டுச் செல்வம், தானியம், மக்கள் ஆகியோருடன் கூடியவராவார்; இதில் ஐயமில்லை.”",
        '22.14': "“என் இந்த மாஹாத்ம்யத்தையும், மங்களமான என் அவதாரங்களையும், போர்களில் என் வீரத்தையும் கேட்டு மனிதன் அச்சமற்றவனாகிறான்.”",
        '22.15': "“என் மாஹாத்ம்யத்தைக் கேட்பவர்களின் பகைவர் அழிவர், நலம் உண்டாகும், அவர்கள் குலம் மகிழ்ந்திருக்கும்.”",
        '22.16': "“எல்லாச் சாந்தி கர்மங்களிலும், தீய கனவு கண்டபோதும், கொடிய கிரக தோஷங்களிலும் என் மாஹாத்ம்யத்தைக் கேட்க வேண்டும்.”",
        '22.17': "“துன்பங்களும் கொடிய கிரக தோஷங்களும் தணியும்; மனிதர்கள் கண்ட தீய கனவு நல்ல கனவாக மாறும்.”",
        '22.18': "“பாலகிரகங்களால் பீடிக்கப்பட்ட குழந்தைகளுக்கு இது அமைதி தரும்; மனிதர்களிடையே பிளவு ஏற்படும்போது நட்பை உண்டாக்கும் சிறந்த வழி இது.”",
        '22.19': "“இது எல்லாத் தீயோரின் வலிமையையும் அழிக்கும் மேலான வழி; இதை ஓதுவதாலேயே ராக்ஷஸர், பூதங்கள், பிசாசங்கள் அழியும்.”",
        '22.20': "“என் இந்த மாஹாத்ம்யம் முழுதும் என் ஸாந்நித்யத்தை உண்டாக்கும். பசு (பலி), மலர், அர்க்யம், தூபம், சிறந்த சந்தனம், தீபம் ஆகியவற்றாலும் —”",
        '22.21': "“— அந்தணர்க்கு உணவளித்தல், ஹோமங்கள், இரவும் பகலும் புனித நீர் தெளித்தல், மற்றும் பலவகை இன்பப் பொருள்கள், தானங்கள் ஆகியவற்றால் ஓராண்டில் எந்த —”",
        '22.22': "“— மகிழ்ச்சி எனக்கு ஏற்படுகிறதோ, அது இந்தப் புனிதச் சரித்திரத்தை ஒருமுறை கேட்பதாலேயே ஏற்படுகிறது. கேட்கப்பட்டால் இது பாவங்களைப் போக்கி ஆரோக்கியம் அருள்கிறது.”",
        '22.23': "“என் அவதாரங்களைப் போற்றுதல் தீய ஆவிகளிடமிருந்து காக்கும். தீய அசுரர்களை அழித்த போர்களில் என் சரித்திரத்தை —”",
        '22.24': "“— கேட்டால் மனிதர்களுக்குப் பகைவர்களால் அச்சம் ஏற்படாது. நீங்கள் செய்த துதிகளும், பிரம்மரிஷிகள் செய்த துதிகளும் —”",
        '22.25': "“— பிரம்மா செய்த துதிகளும் நல்ல புத்தியை அருள்கின்றன. காட்டிலோ, ஆளற்ற வழியிலோ காட்டுத்தீயால் சூழப்பட்டவனும் —”",
        '22.26': "“— ஆளற்ற இடத்தில் கள்வர்களால் சூழப்பட்டவனும், பகைவர்களால் பிடிக்கப்பட்டவனும், சிங்கம் புலிகளால் துரத்தப்பட்டவனும், காட்டில் காட்டு யானைகளால் துரத்தப்பட்டவனும் —”",
        '22.27': "“— சினமுற்ற அரசனால் கொல்லப்படக் கட்டளையிடப்பட்டவனும், சிறையில் கட்டுண்டவனும், பெருங்கடலில் கப்பலில் இருந்து காற்றால் அலைக்கழிக்கப்படுபவனும் —”",
        '22.28': "“— மிகக் கொடிய போரில் ஆயுதங்கள் விழும்போதும், எல்லாக் கொடிய துன்பங்களிலும், வேதனையால் வாடும்போதும் —”",
        '22.29': "“— என் இந்தச் சரித்திரத்தை நினைக்கும் மனிதன் இடரிலிருந்து விடுபடுவான். என் ஆற்றலால் சிங்கம் முதலியவையும், கள்வரும், பகைவரும் —”",
        '22.30': "“— என் சரித்திரத்தை நினைப்பவனிடமிருந்து தொலைவிலேயே ஓடிவிடுவர்.”",
        '22.31': "ரிஷி கூறினார்:",
        '22.32': "இவ்வாறு கூறிக் கடும் வீரமுடைய பகவதி சண்டிகை —",
        '22.33': "— தேவர்கள் பார்த்துக்கொண்டிருக்கையிலேயே அங்கேயே மறைந்தாள். அந்தத் தேவர்களும் அச்சம் நீங்கி முன்போலவே தத்தம் அதிகாரங்களை —",
        '22.34': "— பகைவர் கொல்லப்பட்டதால் யக்ஞ பாகங்களை அனுபவித்தவாறு ஏற்றனர். தேவர்களின் பகைவனான சும்பன் போரில் தேவியால் கொல்லப்பட்டதும் அசுரர்கள் —",
        '22.35': "— உலகை அழித்த மிகக் கொடியவனும் ஒப்பற்ற வீரனுமான அவனும், பெரும் வீரனான நிசும்பனும் கொல்லப்பட்டபோது, எஞ்சிய அசுரர்கள் பாதாளத்துக்குச் சென்றனர்.",
        '22.36': "அரசனே, இவ்வாறு அந்தப் பகவதி தேவி நித்யமானவளாயினும் மீண்டும் மீண்டும் தோன்றி உலகைக் காக்கிறாள்.",
        '22.37': "அவளாலேயே இந்த உலகம் மயங்குகிறது; அவளே உலகைப் பிறப்பிக்கிறாள். வேண்டும்போது அவள் ஞானத்தையும், மகிழும்போது வளத்தையும் அருள்கிறாள்.",
        '22.38': "மனிதர்களின் தலைவனே, மகாப்பிரளய காலத்தில் மகாமாரீ வடிவு கொள்ளும் அந்த மகாகாளியால் இந்தப் பிரபஞ்சம் முழுதும் நிறைந்துள்ளது.",
        '22.39': "உரிய காலத்தில் அவளே மகாமாரீ; பிறப்பற்ற அவளே படைப்பாகிறாள்; என்றுமுள்ள அவளே காலத்தில் உயிர்களைக் காக்கிறாள்.",
        '22.40': "வளமான காலத்தில் அவளே மனிதர்களின் இல்லங்களில் பெருக்கம் தரும் லக்ஷ்மி; இல்லாமைக் காலத்தில் அவளே அழிவுக்காக அலக்ஷ்மியாகிறாள்.",
        '22.41': "மலர், தூபம், சந்தனம் முதலியவற்றால் துதித்து வழிபடப்பட்ட அவள் செல்வத்தையும், மக்களையும், அறத்தில் நாட்டமுள்ள மனத்தையும், நற்கதியையும் அருள்கிறாள்.",
        '22.42': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “பலஸ்துதி” என்னும் பன்னிரண்டாம் அத்தியாயம் நிறைவுற்றது.",
        '23.0': "ஓம். உதய சூரிய மண்டலம் போல் ஒளிர்பவளும், நான்கு கைகளும் மூன்று கண்களும் உடையவளும், பாசம், அங்குசம், வரம், அபயம் ஆகியவற்றைத் தாங்கியவளுமான சிவையை வழிபடுகிறேன்.",
        '23.1': "ரிஷி கூறினார்:",
        '23.2': "“அரசனே, இவ்வாறு தேவியின் இந்த உயர்ந்த மாஹாத்ம்யத்தை உனக்குக் கூறினேன். இந்த உலகைத் தாங்கும் அந்தத் தேவி இத்தகைய ஆற்றல் உடையவள்.”",
        '23.3': "“பகவதி விஷ்ணுமாயையாலேயே ஞானமும் அருளப்படுகிறது. அவளாலேயே நீயும் இந்த வணிகனும் மற்ற விவேகிகளும் —”",
        '23.4': "“— மயங்குகிறீர்கள், மயங்கியுள்ளீர்கள், இனியும் மற்றவர்கள் மயங்குவார்கள். மகாராஜா, அந்தப் பரமேச்வரியைச் சரணடை.”",
        '23.5': "“வழிபடப்பட்டால் அவளே மனிதர்களுக்கு இன்பத்தையும் சுவர்க்கத்தையும் முக்தியையும் அருள்கிறாள்.”",
        '23.6': "மார்க்கண்டேயர் கூறினார்:",
        '23.7': "முனிவரின் இச்சொற்களைக் கேட்டு அரசன் ஸுரதன் —",
        '23.8': "— கடும் விரதங்களுடைய அந்த மகாபாக்யசாலியான ரிஷியை வணங்கி, அளவற்ற பற்றாலும் அரசு பறிக்கப்பட்டதாலும் மனம் வெறுத்து,",
        '23.9': "மாமுனிவரே, உடனே தவம் செய்யப் புறப்பட்டான்; அந்த வணிகனும் அன்னையின் தரிசனத்துக்காக நதிக்கரை மணல்திட்டில் தங்கினான்.",
        '23.10': "அந்த வணிகன் மேலான தேவீ ஸூக்தத்தை ஜபித்தவாறு தவம் செய்தான். அவ்விருவரும் அந்த மணல்திட்டில் தேவியின் மண் விக்ரகத்தை அமைத்து —",
        '23.11': "— மலர், தூபம், அக்னி, தர்ப்பணம் ஆகியவற்றால் அவளை வழிபட்டனர்; சில வேளை உண்ணாமலும், சில வேளை அளவோடு உண்டும், அவளிடமே மனத்தைச் செலுத்தி ஒருமுகப்பட்டிருந்தனர்.",
        '23.12': "தம் உடலின் குருதியால் நனைத்த பலியையும் அர்ப்பணித்தனர். இவ்வாறு தன்னடக்கமுள்ள அவ்விருவரும் மூன்று ஆண்டுகள் வழிபட்டபோது —",
        '23.13': "— உலகைத் தாங்கும் சண்டிகை மகிழ்ந்து நேரில் தோன்றிக் கூறினாள்.",
        '23.14': "தேவி கூறினாள்:",
        '23.15': "“அரசனே, குலத்தை மகிழ்விப்பவனே, நீங்கள் வேண்டுவது அனைத்தையும் என்னிடமிருந்து பெறுங்கள்; மகிழ்ந்த நான் அதை அருள்கிறேன்.”",
        '23.16': "மார்க்கண்டேயர் கூறினார்:",
        '23.17': "அப்போது அரசன் மறுபிறவியில் ஒருபோதும் அழியாத அரசையும், இப்பிறவியிலேயே பகைவர் படையை வலிமையால் அழித்துத் தன் சொந்த அரசையும் வரமாகக் கேட்டான்.",
        '23.18': "அந்த வணிகனும் உலகப் பற்றற்ற மனமுடைய அறிவாளியாக, ‘என்னுடையது’, ‘நான்’ என்னும் பற்றை நீக்கும் ஞானத்தை வேண்டினான்.",
        '23.19': "தேவி கூறினாள்:",
        '23.20': "“அரசனே, சில நாள்களிலேயே நீ உன் அரசைப் பெறுவாய்.”",
        '23.21': "“பகைவரைக் கொன்று அங்கே உன் அரசு அசையாது நிலைக்கும்.”",
        '23.22': "“இறந்த பின் மீண்டும் விவஸ்வான் (சூரிய) தேவனிடமிருந்து பிறப்பைப் பெற்று,”",
        '23.23': "“நீ பூமியில் ஸாவர்ணிகன் என்னும் மனுவாவாய்.”",
        '23.24': "“வணிகர்களில் சிறந்தவனே, நீ என்னிடம் விரும்பிய வரத்தை —”",
        '23.25': "“— உன் பரிபூரணத்துக்காக அருள்கிறேன்; உனக்கு ஞானம் உண்டாகும்.”",
        '23.26': "மார்க்கண்டேயர் கூறினார்:",
        '23.27': "இவ்வாறு அவ்விருவருக்கும் அவரவர் விரும்பிய வரத்தை அருளி,",
        '23.28': "அவர்களால் பக்தியுடன் துதிக்கப்பட்ட தேவி உடனே மறைந்தாள். இவ்வாறு தேவியிடமிருந்து வரம் பெற்ற க்ஷத்திரியர்களில் சிறந்த ஸுரதன்,",
        '23.29': "சூரியனிடமிருந்து பிறந்து ஸாவர்ணி மனுவாவான்.",
        '23.30': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “ஸுரதனுக்கும் வணிகனுக்கும் வரமளித்தல்” என்னும் பதின்மூன்றாம் அத்தியாயம் நிறைவுற்றது.",
        '24.0': "விநியோகம்: “அஹம்” என்று தொடங்கும் எட்டு ருக்குகள் கொண்ட இந்த ஸூக்தத்திற்கு அம்ப்ருண ரிஷியின் மகளான வாக் ரிஷி; ஸச்சிதானந்த ஸ்வரூபரான எங்கும் நிறைந்த பரமாத்மா தேவதை; இரண்டாவது ருக்கிற்கு ஜகதீ, மற்றவற்றுக்கு த்ரிஷ்டுப் சந்தஸ்; தேவீ மாஹாத்ம்ய பாராயணத்தில் இதன் விநியோகம்.",
        '24.1': "நான் ருத்திரர்களுடனும் வஸுக்களுடனும், ஆதித்யர்களுடனும் எல்லாத் தேவர்களுடனும் உலவுகிறேன். மித்திரன் வருணன் இருவரையும், இந்திரன் அக்னியையும், அச்வினிகள் இருவரையும் நானே தாங்குகிறேன்.",
        '24.2': "பொங்கும் ஸோமனையும், த்வஷ்டா, பூஷா, பகன் ஆகியோரையும் நானே தாங்குகிறேன். ஹவிஸ் அர்ப்பணித்துப் பக்தியுடன் ஸோமம் பிழியும் யஜமானனுக்கு நான் செல்வம் அருள்கிறேன்.",
        '24.3': "நானே அரசி, செல்வங்களைச் சேர்ப்பவள், அறிந்தவள், வழிபடத்தக்கோரில் முதன்மையானவள். தேவர்கள் என்னைப் பல இடங்களில் நிறுவியுள்ளனர்; பல வடிவங்களில் நிலைத்துப் பலவற்றில் நுழைகிறேன்.",
        '24.4': "என்னாலேயே ஒருவன் உண்கிறான், காண்கிறான், மூச்சுவிடுகிறான், சொல்லப்படுவதைக் கேட்கிறான். அறியாமலேயே அனைவரும் என்னுள் வசிக்கின்றனர். புகழ்பெற்றவனே, கேள்: நம்பத் தகுந்ததை உனக்குச் சொல்கிறேன்.",
        '24.5': "தேவர்களாலும் மனிதர்களாலும் வரவேற்கப்படும் இதை நானே அறிவிக்கிறேன்: நான் யாரை நேசிக்கிறேனோ அவனை வலியவனாக்குகிறேன், அவனைப் பிரம்மாவாக்குகிறேன், ரிஷியாக்குகிறேன், ஞானியாக்குகிறேன்.",
        '24.6': "வேதத்தை வெறுப்பவனை ருத்திரனின் அம்பு தாக்கும்படி அவன் வில்லுக்கு நான் நாணேற்றுகிறேன். மக்களுக்காகப் போர் புரிகிறேன்; வானிலும் பூமியிலும் நுழைந்துள்ளேன்.",
        '24.7': "இவ்வுலகின் உச்சியில் தந்தையைத் தோற்றுவிக்கிறேன்; என் மூலம் நீரில், கடலுக்குள் உள்ளது. அங்கிருந்து எல்லா உலகங்களிலும் பரவி, என் உயரத்தால் அந்த வானைத் தொடுகிறேன்.",
        '24.8': "எல்லா உலகங்களையும் பற்றிக்கொண்டு காற்றுப் போல் வீசுகிறேன்; வானுக்கு அப்பாலும் இப்பூமிக்கு அப்பாலும், என் மகிமையால் இவ்வளவு பெரியவளானேன்.",
        '24.9': "இவ்வாறு ருக்வேதத்தில் கூறப்பட்ட தேவீ ஸூக்தம் நிறைவுற்றது.",
        '25.0': "ஸ்விஷ்டக்ருத் முதல் பூர்ணாஹுதி வரையிலான உத்தராங்கத்தை (“ஹோமவிதி — பூர்வாங்க உத்தராங்கம்” பாடத்திலிருந்து) செய்து…",
        '26.0': "அர்க்யம் முதலியவற்றால், அலங்காரங்களால், கந்த–புஷ்ப–அக்ஷதைகளால், தூப–தீபங்களால், பல பக்ஷ்யங்களுடன் கூடிய நைவேத்யங்களால் (தேவியைப் பூஜிக்க வேண்டும்). (வைக்ருதிக ரஹஸ்யம், தேவீ பூஜை.)",
        '27.0': "மீதமுள்ள உத்தராங்கத்தை (“ஹோமவிதி — பூர்வாங்க உத்தராங்கம்” பாடத்திலிருந்து) நிறைவு செய்து…",
        '28.0': "தூபம், தீபம், நைவேத்யம், நீராஜனம் (ஆரத்தி), மந்திரபுஷ்பம், ப்ரதக்ஷிண நமஸ்காரங்களை ஸமர்ப்பிக்கிறேன்.",
        '28.1': "சுப காரியங்களுக்கு மீண்டும் வர உங்களை உங்கள் இடத்திற்குத் திரும்ப ப்ரதிஷ்டை செய்கிறேன். (கலச தேவதைகளின் உத்வாஸனம்.)",
        '29.0': "பிரதக்ஷிணமும் நமஸ்காரமும் செய்து, தலைமேல் கைகூப்பி, சலிப்பின்றி ஜகன்மாதாவிடம் மீண்டும் மீண்டும் மன்னிப்பு கோர வேண்டும். (வைக்ருதிக ரஹஸ்யம்)",
        '30.0': "ஐயோ, நான் மந்திரமும் அறியேன், யந்திரமும் அறியேன், ஒரு துதியும் அறியேன்; உன்னை அழைக்கவோ தியானிக்கவோ அறியேன், உன் மகிமைக் கதைகளையும் அறியேன்; உன் முத்திரைகளையும் அறியேன், உன்னை நோக்கிக் கதறவும் அறியேன். ஆனால் அன்னையே, இது மட்டும் அறிவேன்: உன்னைப் பின்பற்றுவது எல்லாத் துயரையும் போக்குகிறது.",
        '30.1': "விதிகளை அறியாமையாலும், செல்வமின்மையாலும், சோம்பலாலும், விதிக்கப்பட்டதைச் செய்ய இயலாமையாலும் உன் திருவடிகளிலிருந்து நழுவினேன். அனைவரையும் உயர்த்தும் அருள்மிக்க சிவையே, அன்னையே, இதைப் பொறுத்தருள். மகன் கெட்டவனாகலாம், ஆனால் தாய் ஒருபோதும் கொடியவளாவதில்லை.",
        '30.2': "அன்னையே, பூமியில் உனக்கு எளிய நேர்மையான பல மக்கள் உள்ளனர்; அவர்களிடையே நான் உன் மிகச் சஞ்சலமான மகன். ஆயினும் சிவையே, என்னைக் கைவிடுவது உனக்குத் தகாது. மகன் கெட்டவனாகலாம், ஆனால் தாய் ஒருபோதும் கொடியவளாவதில்லை.",
        '30.3': "உலகன்னையே, நான் உன் திருவடிகளுக்குச் சேவை செய்யவில்லை, உனக்கு மிகுந்த செல்வமும் தரவில்லை, தேவியே; ஆயினும் ஒப்பற்ற அன்பை எனக்குக் காட்டுகிறாய். மகன் கெட்டவனாகலாம், ஆனால் தாய் ஒருபோதும் கொடியவளாவதில்லை.",
        '30.4': "பலவித வழிபாடுகளால் குழம்பி, எண்பத்தைந்து வயதைக் கடந்த இப்போது மற்றத் தேவர்களை விட்டுவிட்டேன். இப்போதும் உன் அருள் வராவிடில், அன்னையே, கணேசனின் தாயே, வேறு ஆதரவின்றி நான் யாரிடம் அடைக்கலம் புகுவேன்?",
        '30.5': "அபர்ணையே, உன் மந்திர எழுத்துகள் காதில் நுழைந்த மாத்திரத்தில், புலையனும் தேன் போன்ற சொற்களுடன் சொல்வன்மையுடையவனாகிறான், ஏழையும் கோடிப் பொன்னுடன் நீண்ட காலம் அச்சமின்றித் திரிகிறான். அதுவே பலன் என்றால், அன்னையே, முறைப்படி அதை ஜபிப்பதன் பலனை யார் அறிவார்?",
        '30.6': "சுடலைச் சாம்பல் பூசி, நஞ்சை உணவாகக் கொண்டு, திசைகளை ஆடையாக்கி, சடை தரித்து, நாகராஜனை மாலையாக அணிந்து, கபாலம் ஏந்தி பூதங்களை ஆளும் பசுபதி “ஜகதீசன்” என்ற ஒரே பட்டத்தைப் பெற்றிருப்பது — பவானியே, உன் கையைப் பிடித்து மணந்ததன் பலனே.",
        '30.7': "நான் முக்தியை விரும்பவில்லை, உலகியல் வைபவத்தையும் விரும்பவில்லை; சந்திர முகத்தவளே, ஞானத்தையும் நாடவில்லை, இன்பத்தையும் நாடவில்லை. ஆகவே அன்னையே, இதை மட்டுமே உன்னிடம் வேண்டுகிறேன்: “ம்ருடானீ, ருத்ராணீ, சிவ, சிவ, பவானீ” என்று ஜபித்தவாறு என் வாழ்வு கழியட்டும்.",
        '30.8': "பலவித உபசாரங்களால் உன்னை முறைப்படி வழிபடவில்லை; கடுஞ்சொற்களாலும் இரக்கமற்ற எண்ணங்களாலும் நான் செய்யாதது என்ன? ஆயினும் கருநிறத் தேவியே, ஆதரவற்ற என்னிடம் சிறிது கருணை காட்டினால் அது உனக்கு மட்டுமே தகும், அன்னையே.",
        '30.9': "துன்பங்களில் மூழ்கி, அரசியும் கருணைக் கடலுமான துர்கையே, உன்னை நினைக்கிறேன். இது என் வஞ்சகம் என்று எண்ணாதே: பசியாலும் தாகத்தாலும் வாடும் குழந்தைகள் தாயையே நினைக்கின்றனர்.",
        '30.10': "உலகன்னையே, என்னிடம் உன் கருணை நிறைந்திருப்பதில் வியப்பென்ன? மகன் குற்றத்தின் மேல் குற்றம் செய்தாலும் தாய் அவனைக் கைவிடுவதில்லை.",
        '30.11': "என்னைப் போன்ற பாவி இல்லை, உன்னைப் போல் பாவத்தை அழிப்பவளும் இல்லை. இதை அறிந்து, மகாதேவியே, உனக்குத் தக்கதைச் செய்.",
        '30.12': "இவ்வாறு ஸ்ரீ சங்கராசாரியர் இயற்றிய, குற்றங்களைப் பொறுக்கும்படி தேவியை வேண்டும் தேவ்யபராத க்ஷமாபன ஸ்தோத்திரம் நிறைவுற்றது.",
        '31.0': "இந்த சண்டிகா ஹோமத்தால் யஜ்ஞபுருஷனின் அந்தர்யாமியான பாரதீரமண முக்யப்ராணாந்தர்கதரான ஹரிணீபதி ஸ்ரீபரசுராமர் மகிழட்டும். ஸ்ரீகிருஷ்ணார்ப்பணமஸ்து.",
        '32.0': "என்னால் செய்யப்பட்ட இந்த சண்டிகா ஹோமம் என்ற கர்மம் — ஓம் தத்ஸத் — ப்ரஹ்மார்ப்பணமாகட்டும்.",
      },
    },
    'pavamana-homa': {
      summary: "ப்ராயச்சித்தம் (ச்ராத்த நாளில் போல), சாந்தி அல்லது புஷ்டிக்காக மாத்வர் செய்யும் பவமான ஹோமம், செய்யும் வரிசையில்: நோக்கத்துடன் கூடிய ஸங்கல்பம், ஐந்து பவமான தேவதைகளுக்கும் (அக்னி, சந்திரன், பாரதீ, வாயு, ஹரி) பகவானின் ஐந்து ரூபங்களுக்கும் ஐந்து கலசங்கள், ஆஜ்யபாகம் வரையிலான பொது பூர்வாங்கம், ருக்வேத புருஷஸூக்தத்தின் பதினாறு ருக்குகளால் நெய் ஆஹுதி, பின் 610 பவமான மந்திரங்களில் (ருக்வேதம் 9.1–9.67, அனைத்தும் ஸ்வாஹாவுடன், ஸூக்த வரிசையில்) ஒவ்வொன்றுக்கும் ஒரு ஆஹுதி, பவமான கிலம், தர்ப்பணம், மாத்வ உத்தராங்கம்: ஸ்விஷ்டக்ருத், ப்ராயச்சித்தம், \"ஸமுத்ராதூர்மிః\" பூர்ணாஹுதி, உத்தர பூஜை, கலச நீர் ப்ரோக்ஷணம், ரக்ஷை, ஸமர்ப்பணம்.",
      verses: {
        '0.0': "பவமானீ ரிக்குகள் அறுநூற்றுப் பத்து; இவற்றை ஹோமம் செய்து ஜபிப்பவன் கொடிய ம்ருத்யு பயத்தையும் வெல்வான். (ரிக்வேத கிலம் 3.10.19)",
        '1.0': "யஜ்ஞபுருஷனின் அந்தர்யாமியான, பாரதீரமண முக்யப்ராணாந்தர்கதரான ஹரிணீபதி ஸ்ரீபரசுராமரின் தூண்டுதலால், அவர் மகிழ்ச்சிக்காக, என்னுடையவும் என் குடும்பத்தினுடையவும் ப்ராயச்சித்தத்திற்காக (அல்லது சாந்தி, புஷ்டிக்காக), புருஷஸூக்தம் மற்றும் ருக்வேத ஒன்பதாம் மண்டலத்தின் அறுநூற்றுப் பத்து பவமான மந்திரங்களின் ஒவ்வொரு ருக்கினாலும் நெய் (அல்லது எள்) ஹோமம் செய்யும் பவமான ஹோமத்தைச் செய்வேன்; அதன் அங்கமாகக் கலசஸ்தாபனம், ஸ்தண்டில ஸம்ஸ்காரம், அக்னிப்ரதிஷ்டை செய்வேன்.",
        '2.0': "ஓ வருணா, என் இந்த அழைப்பைக் கேள், இன்று எங்களுக்கு அருள்செய்; உன் பாதுகாப்பை விரும்பி உன்னை அழைக்கிறேன். (ரிக்வேதம் 1.25.19; கலசத்தில் வருண ஆவாஹனம்)",
        '2.1': "ஓம், அக்னிக்கு வணக்கம்; சந்திரனுக்கு; பாரதிக்கு; வாயுவுக்கு; ஹரிக்கு வணக்கம். (ஐந்து பவமான தேவதைகள், ஒவ்வொரு கலசத்திலும் ஒருவர்.)",
        '2.2': "ஓம், நாராயணன், வாஸுதேவன், ஸங்கர்ஷணன், ப்ரத்யும்னன், அனிருத்தன் ஆகியோருக்கு வணக்கம் — ஐந்து ப்ராணங்களுக்குள் உள்ள பகவானின் ஐந்து ரூபங்கள்.",
        '2.3': "தியானிக்கிறேன், ஆவாஹனம் செய்கிறேன்; ஆஸனம், பாத்யம், அர்க்யம், ஆசமனீயம், ஸ்நானம், வஸ்திரம், சந்தனம், புஷ்பங்கள், தூபம், தீபம், நைவேத்யம், தாம்பூலம் ஸமர்ப்பிக்கிறேன். (கலச தேவதையின் சுருக்கமான பூஜை.)",
        '3.0': "ஆஜ்யபாகம் வரையிலான பூர்வாங்கத்தை (“ஹோமவிதி — பூர்வாங்க உத்தராங்கம்” பாடத்திலிருந்து) செய்து…",
        '4.0': "இது பவமான ஸோமனுக்கு, எனக்கு அல்ல. (ஒவ்வொரு பவமான ஆஹுதிக்குப் பின் சொல்லும் த்யாகம்.)",
        '5.0': "ஸோமனே, இந்திரன் பருகப் பிழியப்பட்ட நீ மிக இனிய, மகிழ்வூட்டும் தாரையாகப் பெருகு.",
        '5.1': "அரக்கரை அழிப்பவனும் எல்லா மக்களையும் காண்பவனுமான ஸோமன் உலோகம் பூட்டிய மரப் பாத்திரமாகிய தன் இடத்தில் அமர்ந்தான்.",
        '5.2': "செல்வத்தை மிகுதியாக அளிப்பவனாக, வள்ளலாக, விருத்திரனை அழிப்பவரில் சிறந்தவனாக இரு; கொடையாளரின் செல்வத்தை எமக்குக் கொண்டு வா.",
        '5.3': "உன் சாற்றுடன் பெருந்தேவர்களின் விருந்தை நோக்கிப் பெருகு; வலிமையையும் புகழையும் நோக்கியும்.",
        '5.4': "நாள்தோறும் இதே நோக்கத்துடன் உன்னை நாடி வருகிறோம்; இந்துவே, எங்கள் நம்பிக்கைகள் உன்னிடம் உள்ளன.",
        '5.5': "சூரியனின் மகள் பெருகும் ஸோமனான உன்னை எப்போதும் விரித்த கம்பளி வடிகட்டியால் தூய்மைப்படுத்துகிறாள்.",
        '5.6': "பத்து மெல்லிய கன்னியர், சகோதரிகள் (பத்து விரல்கள்), தீர்க்கமான நாளின் வேள்வியில் அவனைப் பற்றுகின்றனர்.",
        '5.7': "கன்னியர் அவனை முன் செலுத்துகின்றனர், தோல் பையை ஊதுகின்றனர்; அவன் மூவகையான, தீங்கைத் தடுக்கும் தேன்.",
        '5.8': "கொல்லத்தகாத பசுக்கள், கறவைப் பசுக்கள், இந்திரன் பருகக் குழந்தையான ஸோமனைப் பாலால் அலங்கரிக்கின்றன.",
        '5.9': "இதன் களிப்பில் இந்திரன் எல்லாப் பகைவரையும் அழிக்கிறான்; அந்த வீரன் செல்வத்தை வழங்குகிறான்.",
        '6.0': "ஸோமனே, தேவர்களை நாடி வேகமாக வடிகட்டியின் வழியே பெருகு; இந்துவே, காளையாக இந்திரனுள் புகு.",
        '6.1': "இந்துவே, மிக ஒளிமிக்க காளையே, உன் பெரும் உணவைப் பரப்பு; உறுதியாக உன் இடத்தில் அமர்.",
        '6.2': "பிழியப்பட்ட ஞானியின் தாரை இனிய தேனைப் பொழிந்தது; திறமையுள்ளவன் நீரை ஆடையாக அணிந்தான்.",
        '6.3': "நீ பாலால் போர்த்தப்படும்போது, பெருநீர்களாகிய நதிகள் பெரியவனான உன்னை நோக்கிப் பெருகுகின்றன.",
        '6.4': "வானத்தின் தூணும் தாங்கலுமான கடலாகிய ஸோமன் நீரில் தூய்மையாகிறான்; எம்மை விரும்பும் ஸோமன் வடிகட்டியில் உள்ளான்.",
        '6.5': "பொன்-பசும் நிறக் காளை முழங்கியது, நண்பனைப் போலப் பெரியது, காணத்தக்கது; சூரியனோடு ஒளிர்கிறது.",
        '6.6': "இந்துவே, செயலில் ஆர்வமுள்ள எங்கள் துதிகள் உன் வலிமையால் ஒளிர்கின்றன; அவற்றால் நீ களிப்புக்காக உன்னை அலங்கரிக்கிறாய்.",
        '6.7': "விரிந்த உலகைப் படைப்பவனான உன்னைக் களிப்புக்காக வேண்டுகிறோம்; உன் புகழ்ச்சிகள் பெரியவை.",
        '6.8': "இந்துவே, இந்திரனை நேசிப்பவனே, மழை நிறைந்த மேகம் போல எமக்காக இனிய தாரையாகப் பெருகு.",
        '6.9': "இந்துவே, நீ பசு, வீரர், குதிரை, வலிமை ஆகியவற்றை வென்று தருபவன்; வேள்வியின் தொன்மையான ஆன்மா நீயே.",
        '7.0': "இந்த அழிவற்ற தேவன் சிறகுள்ள பறவை போலப் பறந்து மரப் பாத்திரங்களில் அமரச் செல்கிறான்.",
        '7.1': "பாடகனால் ஆயத்தமான இந்தத் தேவன் எல்லாத் தடைகளையும் கடந்து ஓடுகிறான்; ஏமாற்ற முடியாத பவமானன் அவன்.",
        '7.2': "இந்தத் தேவனான பொன்னிறப் பவமானனை ருதத்தை விரும்பும் பாடகர்கள் வெற்றிப் பரிசுக்காகத் தூய்மைப்படுத்துகின்றனர்.",
        '7.3': "தன் வீரர்களுடன் செல்லும் வீரனைப் போலப் பவமானன் எல்லா நல்ல பொருள்களையும் வெல்ல விரும்புகிறான்.",
        '7.4': "இந்தத் தேவன் தேரை விரும்புகிறான்; பவமானன் கொடுக்கிறான், தன் ஒலியை வெளிப்படுத்துகிறான்.",
        '7.5': "ஞானியரால் போற்றப்பட்ட இந்தத் தேவன் நீரில் மூழ்குகிறான், வழிபடுபவனுக்கு ரத்தினங்களை அளிக்கிறான்.",
        '7.6': "இவன் தன் தாரையால் உலகங்களைக் கடந்து வானுக்கு ஓடுகிறான், பவமானன் முழங்கியபடி.",
        '7.7': "இவன் தடையின்றி உலகங்களைக் கடந்து வானெங்கும் பரவினான்; நல்ல வேள்வியின் பவமானன்.",
        '7.8': "தன் தொன்மையான பிறப்பால் தேவர்களுக்காகப் பிழியப்பட்ட இந்தப் பொன்னிறத் தேவன் வடிகட்டியில் பெருகுகிறான்.",
        '7.9': "பல செயல்கள் செய்யும் இவன் பிறந்தவுடனே உணவை உண்டாக்குகிறான்; பிழியப்பட்டுத் தாரையாகப் பெருகுகிறான்.",
        '8.0': "பவமான ஸோமனே, பெரும் புகழை வென்று தா; எம்மை மேலானவர்களாக்கு.",
        '8.1': "ஸோமனே, ஒளியையும் சுவர்க்கத்தையும் எல்லா நற்பேற்றையும் வென்று தா; எம்மை மேலானவர்களாக்கு.",
        '8.2': "ஸோமனே, திறமையையும் அறிவையும் தா, பகைவரை விரட்டு; எம்மை மேலானவர்களாக்கு.",
        '8.3': "தூய்மைப்படுத்துவோரே, இந்திரன் பருக ஸோமனைத் தூய்மைப்படுத்துங்கள்; எம்மை மேலானவர்களாக்கு.",
        '8.4': "உன் திட்பத்தாலும் காவலாலும் எமக்குச் சூரியனில் பங்கு தா; எம்மை மேலானவர்களாக்கு.",
        '8.5': "உன் திட்பத்தாலும் காவலாலும் நாங்கள் நெடுங்காலம் சூரியனைக் காண்போமாக; எம்மை மேலானவர்களாக்கு.",
        '8.6': "நல்ல ஆயுதமுள்ள ஸோமனே, இரட்டிப்புச் செல்வத்துடன் எம்மை நோக்கிப் பெருகு; எம்மை மேலானவர்களாக்கு.",
        '8.7': "ஒருபோதும் பின்வாங்காமல், போர்களில் வெல்பவனாகச் செல்வத்தை நோக்கிப் பெருகு; எம்மை மேலானவர்களாக்கு.",
        '8.8': "பவமானனே, அறத்தைத் தாங்குபவனே, வேள்விகளால் உன்னை வளர்த்தனர்; எம்மை மேலானவர்களாக்கு.",
        '8.9': "இந்துவே, குதிரைகள் நிறைந்த, வாழ்நாள் முழுதும் நிலைக்கும் அற்புதச் செல்வத்தை எமக்குக் கொண்டு வா; எம்மை மேலானவர்களாக்கு.",
        '9.0': "மூட்டப்பட்ட, அனைத்துக்கும் தலைவனான பவமானன் மகிழ்வித்து, காளையாக முழங்கியபடி ஒளிர்கிறான்.",
        '9.1': "தனூநபாத்தாகப் பவமானன் தன் கொம்புகளைக் கூர்மையாக்கியபடி, வானிடையில் ஒளிர்ந்தபடி பெருகுகிறான்.",
        '9.2': "போற்றத்தக்க பவமானன், செல்வ வடிவினன், தேன் தாரைகளாலும் வலிமையாலும் பிரகாசமாக ஒளிர்கிறான்.",
        '9.3': "வலிமையால் கிழக்கு நோக்கிய தர்ப்பையைப் பரப்பியபடி பொன்னிறப் பவமானத் தேவன் தேவர்களிடையே செல்கிறான்.",
        '9.4': "பவமானனால் நன்கு போற்றப்பட்ட தெய்வீகப் பொன் வாயில்கள் உயரத்தில் அகலத் திறக்கின்றன.",
        '9.5': "பெரிய, அழகாக அலங்கரிக்கப்பட்ட, காணத்தக்க இரவையும் விடியலையும் பவமானன் விரும்புகிறான்.",
        '9.6': "மனிதரைக் கண்காணிக்கும் இரு தெய்வீக ஹோதாக்களை அழைக்கிறேன்; பவமானனே காளையாகிய இந்திரன்.",
        '9.7': "பவமானனின் மூன்று அழகிய தேவியரான பாரதீ, ஸரஸ்வதீ, பெரும் இளா எங்கள் இந்த வேள்விக்கு வந்துள்ளனர்.",
        '9.8': "முதலில் பிறந்த, முன் செல்லும் காவலனான த்வஷ்டாவை அழைக்கிறேன்; இந்துவே இந்திரன், பொன்னிறக் காளை, பவமானன், ப்ரஜாபதி.",
        '9.9': "பவமானனே, ஆயிரம் கிளைகளுள்ள, பசுமையான, ஒளிரும், பொன்மயமான வனஸ்பதியை உன் தேன் தாரையால் அபிஷேகம் செய்.",
        '9.10': "எல்லாத் தேவர்களே, பவமானனின் ஸ்வாஹா அர்ப்பணத்திற்கு ஒன்றாக வாருங்கள்: வாயு, ப்ருஹஸ்பதி, சூரியன், அக்னி, இந்திரன்.",
        '10.0': "ஸோமனே, தேவர்களை நாடும் காளையே, எம்மை நேசித்தபடி கம்பளி வடிகட்டி வழியே மகிழ்வூட்டும் தாரையாகப் பெருகு.",
        '10.1': "இந்துவே, அந்தக் களிப்பூட்டும் மகிழ்ச்சியை நோக்கி, இந்திரனுடையவனாகப் பெருகு; வேகமான குதிரைகளை நோக்கியும்.",
        '10.2': "பிழியப்படும்போது அந்தத் தொன்மையான மகிழ்ச்சியை நோக்கி வடிகட்டியில் பெருகு; வலிமையையும் புகழையும் நோக்கி.",
        '10.3': "துளிகளான இந்துக்கள் சரிவில் நீர் போல ஓடின; தூய்மையாகி இந்திரனை அடைந்தன.",
        '10.4': "பத்துக் கன்னியர் அவனைப் பந்தயக் குதிரை போலச் சீர்படுத்துகின்றனர்; அவன் மரப் பாத்திரத்தில், கம்பளியைக் கடந்து விளையாடுகிறான்.",
        '10.5': "பிழிந்த அந்த வலிய சாற்றைக் களிப்புக்காக, தேவர் விருந்துக்காக, வெற்றிக்காகப் பாலுடன் கல.",
        '10.6': "பிழியப்பட்ட தேவன் தன் சாறு பெருகும்போது இந்திரத் தேவனை நோக்கித் தாரையாகப் பெருகுகிறான்.",
        '10.7': "வேள்வியின் ஆன்மா வேகமாகப் பிழியப்பட்டுப் பெருகுகிறது; அவன் தொன்மையான ஞானத்தைக் காக்கிறான்.",
        '10.8': "இவ்வாறு தூய்மையாகி, இந்திரனை நேசிப்பவனே, மிக மகிழ்வூட்டுபவனே, விருந்துக்காகப் பெருகு; மறைந்த துதிகளையும் நீ தாங்குகிறாய்.",
        '11.0': "அழகிய இந்துக்கள் ருதத்தின் பாதையில், அதன் வழியை அறிந்து, பெருக்கப்பட்டன.",
        '11.1': "தேனின் முதன்மைத் தாரை பெருநீர்களில் மூழ்குகிறது; அவிகளில் வணங்கத்தக்க அவி அதுவே.",
        '11.2': "இணைந்த சொற்களில் முதன்மையான காளை மரப் பாத்திரத்தில் முழங்கியது; சத்தியனான அவன் தன் இடமான வேள்விக்குச் செல்கிறான்.",
        '11.3': "கவி பாக்களையும் வீரியங்களையும் அணிந்து சுற்றிப் பெருகும்போது, அந்தக் குதிரை சுவர்க்கத்தை வெல்ல விரும்புகிறது.",
        '11.4': "ஞானியர் அவனைத் தூண்டும்போது, மன்னன் குடிகள் மேல் போலப் பவமானன் எதிரிகள் மேல் அமர்கிறான்.",
        '11.5': "அன்பான பொன்னிறத்தான் கம்பளியின் மேல், மரப் பாத்திரங்களில் அமர்கிறான்; பாடுவோன் துதியால் வசமாகிறான்.",
        '11.6': "அவன் தன் களிப்புடன் வாயு, இந்திரன், அச்வினிகளிடம் செல்கிறான்; அவன் நெறிகளில் மகிழ்வோரிடம்.",
        '11.7': "தேனின் அலைகள் அவன் ஆற்றல்களை அறிந்து மித்ரன், வருணன், பகன் ஆகியோரை நோக்கிப் பெருகுகின்றன.",
        '11.8': "வானமே, மண்ணே, எமக்காகச் செல்வம், தேன், வலிமை, புகழ், ஐச்வர்யம் ஆகியவற்றை வென்று தாருங்கள்.",
        '12.0': "இந்த ஸோமங்கள் இந்திரனின் அன்பான விருப்பத்தை நோக்கிப் பெருகின, அவன் வீரியத்தை வளர்த்தபடி.",
        '12.1': "தூய்மையாகி, கலங்களில் அமர்ந்து, வாயுவிடமும் அச்வினிகளிடமும் செல்லும் அவை எமக்கு வீர வலிமை தரட்டும்.",
        '12.2': "ஸோமனே, தூய்மையாகியபடி இந்திரனின் இதயத்தைக் கொடைக்குத் தூண்டு, ருதத்தின் இருப்பிடத்தில் அமர.",
        '12.3': "பத்து விரல்கள் உன்னைச் சீர்படுத்துகின்றன, ஏழு துதிகள் தூண்டுகின்றன; ஞானியர் மகிழ்ந்தனர்.",
        '12.4': "கம்பளியைக் கடந்து வரும் உன்னைத் தேவர்களின் களிப்புக்காகப் பாலால் போர்த்துகிறோம்.",
        '12.5': "கலசங்களில் தூய்மையான சிவந்த பொன்னிறத்தான் பால் ஆடைகளை அணிந்தான்.",
        '12.6': "எமக்காக, கொடையாளருக்காகப் பெருகு; எல்லாப் பகைவரையும் விரட்டு; இந்துவே, உன் நண்பனுள் புகு.",
        '12.7': "வானிலிருந்து மழையையும் மண்ணில் ஒளியையும் பொழி; ஸோமனே, போர்களில் எமக்கு வலிமை தா.",
        '12.8': "மனிதரைக் காண்பவனும் இந்திரன் பருகியவனும் சுவர்க்கம் காண்பவனுமான உன்னிடமிருந்து நாங்கள் சந்ததியையும் உணவையும் பெறுவோமாக.",
        '13.0': "இரு உலகங்களுக்கிடையே வைக்கப்பட்ட கவி வானின் அன்பான வடிவங்களைச் சுற்றிச் செல்கிறான்; பிழியப்பட்டு ஞானத் திறனுடன் செல்கிறான்.",
        '13.1': "துதிப்பவனும் தீங்கு செய்யாதவனுமான மனிதனின் இருப்பிடத்திற்காக மிக இனிய உணவுடன் பெருகு.",
        '13.2': "தூய மகன் பிறந்து தன் இரு அன்னையரான, ருதத்தை வளர்க்கும் பெரும் உலகங்களை ஒளிரச் செய்தான்.",
        '13.3': "ஏழு துதிகளால் தூண்டப்பட்ட அவன் ஒரே கண்ணை (சூரியனை) வளர்த்த கபடமற்ற நதிகளை உயிர்ப்பித்தான்.",
        '13.4': "இந்திரனே, வெல்ல முடியாத இளைஞனை (ஸோமனை) பெருஞ்செயலுக்காக உன் நெறியில் அவை நிறுத்தின.",
        '13.5': "அழிவற்ற சுமப்பவன் ஏழையும் (நதிகளை) காண்கிறான்; அவன் தெய்வீக நீர்களைத் திருப்தி செய்தான்.",
        '13.6': "வீரமுள்ள ஸோமனே, எங்கள் பணிகளில் உதவு; இருள்களை எதிர்த்துப் போரிட வேண்டும்; தூய்மையாகியபடி அவற்றை அழி.",
        '13.7': "புதிய, மிகப் புதிய துதிக்காக வழிகளை எளிதாக்கு; முன்போல ஒளிகளை ஒளிரச் செய்.",
        '13.8': "பவமானனே, நீ பெரும் புகழையும் பசு, குதிரை, வீரரையும் தருகிறாய்; அறிவையும் சுவர்க்கத்தையும் வென்று தா.",
        '14.0': "தேர்கள் போல, புகழை நாடும் பந்தயக் குதிரைகள் போல, பிழிந்த ஸோமங்கள் செல்வத்திற்காக முன்னேறின.",
        '14.1': "தேர்கள் போலத் தூண்டப்பட்ட அவை பாடகரின் பரிசுகள் போல இரு கைகளில் பிடிக்கப்பட்டன.",
        '14.2': "துதிகளால் மன்னர் அபிஷேகம் பெறுவது போல ஸோமங்கள் பாலால் அலங்கரிக்கப்படுகின்றன, ஏழு புரோகிதரால் வேள்வி போல.",
        '14.3': "பிழியப்பட்ட இந்துக்கள் வலிய துதியுடன் களிப்புக்காகத் தாரையாகப் பெருகுகின்றன.",
        '14.4': "விவஸ்வானின் பானங்களான அவை விடியலின் பேற்றைப் பிறப்பிக்கின்றன; சூரியர் போல நுண்ணிய இழையை விரிக்கின்றன.",
        '14.5': "தொன்மையான பாடகர்கள், காளையின் ஒளியுடைய மனிதர், துதிகளின் கதவுகளைத் திறக்கின்றனர்.",
        '14.6': "ஏழு உறவினரான ஹோதாக்கள் ஒன்றாக அமர்ந்து ஒருவனின் இடத்தை நிரப்புகின்றனர்.",
        '14.7': "அவன் எங்கள் நாபியை நாபியுடனும் கண்ணைச் சூரியனுடனும் இணைத்தான்; கவியின் சந்ததியை நான் கறக்கிறேன்.",
        '14.8': "சூரியன் தன் கண்ணால் புரோகிதர் மறைவாக வைத்த வானின் அன்பான இடத்தைக் காண்கிறான்.",
        '15.0': "மனிதர்களே, தேவர்களை வழிபட விரும்பும் இந்துவான பவமானனுக்குப் பாடுங்கள்.",
        '15.1': "அதர்வர்கள் உன் சாற்றைத் தேனுடன் கலந்தனர், தேவனுக்காகத் தேவர் விரும்பும் பானம்.",
        '15.2': "எமக்காகப் பெருகு: பசுவுக்கு நலம், மக்களுக்கு நலம், குதிரைக்கு நலம், அரசே, செடிகளுக்கு நலம்.",
        '15.3': "பழுப்பு நிறமுள்ள, தன்வலிமையுள்ள, சிவந்த, வானைத் தொடும் ஸோமனுக்குப் பாடல் பாடுங்கள்.",
        '15.4': "கைகளால் இயக்கும் கற்களால் பிழிந்த ஸோமனைத் தூய்மைப்படுத்துங்கள்; இனிமையை இனிமையில் ஊற்றுங்கள்.",
        '15.5': "வணக்கத்துடன் அணுகுங்கள், தயிருடன் கலவுங்கள்; இந்துவை இந்திரனுள் வையுங்கள்.",
        '15.6': "பகைவரை அழிப்பவனே, அனைத்தும் காண்பவனே, ஸோமனே, பசுவுக்கு நலமாக, தேவர்களின் விருப்பம் நிறைவேற்றியபடி பெருகு.",
        '15.7': "ஸோமனே, இந்திரன் பருகவும் களிக்கவும் நீ ஊற்றப்படுகிறாய்; நீ மனமும் மனத்தின் தலைவனும்.",
        '15.8': "பவமான ஸோமனே, வீரருடன் கூடிய செல்வத்தை எமக்குத் தா; இந்துவே, இந்திரனை எம் துணையாக்கி.",
        '16.0': "பிழிந்த ஸோமத் துளிகள் ருதத்தின் இருப்பிடத்தில் ஊற்றப்பட்டன, இந்திரனுக்கு மிக இனியவை.",
        '16.1': "தாய்ப் பசுக்கள் கன்றுக்காகக் கதறுவது போல ஞானியர் ஸோமம் பருக இந்திரனை அழைத்தனர்.",
        '16.2': "களிப்பைச் சொட்டும் ஞானி நதியின் அலையில், தன் இடத்தில் வசிக்கிறான்; ஸோமன் கௌரியின் (வாக்கின்) மேல் நிலைத்தவன்.",
        '16.3': "வானின் நாபியில் தொலைநோக்குடைய ஸோமன் கம்பளியின் மேல் போற்றப்படுகிறான்; அவன் நற்செயலன், கவி.",
        '16.4': "கலசங்களுக்குள்ளும் வடிகட்டியிலும் வைத்த ஸோமனை இந்து தழுவினான்.",
        '16.5': "இந்து கடலின் உச்சியில் தன் குரலை எழுப்புகிறான், தேன் சொட்டும் கலத்தை உயிர்ப்பித்தபடி.",
        '16.6': "எப்போதும் போற்றப்படும் வனஸ்பதி துதிகளுக்குள் அமுதம் சுரந்தபடி மனிதத் தலைமுறைகளைத் தூண்டுகிறான்.",
        '16.7': "தூண்டப்பட்ட கவி ஸோமன் பாடகனின் தாரையுடன் வானின் அன்பான இடங்களை நோக்கிப் பெருகுகிறான்.",
        '16.8': "பவமானனே, இந்துவே, ஆயிரம் ஒளிகளுடைய, எம்மிடம் நிலைக்கும் செல்வத்தைக் கொண்டு வா.",
        '17.0': "தூய்மையாகும் ஸோமன் ஆயிரம் தாரைகளில் கம்பளியைக் கடந்து வாயு, இந்திரனின் இருப்பிடத்திற்குப் பெருகுகிறான்.",
        '17.1': "காவலை நாடுவோரே, தேவர் விருந்துக்காகப் பிழியப்பட்ட ஞானி பவமானனைப் பாடுங்கள்.",
        '17.2': "ஆயிரம் ஆற்றல்களுடைய ஸோமங்கள் போற்றப்பட்டு, தேவர் விருந்துக்காக, வலிமையை வெல்லப் பெருகுகின்றன.",
        '17.3': "வலிமை வெல்ல, இந்துவே, எமக்கு மிகுந்த உணவையும் ஒளிமிக்க வீர வலிமையையும் பெருக்கு.",
        '17.4': "பிழியப்படும் தெய்வீக இந்துக்கள் எமக்கு ஆயிரம் மடங்கு செல்வத்தையும் வீர வலிமையையும் பெருக்கட்டும்.",
        '17.5': "ஓட்டுநர் செலுத்தும் பந்தயக் குதிரைகள் போல வேகமானவை பரிசுக்காகக் கம்பளி வழியே பெருக்கப்பட்டன.",
        '17.6': "கன்றை நோக்கிக் கதறும் பசுக்கள் போல இந்துக்கள் பெருகுகின்றன; இரு கைகளில் பிடிக்கப்பட்டன.",
        '17.7': "இந்திரனுக்கு இனியவனே, மகிழ்வூட்டும் பவமானனே, முழங்கியபடி எல்லாப் பகைவரையும் அழி.",
        '17.8': "கொடுக்காதவரை அழித்தபடி, ஒளியைக் காணும் பவமானர்களே, ருதத்தின் கருவறையில் அமருங்கள்.",
        '18.0': "நதியின் அலையில் நிலைத்த கவி பலர் விரும்பும் துதியைச் சுமந்து சுற்றிப் பெருகினான்.",
        '18.1': "செயலில் ஆர்வமுள்ள ஐந்து உறவுக் குலங்கள் துதியால் உறுதியானவனை அலங்கரிக்கும்போது...",
        '18.2': "...அப்போது வலியவனின் சாற்றில் எல்லாத் தேவர்களும் மகிழ்ந்தனர், அவன் பாலால் போர்த்தப்பட்டபோது.",
        '18.3': "வெளிப்பெருகி, தன் உடலின் உமியை விட்டு ஓடுகிறான்; இங்கே தன் துணைவனுடன் சேர்கிறான்.",
        '18.4': "விவஸ்வானின் மகள்களால் ஒளிரும் இளைஞன் போலச் சீர்படுத்தப்பட்டு, பாலைத் தன் ஆடையாக்குகிறான்.",
        '18.5': "சாய்ந்த வடிகட்டியைக் கடந்து நுண்ணிய விரல்களுடன் பாலை நோக்கிச் செல்கிறான்; தான் அறிந்த ஒலியை எழுப்புகிறான்.",
        '18.6': "விரல்கள் ஒன்றுகூடி உணவின் தலைவனைச் சீர்படுத்துகின்றன; குதிரையின் முதுகுகளைப் பற்றுகின்றன.",
        '18.7': "ஸோமனே, வானத்தின், மண்ணின் எல்லாச் செல்வங்களையும் பற்றி, எம்மை நேசித்தபடி வா.",
        '19.0': "இந்த வீரன் நுண்ணறிவுடன், வேகத் தேர்களுடன் இந்திரனின் இருப்பிடத்திற்குச் செல்கிறான்.",
        '19.1': "அமரர் அமரும் பெரும் தேவ வேள்விக்காக இவன் பெரிதும் சிந்திக்கிறான்.",
        '19.2': "வைக்கப்பட்ட அவன் ஒளிரும் பாதையில் உள்ளே அழைத்துச் செல்லப்படுகிறான், ஆர்வலர் அவனைத் தூண்டும்போது.",
        '19.3': "மந்தையின் இந்தக் காளை தன் கொம்புகளை ஆட்டிக் கூர்மையாக்குகிறது, வலிமையுடன் வீரியத்தைத் தாங்கியபடி.",
        '19.4': "இந்தக் குதிரை ஒளிரும் தண்டுகளுடன் செல்கிறது, நதிகளின் தலைவனாகியபடி.",
        '19.5': "கணுக்களைக் கடந்து இவன் உறுதியான செல்வங்களைக் கொண்டுவந்தபடி செடிகளிடையே இறங்குகிறான்.",
        '19.6': "சீர்படுத்தத்தக்க, பெரும் உணவைக் கொண்டு வரும் அவனை மனிதர் மரப் பாத்திரங்களில் சீர்படுத்துகின்றனர்.",
        '19.7': "நல்ல ஆயுதமுள்ள, மிக மகிழ்வூட்டும் அவனைப் பத்து விரல்களும் ஏழு துதிகளும் சீர்படுத்துகின்றன.",
        '20.0': "பிழிபவர்கள் பலகைகளிலிருந்து உன் சாற்றைத் துணிவுள்ளவனின் களிப்புக்காகப் பெருக்குகின்றனர்; அது வேகக் குதிரை போல ஓடுகிறது.",
        '20.1': "நீரை ஆடையாக அணிந்த தேரோட்டியை, பசுக்களை வெல்பவனை, நாங்கள் திறமையுடன் பின்தொடர்கிறோம்.",
        '20.2': "நீரில் இருந்தும் நனையாத, வெல்ல முடியாத ஸோமனை வடிகட்டியில் ஊற்றுங்கள்; இந்திரன் பருகத் தூய்மைப்படுத்துங்கள்.",
        '20.3': "தூய்மைப்படுத்துபவனின் சிந்தனையுடன் ஸோமன் வடிகட்டியில் பெருகுகிறான்; திறமையால் தன் இடத்தில் அமர்ந்தான்.",
        '20.4': "இந்திரனே, வணக்கங்களுடன் ஸோமத் துளிகள் உனக்காகப் பெருக்கப்பட்டன, பாடகனின் பெரும் போட்டிக்காக.",
        '20.5': "கம்பளி வடிவில் தூய்மையாகி, எல்லா எழில்களையும் நோக்கிப் பெருகியபடி, பசுக்களிடையே வீரன் போல நிற்கிறான்.",
        '20.6': "பொங்கும் வான் உச்சி போலப் பிழிந்த ஞானியின் தாரை இயல்பாக வடிகட்டியில் பெருகுகிறது.",
        '20.7': "ஸோமனே, மனிதரிடையே ஞானியைத் தூய்மைப்படுத்தியபடி நீ கம்பளி வழியே ஓடுகிறாய்.",
        '21.0': "சரிவில் நதிகள் போல, பகைவரை அழித்தபடி, வேகமான ஆர்வமுள்ள ஸோமங்கள் பெருக்கப்பட்டன.",
        '21.1': "மண்ணில் மழை போலப் பிழிந்த ஸோமத் துளிகள் இந்திரனை நோக்கிப் பெருகின.",
        '21.2': "பொங்கும் அலையுடன், மகிழ்வூட்டும் ஸோமன் அரக்கரை அழித்து, தேவர்களை நாடியபடி வடிகட்டியில் பெருகுகிறான்.",
        '21.3': "அவன் கலசங்களுக்குள் ஓடுகிறான், வடிகட்டியில் ஊற்றப்படுகிறான், வேள்விகளில் துதிகளால் வளர்கிறான்.",
        '21.4': "ஸோமனே, மூன்று ஒளிகளையும் கடந்து ஏறியபடி நீ வானில் ஒளிர்கிறாய்; இயங்கியபடி சூரியனைத் தூண்டுகிறாய்.",
        '21.5': "பாடகரான ஞானியர் வேள்வியின் உச்சியில் அவனைப் போற்றினர், தம் பார்வையில் அன்புடன் கொண்டு.",
        '21.6': "காவலை நாடும் ஞானியரான மனிதர் குதிரையான உன்னைத் தேவ சேவைக்காகத் துதிகளால் சீர்படுத்துகின்றனர்.",
        '21.7': "தேன் தாரையைத் தொடர்ந்து பெருகு; தீவிரனான நீ உன் இடத்தில் அமர்ந்தாய், அழகாக, ருதத்தின் பானத்திற்காக.",
        '22.0': "மலையில் வாழும் ஸோமன் பிழியப்பட்டு வடிகட்டியில் பெருகினான்; களிப்புகளில் நீ அனைத்தையும் அளிப்பவன்.",
        '22.1': "நீயே ஞானி, நீயே கவி; சாற்றிலிருந்து தேன் பிறந்தது; களிப்புகளில் நீ அனைத்தையும் அளிப்பவன்.",
        '22.2': "எல்லாத் தேவர்களும் ஒன்றாக உன்னைப் பருகினர்; களிப்புகளில் நீ அனைத்தையும் அளிப்பவன்.",
        '22.3': "விரும்பத்தக்க எல்லாச் செல்வங்களையும் தன் இரு கைகளில் கொண்டவன்: களிப்புகளில் நீ அனைத்தையும் அளிப்பவன்.",
        '22.4': "இந்த இரு பெரும் உலகங்களை இரு அன்னையர் போலக் கறப்பவன்: களிப்புகளில் நீ அனைத்தையும் அளிப்பவன்.",
        '22.5': "வலிமையுடன் ஒரே நேரத்தில் இரு உலகங்களையும் சுற்றிப் பெருகுபவன்: களிப்புகளில் நீ அனைத்தையும் அளிப்பவன்.",
        '22.6': "வலியவன் தூய்மையாகியபடி கலசங்களில் முழங்கினான்: களிப்புகளில் நீ அனைத்தையும் அளிப்பவன்.",
        '23.0': "ஸோமனே, வானம், மண் இவற்றின் அற்புதமான, போற்றத்தக்க செல்வம் எதுவோ அதைத் தூய்மையாகியபடி எமக்குக் கொண்டு வா.",
        '23.1': "இந்திரனே, ஸோமனே, நீங்கள் இருவரும் வானின் தலைவர், பசுக்களின் தலைவர்; ஆள்பவர்களாக எம் துதிகளைச் செழிக்கச் செய்யுங்கள்.",
        '23.2': "மனிதரிடையே தூய்மையாகும் காளை தர்ப்பையின் மேல் இடிமுழக்கமிட்டு, பொன்னிறத்தான் தன் இடத்தில் அமர்ந்தான்.",
        '23.3': "காளையின் விதையின் மேல் துதிகள் கதறின, மகனான கன்றின் அன்னையர்.",
        '23.4': "தூய்மையாகியபடி, ஒளிமிக்க பாலைச் சுரக்கும், காளையை நாடும் அவற்றில் அவன் கருவை வைத்தான்.",
        '23.5': "விலகி நிற்போருக்குக் கற்பி; பகைவரிடம் அச்சத்தை வை; பவமானனே, செல்வத்தைக் கண்டு தா.",
        '23.6': "ஸோமனே, பகைவன் தொலைவில் இருந்தாலும் அருகில் இருந்தாலும், அவன் வீரியம், வலிமை, வீறு இவற்றைக் குறை.",
        '24.0': "கவி எல்லா எதிரிகளையும் வென்றபடி தேவர் விருந்துக்காகக் கம்பளி வழியே பெருகுகிறான்.",
        '24.1': "ஏனெனில் அந்தப் பவமானன் பாடகருக்குப் பசுக்கள் நிறைந்த, ஆயிரம் மடங்கு பரிசைக் கொண்டு வருகிறான்.",
        '24.2': "நீ மனத்தால் அனைத்தையும் பற்றுகிறாய், அறிவுடன் பெருகுகிறாய்; ஸோமனே, எமக்குப் புகழைக் கண்டு தா.",
        '24.3': "கொடையாளருக்குப் பெரும் புகழையும் நிலையான செல்வத்தையும் பெருக்கு; துதிப்போருக்கு உணவு கொண்டு வா.",
        '24.4': "நல்ல விரதமுள்ள மன்னன் போல, ஸோமனே, நீ துதிகளுள் புகுந்தாய்; தூய்மையாகும் அற்புதச் சுமப்பவனே.",
        '24.5': "நீரில் வெல்ல முடியாத அந்தச் சுமப்பவன் கைகளில் சீர்படுத்தப்பட்டு, ஸோமன் கலங்களில் அமர்கிறான்.",
        '24.6': "திருவிழா போல விளையாடும், வள்ளலான நீ, ஸோமனே, துதிப்பவனுக்கு வீர வலிமை அளித்தபடி வடிகட்டிக்குச் செல்கிறாய்.",
        '25.0': "இந்திரனுக்காகத் துணிவுள்ள, மகிழ்வூட்டும், சுவர்க்கம் காணும் இந்த ஸோமத் துளிகள் ஓடுகின்றன.",
        '25.1': "தாக்குவோரை விரட்டியபடி, பிழிபவனுக்கு விரிவைக் கண்டபடி, துதிப்பவனுக்கு அவையே வீறு அளிக்கின்றன.",
        '25.2': "தடையின்றி விளையாடியபடி இந்துக்கள் நதியின் அலையில் ஒரே இடத்தை நோக்கிப் பெருகின.",
        '25.3': "இந்தப் பவமானர்கள் தேரில் பூட்டிய குதிரைகள் போல விரும்பத்தக்க அனைத்தையும் அடைந்தனர்.",
        '25.4': "இந்துக்களே, எமக்குக் கொடுக்காத இவனுக்கு வழிகாட்ட, இவனுள் பொன்னிற விருப்பத்தை வையுங்கள்.",
        '25.5': "ருபு புதிய தேரைப் போல வழிகாட்டலுக்கான நோக்கத்தை வையுங்கள்; ஒளியோரே, உங்கள் வெள்ளத்துடன் பெருகுங்கள்.",
        '25.6': "இவை முழங்கின; குதிரைகள் இலக்கை அடைந்தன; நல்லோனின் சிந்தையைத் தூண்டின.",
        '26.0': "இந்த வேகமான ஸோமங்கள் தேர்கள் போல, விடுவிக்கப்பட்ட பந்தயக் குதிரைகள் போல முன்பாய்ந்தன.",
        '26.1': "இவை காற்றுப் போல விரிவானவை, பர்ஜன்யனின் மழை போல, நெருப்பின் சுடர்கள் போலத் தடையின்றிச் சுழல்கின்றன.",
        '26.2': "தூய்மையான, ஞானமுள்ள, தயிர் கலந்த இந்த ஸோமங்கள் உள்நோக்குடன் துதிகளில் பரவின.",
        '26.3': "சீர்படுத்தப்பட்ட இந்த அமரர்கள் ஓடியபடி களைக்கவில்லை, வானின் வழிகளைக் கடக்க ஆர்வத்துடன்.",
        '26.4': "இவை பரவியபடி வானம்-மண்ணின் முதுகுகளையும் இந்த உயர்ந்த உலகையும் அடைந்தன.",
        '26.5': "சரிவுகளில் அவை நெய்யப்படும் மேலான இழையையும் இந்த உயர்ந்த இலக்கையும் அடைந்தன.",
        '26.6': "ஸோமனே, நீ பணிகளிடமிருந்து பசுச் செல்வத்தைப் பெற்றாய்; விரிந்த இழையை ஒலிக்கச் செய்தாய்.",
        '27.0': "வேகமான ஸோமங்கள் தேன், களிப்பின் தாரையாக எல்லாப் பாக்களையும் நோக்கிப் பெருக்கப்பட்டன.",
        '27.1': "தொன்மையானோர் புதிய இடத்திற்கு அடியெடுத்தனர்; ஒளிர்வதற்குச் சூரியனைப் பிறப்பித்தனர்.",
        '27.2': "பவமானனே, கொடுக்காத பகைவனின் இல்லத்தை எமக்குக் கொண்டு வா; எம் உணவைச் சந்ததி நிறைந்ததாக்கு.",
        '27.3': "ஸோமங்கள் களிப்பூட்டும் மகிழ்ச்சியை நோக்கி, தேன் சொட்டும் கலத்தை நோக்கிப் பெருகுகின்றன.",
        '27.4': "உறுதியான ஸோமன் இந்திர வலிமையைத் தாங்கிப் பெருகுகிறான்; நல்ல வீரன், பழிகளிலிருந்து காவலன்.",
        '27.5': "ஸோமனே, இந்திரனுக்காக, தேவர்களுக்காக, உடன் களிப்பவனாகப் பெருகுகிறாய்; இந்துவே, பரிசை வெல்ல விரும்புகிறாய்.",
        '27.6': "இந்தக் களிப்புகளைப் பருகி ஒப்பற்ற இந்திரன் பகைவரை அழித்தான், இன்னும் அழிக்கிறான்.",
        '28.0': "பவமான இந்துக்களான ஸோமங்கள் முன்னோடின; கலக்கப்பட்டு நீரில் சீர்படுத்தப்படுகின்றன.",
        '28.1': "சரிவில் செல்லும் நீர் போலப் பால் அவற்றை நோக்கி ஓடியது; தூய்மையாகி அவை இந்திரனை அடைந்தன.",
        '28.2': "பவமான ஸோமனே, இந்திரன் பருக முன்னோடுகிறாய்; மனிதரால் பிடிக்கப்பட்டு வழிநடத்தப்படுகிறாய்.",
        '28.3': "ஸோமனே, மனிதரை மகிழ்விக்கும் நீ மக்களை வெல்பவனுக்காகப் பெருகு; தூயவன், போற்றத்தக்கவன் நீ.",
        '28.4': "இந்துவே, கற்களால் பிழியப்பட்டு வடிகட்டியைச் சுற்றி ஓடும்போது நீ இந்திரனின் இருப்பிடத்திற்குப் போதுமானவன்.",
        '28.5': "விருத்திரனை அழிப்பவரில் சிறந்தவனே, துதிகளால் போற்றத்தக்கவனே, தூயவனே, தூய்மைப்படுத்துபவனே, அற்புதனே, பெருகு.",
        '28.6': "பிழிந்த தேனின் ஸோமன் தூயவன், தூய்மைப்படுத்துபவன் என்று அழைக்கப்படுகிறான்; தேவர்களின் நண்பன், தீயோரை அழிப்பவன்.",
        '29.0': "திறமையை நிறைவேற்றும் பொன்னிறத்தானே, தேவர்கள் பருகப் பெருகு; மருத்துகளுக்கும் வாயுவுக்கும் களிப்பாக.",
        '29.1': "பவமானனே, துதியால் தூண்டப்பட்டு, உன் இடத்தை நோக்கி முழங்கியபடி, உன் இயல்பால் வாயுவுள் புகு.",
        '29.2': "காளை தேவர்களுடன் ஒளிர்கிறது; கவி, தன் இடத்தில் அன்பானவன், விருத்திரனைக் கொன்றவன், தேவர்களுக்கு மிக இனியவன்.",
        '29.3': "எல்லா வடிவங்களிலும் புகுந்தபடி, அழகியவன் தூய்மையாகி அமரர் அமரும் இடத்திற்குச் செல்கிறான்.",
        '29.4': "சிவந்த ஸோமன் துதிகளைப் பிறப்பித்தபடி இடைவிடாது பெருகுகிறான், திறமையுள்ள ஞானியாக இந்திரனிடம் செல்கிறான்.",
        '29.5': "மிக மகிழ்வூட்டுபவனே, கவியே, துதியின் இருப்பிடத்தில் அமர வடிகட்டியில் தாரையாகப் பெருகு.",
        '30.0': "ஞானியர் அந்தக் குதிரையை அதிதியின் மடியில் நுண்ணறிவுடன் சீர்படுத்தினர்.",
        '30.1': "ஆயிரம் தாரைகளுடைய, குறையாத, வானைத் தாங்கும் இந்துவை நோக்கிப் பசுக்கள் கதறின.",
        '30.2': "அறிவால் அவர்கள் வானில் உறுதியான, அனைத்தையும் போஷிக்கும், ஞானி பவமானனைத் தூண்டினர்.",
        '30.3': "இரு கரங்களின் சிந்தனையால் அவர்கள் விவஸ்வானுடன் வாழும், வாக்கின் தலைவனான, ஏமாற்ற முடியாதவனைத் தூண்டினர்.",
        '30.4': "உச்சியில் சகோதரிகள் அழகிய, தொலைநோக்குடைய பொன்னிறத்தானைக் கற்களால் தூண்டுகின்றனர்.",
        '30.5': "பவமானனே, துதியால் வளர்ந்தவனே, இந்துவே, இந்திரனுக்கு மகிழ்வூட்டும் உன்னை ஞானியர் தூண்டுகின்றனர்.",
        '31.0': "போற்றப்பட்ட இந்தக் கவி வடிகட்டியில் பிழியப்படுகிறான், தூய்மையாகியபடி, பகைவரை அழித்தபடி.",
        '31.1': "சுவர்க்கத்தை வெல்லும் இவன் இந்திரன், வாயுவுக்காக வடிகட்டியில் ஊற்றப்படுகிறான், திறமையை நிறைவேற்றியபடி.",
        '31.2': "வானின் சிரமும் காளையும் பிழியப்பட்டவனுமான இவன் மனிதரால் அழைத்துச் செல்லப்படுகிறான்; மரத்திலுள்ள அனைத்தும் அறிந்த ஸோமன்.",
        '31.3': "பசுக்களையும் பொன்னையும் நாடும் பவமானன் முழங்கினான்; எப்போதும் வெல்பவன், வெல்லப்படாத இந்து.",
        '31.4': "இந்தப் பவமானன் வானில் சூரியனுடன் போட்டியிடுகிறான்; வடிகட்டியிலுள்ள மகிழ்வூட்டும் களிப்பு.",
        '31.5': "இந்த வலியவன் வானிடையில் பெருகினான்; பொன்னிறக் காளையான இந்து தூய்மையாகி இந்திரனை நோக்கி.",
        '32.0': "மனிதரால் தூண்டப்பட்ட, அனைத்தும் அறிந்த, மனத்தின் தலைவனான இந்தக் குதிரை கம்பளி வழியே ஓடுகிறது.",
        '32.1': "தேவர்களுக்காகப் பிழியப்பட்ட இந்த ஸோமன் எல்லா இருப்பிடங்களிலும் புகுந்தபடி வடிகட்டியில் பெருகினான்.",
        '32.2': "இந்த அழிவற்ற தேவன் தன் இடத்தில் அலங்கரிக்கப்படுகிறான்; விருத்திரனைக் கொன்றவன், தேவர்களுக்கு மிக இனியவன்.",
        '32.3': "முழங்கும் இந்தக் காளை பத்துச் சகோதரிகளால் செலுத்தப்பட்டு மரப் பாத்திரங்களை நோக்கி ஓடுகிறது.",
        '32.4': "அனைத்தும் காணும் இந்தப் பவமானன் சூரியனை ஒளிரச் செய்தான்; எல்லா இருப்பிடங்களையும் அறிந்தவன்.",
        '32.5': "வலியவனும் ஏமாற்ற முடியாதவனுமான இந்த ஸோமன் தூய்மையாகிப் பெருகுகிறான்; தேவர் நண்பன், தீயோரை அழிப்பவன்.",
        '33.0': "பிழிந்த இந்தக் காளையின் தாரைகள் வலிமையுடன், தேவர்களுக்குப் பணிந்தபடி பெருகின.",
        '33.1': "துதியால் புகழும் ஞானக் கவிகள் குதிரையைச் சீர்படுத்துகின்றனர்; அவன் பிறக்கும் போற்றத்தக்க ஒளி.",
        '33.2': "செல்வ ஸோமனே, உன்னைத் தூய்மைப்படுத்துவோனுக்கு உன் ஆற்றல்கள் எளியவை; போற்றத்தக்க கடலைப் பெருக்கு.",
        '33.3': "எல்லாச் செல்வங்களையும் வென்றபடி, ஸோமனே, தாரையாகப் பெருகு; எல்லாப் பகைமைகளையும் ஒருசேர விரட்டு.",
        '33.4': "கொடுக்காதவனிடமிருந்தும், எவருடைய கூச்சலிலிருந்தும், பழியிலிருந்தும் எம்மை நன்கு காப்பாற்று, நாங்கள் விடுபட.",
        '33.5': "இந்துவே, மண்ணுலக, விண்ணுலகச் செல்வத்தைத் தாரையாகப் பெருக்கு; ஒளிமிக்க வலிமையை எமக்குக் கொண்டு வா.",
        '34.0': "இந்த வலியவனின் தாரைகள் இயல்பாக வடிகட்டியில் பெருகின; தூய்மையாகியபடி அவன் குரலை எழுப்புகிறான்.",
        '34.1': "பிழிபவரால் தூண்டப்பட்ட, சீர்படுத்தப்படும் இந்து முழங்கியபடி இந்திரனுக்கு ஏற்ற ஒலியை எழுப்புகிறான்.",
        '34.2': "ஸோமனே, மனிதரை வெல்லும், வீரருடன் கூடிய, பலர் விரும்பும் வலிமையைத் தாரையாக எமக்குப் பெருக்கு.",
        '34.3': "பவமான ஸோமன் மரப் பாத்திரங்களில் அமர வடிகட்டியைக் கடந்து தாரையாகப் பெருகினான்.",
        '34.4': "இந்துவே, மிக இனிய பொன்னிறத்தானே, இந்திரன் பருக நீரில் கற்களால் உன்னைத் தூண்டுகின்றனர்.",
        '34.5': "வஜ்ரம் ஏந்திய இந்திரனுக்காக மிக இனிய, அழகிய, மகிழ்வூட்டும் ஸோமனை வலிமைக்காகப் பிழியுங்கள்.",
        '35.0': "சிந்தனையுள்ள பவமான ஸோமங்கள் முன்னேறின; கவனிக்கத்தக்க செல்வத்தைப் படைக்கின்றன.",
        '35.1': "இந்துவே, வானம்-மண்ணிலிருந்து ஒளியைப் பெருக்குபவனாக இரு; பரிசுகளின் தலைவனாக இரு.",
        '35.2': "உனக்காகக் காற்றுகள் இனிமையாக வீசுகின்றன, உனக்காக நதிகள் பெருகுகின்றன; ஸோமனே, அவை உன் பெருமையை வளர்க்கின்றன.",
        '35.3': "பெருகு; ஸோமனே, எல்லாப் பக்கங்களிலிருந்தும் வீரியம் உன்னை வந்தடையட்டும்; வலிமையின் கூடுகையில் இரு.",
        '35.4': "பழுப்பு நிறத்தானே, உயர்ந்த உச்சியில் உனக்காகப் பசுக்கள் குறையாத நெய்யையும் பாலையும் சுரந்தன.",
        '35.5': "இந்துவே, நல்ல ஆயுதமுள்ள, உலகின் தலைவனான உன் நட்பை நாங்கள் விரும்புகிறோம்.",
        '36.0': "களிப்பைச் சொட்டும் ஸோமங்கள் பிழியப்பட்டு வேள்வியில், கொடையாளரான எம் புகழுக்காக முன்னேறின.",
        '36.1': "அப்போது த்ரிதனின் கன்னியர் பொன்னிற இந்துவை இந்திரன் பருகக் கற்களால் தூண்டுகின்றனர்.",
        '36.2': "அப்போது அன்னம் தன் கூட்டத்தைப் போல அவன் அனைவரின் சிந்தையைத் தூண்டினான்; குதிரை போலப் பாலால் அலங்கரிக்கப்படுகிறான்.",
        '36.3': "ஸோமனே, இரு உலகங்களையும் நோக்கியபடி நீ வேகமான மான் போலப் பெருகுகிறாய், ருதத்தின் இருப்பிடத்தில் அமர்ந்தபடி.",
        '36.4': "பெண் தன் அன்பனைப் போலப் பசுக்கள் அவனை அழைத்தன; நியமித்தபடி அவன் போட்டிக்கு வந்தான்.",
        '36.5': "கொடையாளருக்கும் எனக்கும் ஒளிமிக்க புகழைத் தா: பேறு, அறிவு, கீர்த்தி.",
        '37.0': "ஞானமுள்ள ஸோமங்கள் நீர் அலைகள் போல, காடுகளுக்குச் செல்லும் எருமைகள் போல முன்னேறுகின்றன.",
        '37.1': "பழுப்பு நிற ஒளிமிக்க ஸோமங்கள் ருதத்தின் தாரையில் மரப் பாத்திரங்களை நோக்கி, பசுக்கள் நிறைந்த பரிசை நோக்கிப் பெருகின.",
        '37.2': "இந்திரன், வாயு, வருணன், மருத்துகளுக்காகப் பிழியப்பட்ட ஸோமங்கள் விஷ்ணுவை நோக்கிப் பெருகுகின்றன.",
        '37.3': "மூன்று குரல்கள் எழுகின்றன; கறவைப் பசுக்கள் கதறுகின்றன; பொன்னிறத்தான் முழங்கியபடி செல்கிறான்.",
        '37.4': "ருதத்தின் புனிதமான பெரும் அன்னையர் கதறினர்; அவர்கள் வானின் குழந்தையைச் சீர்படுத்துகின்றனர்.",
        '37.5': "ஸோமனே, எல்லாப் பக்கங்களிலிருந்தும் செல்வத்தின் நான்கு கடல்களை, ஆயிரம் மடங்காக, எமக்குப் பெருக்கு.",
        '38.0': "பிழியப்பட்ட இந்து தூண்டப்பட்டுத் தாரையாகப் பெருகுகிறான், வலிமையால் அரண்களை உடைத்தபடி.",
        '38.1': "இந்திரன், வாயு, வருணன், மருத்துகளுக்காகப் பிழியப்பட்ட ஸோமன் விஷ்ணுவை நோக்கிப் பெருகுகிறான்.",
        '38.2': "காளைகளால் பிடிக்கப்பட்ட காளையான ஸோமனைக் கற்களால் பிழிகின்றனர்; திறமையால் சாற்றைக் கறக்கின்றனர்.",
        '38.3': "அவன் த்ரிதனுக்குச் சீர்படுத்தத்தக்கவனாக, இந்திரனுக்கு மகிழ்வூட்டுபவனாக ஆகிறான்; பொன்னிறத்தான் வடிவங்களால் அலங்கரிக்கப்படுகிறான்.",
        '38.4': "ப்ருச்னியின் மக்கள் (மருத்துகள்) ருதத்தின் உச்சியான, அழகிய, மிக இனிய அவியான அவனைக் கறக்கின்றனர்.",
        '38.5': "இந்தத் துதிகள் நேராக, ஒன்றாகப் பெருகி அவனை அடைகின்றன; முழங்குபவன் பசுக்களைக் கதறச் செய்தான்.",
        '39.0': "பவமானனே, எமக்கு ஒளியைக் கண்டு தரும் விரிந்த செல்வத்தைத் தாரையாகப் பெருக்கு.",
        '39.1': "இந்துவே, கடலைக் கலக்கு; பெருகு, அனைத்தையும் இயக்கு; வலிமையுடன் எம் செல்வத்தைத் தாங்குபவனாக இரு.",
        '39.2': "வீரனே, வீரனான உன்னுடன் தாக்குவோரை நாங்கள் வெல்வோமாக; விரும்பத்தக்கதை எமக்குப் பெருக்கு.",
        '39.3': "விரதங்களையும் ஆயுதங்களையும் அறிந்த, வெல்ல விரும்பும் ரிஷி இந்து பரிசை அனுப்புகிறான்.",
        '39.4': "வாக்கைத் தூண்டும், தூய்மையாகும், மக்களின் பசுக்களுக்குத் தலைவனான ஸோமனைத் துதிகளால் போர்த்துகிறோம்.",
        '39.5': "ஒவ்வொரு மனிதனும் எவனுடைய நெறியில் நிலைக்கிறானோ அந்த அறத்தலைவன், தூய்மையாகும், செல்வமுள்ள ஸோமன்.",
        '40.0': "தேர்க் குதிரை போல அவன் விடுவிக்கப்பட்டான், கலங்களிலிருந்து வடிகட்டிக்குப் பிழியப்பட்டு; குதிரை இலக்கை அடைந்தது.",
        '40.1': "விழிப்புள்ள சுமப்பவனே, ஸோமனே, தேவர்களை நாடியபடி தேன் சொட்டும் கலத்தை நோக்கிப் பெருகு.",
        '40.2': "தொன்மையான பவமானனே, எமக்காக ஒளிகளை ஒளிரச் செய்; திட்பத்திற்கும் திறமைக்கும் எம்மைத் தூண்டு.",
        '40.3': "ருதத்தை விரும்புவோரால் அலங்கரிக்கப்பட்டு, கைகளில் சீர்படுத்தப்பட்டு, அவன் கம்பளி வடிகட்டியில் பெருகுகிறான்.",
        '40.4': "ஸோமன் வழிபடுபவனுக்கு வானம், மண், வானிடை ஆகியவற்றின் எல்லாச் செல்வங்களையும் பெருக்கட்டும்.",
        '40.5': "குதிரை, பசு, வீரரை நாடியபடி, வலிமையின் தலைவனான ஸோமனே, நீ வானின் முதுகில் ஏறுகிறாய்.",
        '41.0': "பருகப் பிழியப்பட்ட அந்தக் காளை ஸோமன் அரக்கரை அழித்து, தேவர்களை நாடியபடி வடிகட்டியில் பெருகுகிறான்.",
        '41.1': "தொலைநோக்குடைய, உறுதியான அந்தப் பொன்னிறத்தான் தன் இடத்தை நோக்கி முழங்கியபடி வடிகட்டியில் பெருகுகிறான்.",
        '41.2': "அந்தக் குதிரையான பவமானன் அரக்கரை அழிப்பவனாக, கம்பளி வழியே, வானின் ஒளிகளில் ஓடுகிறான்.",
        '41.3': "த்ரிதனின் உச்சியில் அந்தப் பவமானன் சகோதரிகளுடன் சூரியனை ஒளிரச் செய்தான்.",
        '41.4': "அந்த விருத்திரனைக் கொன்றவன், காளை, பிழியப்பட்டவன், விரிவைக் காண்பவன், ஏமாற்ற முடியாத ஸோமன் பரிசை நோக்கிப் போல ஓடினான்.",
        '41.5': "கவியால் அனுப்பப்பட்ட அந்தத் தேவனான இந்து தன் வள்ளன்மையால் இந்திரனுக்காக மரப் பாத்திரங்களை நோக்கி ஓடுகிறான்.",
        '42.0': "இந்தக் காளை, இந்தத் தேர், ஆயிரம் பரிசை நோக்கிச் சென்றபடி கம்பளி வழியே பெருகுகிறது.",
        '42.1': "த்ரிதனின் கன்னியர் பொன்னிற இந்துவை இந்திரன் பருகக் கற்களால் தூண்டுகின்றனர்.",
        '42.2': "செயலில் ஆர்வமுள்ள பத்து (விரல்கள்) அவனைச் சீர்படுத்துகின்றன; அவற்றால் அவன் களிப்புக்காக அலங்கரித்துக்கொள்கிறான்.",
        '42.3': "அவன் பருந்து போல மனித மக்களிடையே அமர்கிறான், காதலன் காதலியிடம் செல்வது போல.",
        '42.4': "களிப்பூட்டும் இந்தச் சாறு, வானின் குழந்தை, கீழே நோக்குகிறான்: கம்பளியில் புகுந்த இந்து.",
        '42.5': "பருகப் பிழியப்பட்ட, உறுதியான இந்தப் பொன்னிறத்தான் தன் அன்பான இடத்தை நோக்கி முழங்கியபடி பெருகுகிறான்.",
        '43.0': "பேரறிவாளனே, உன் அன்பான வடிவுடன், தேவர்கள் \"இங்கே\" என்னும் இடத்திற்கு வேகமாகப் பெருகு.",
        '43.1': "ஆயத்தமில்லாததை ஆயத்தமாக்கியபடி, மக்களுக்கு உணவு கொண்டு வந்தபடி, வானின் மழையைப் பொழி.",
        '43.2': "பிழியப்பட்ட அவன் வலிமையுடன் ஒளியைத் தாங்கி, தொலைநோக்குடன், ஒளிர்ந்தபடி வடிகட்டிக்கு வருகிறான்.",
        '43.3': "வானிலிருந்து வேகமாக வடிகட்டிக்கு வந்து நதியின் அலையில் பெருகியவன் இவனே.",
        '43.4': "தொலைவிலிருந்தும் அருகிலிருந்தும் வழிபடுவோனைத் தேடியபடி, பிழிந்த தேன் இந்திரனுக்காக ஊற்றப்படுகிறது.",
        '43.5': "ஒன்றாக அவர்கள் போற்றினர்; பொன்னிறத்தானைக் கற்களால் தூண்டுகின்றனர்; ருதத்தின் இருப்பிடத்தில் அமருங்கள்.",
        '44.0': "தூய்மையாகியபடி அனைத்தும் காண்பவன் எல்லாப் பகைவரையும் வென்றான்; ஞானியைத் துதிகளால் அலங்கரிக்கின்றனர்.",
        '44.1': "சிவந்தவன் தன் இடத்திற்கு ஏறினான்; பிழிந்த காளை இந்திரனிடம் செல்கிறது; உறுதியான இருக்கையில் அமர்கிறது.",
        '44.2': "இப்போது, இந்துவே, ஸோமனே, எல்லாப் பக்கங்களிலிருந்தும் ஆயிரம் மடங்கு பெருஞ்செல்வத்தை எமக்குப் பெருக்கு.",
        '44.3': "பவமான ஸோமனே, இந்துவே, எல்லா ஒளிகளையும் கொண்டு வா; ஆயிரம் மடங்கு உணவைக் கண்டு தா.",
        '44.4': "தூய்மையாகியபடி எமக்குச் செல்வத்தையும் துதிப்பவனுக்கு வீர வலிமையையும் கொண்டு வா; பாடகனின் துதிகளைப் பெருக்கு.",
        '44.5': "இந்துவே, தூய்மையாகியபடி இரட்டிப்புப் பெருஞ்செல்வத்தைக் கொண்டு வா; காளை இந்துவே, போற்றத்தக்கதை.",
        '45.0': "ஆர்வமுள்ள காளைகள் போல, ஒளிரும் வேகமுள்ளவையாக, கருந்தோலை (இருளை) விரட்டியபடி அவை முன்னேறின.",
        '45.1': "கடக்கக் கடினமான நல்வழிப் பாலத்தைக் கடப்பதை, நெறியற்ற பகைவனை வென்றபடி, நாங்கள் எண்ணுகிறோம்.",
        '45.2': "வலிய பவமானனின் ஒலி மழையின் ஒலி போலக் கேட்கிறது; வானில் மின்னல்கள் உலவுகின்றன.",
        '45.3': "இந்துவே, பிழியப்பட்ட நீ பசு, பொன், குதிரை, வலிமை நிறைந்த பெரும் உணவைப் பெருக்கு.",
        '45.4': "அனைத்தும் காண்பவனே, பெருகு; விடியலும் சூரியனும் கதிர்களால் போல இரு பெரும் உலகங்களையும் நிரப்பு.",
        '45.5': "ஸோமனே, காக்கும் உன் தாரையால், ரஸா நதி உலகைச் சூழ்வது போல எல்லாப் பக்கங்களிலும் எம்மைச் சூழ்ந்து பெருகு.",
        '46.0': "வானின் ஒளிகளைப் பிறப்பித்தபடி, நீரில் சூரியனைப் பிறப்பித்தபடி, பொன்னிறத்தான் பாலையும் நீரையும் அணிகிறான்.",
        '46.1': "தொன்மையான சிந்தனையுடன் இந்தத் தேவன் தேவர்களுக்காகப் பிழியப்பட்டுத் தாரையாகப் பெருகுகிறான்.",
        '46.2': "வளர்பவனுக்காக, வெற்றிக்காக, வலிமை வெல்ல ஆயிரம் ஆற்றல்களுடைய ஸோமங்கள் பெருகுகின்றன.",
        '46.3': "தொன்மையான பாலைக் கறந்தபடி அவன் வடிகட்டியில் ஊற்றப்படுகிறான்; முழங்கியபடி தேவர்களைப் பிறப்பித்தான்.",
        '46.4': "விரும்பத்தக்க அனைத்தையும் நோக்கி, ருதத்தை வளர்க்கும் தேவர்களை நோக்கி ஸோமன் தூய்மையாகிப் பெருகுகிறான்.",
        '46.5': "ஸோமனே, பிழியப்பட்ட நீ பசு, வீரர், குதிரை, வலிமை நிறைந்த மிகுந்த உணவை எமக்குப் பெருக்கு.",
        '47.0': "களிப்புக்காகப் பாலால் குதிரை போலச் சீர்படுத்தப்படும் அழகியவனை நாங்கள் துதிகளால் போர்த்துகிறோம்.",
        '47.1': "காவலை நாடும் எங்கள் எல்லாத் துதிகளும் இந்திரன் பருக இந்துவை முன்போல அலங்கரிக்கின்றன.",
        '47.2': "தூய்மையாகியபடி அழகிய ஸோமன் ஞானி மேத்யாதிதியின் துதிகளால் அலங்கரிக்கப்பட்டுச் செல்கிறான்.",
        '47.3': "பவமானனே, ஸோமனே, இந்துவே, ஆயிரம் ஒளிகளுடைய மாட்சிமிக்க செல்வத்தை எமக்குக் கண்டு தா.",
        '47.4': "பரிசை நோக்கி ஓடும் பந்தயக் குதிரை போல இந்து தேவர்களை நாடிப் பெருகும்போது வடிகட்டியில் முழங்குகிறான்.",
        '47.5': "துதிக்கும் பாடகனின் வளர்ச்சிக்காக, வலிமை வெல்லப் பெருகு; ஸோமனே, வீர வலிமை தா.",
        '48.0': "இந்துவே, அலையைச் சுமந்து, களைப்பின்றி எம் பெரும் குலத்திற்காகத் தேவர்களை நோக்கிப் பெருகுகிறாய்.",
        '48.1': "துதியால் வரவேற்கப்பட்டு, வேண்டுதலால் தூண்டப்பட்ட கவி ஸோமன் ஞானியின் தாரையில் தொலைவுக்கு அனுப்பப்படுகிறான்.",
        '48.2': "தேவர்களிடையே விழிப்புள்ள இவன் பிழியப்பட்டு வடிகட்டிக்கு வருகிறான்; அனைத்தும் காணும் ஸோமன் செல்கிறான்.",
        '48.3': "பரிசை நாடியபடி, வேள்வியை அழகாக்கியபடி எமக்காகப் பெருகு; தர்ப்பை விரித்தவன் உன்னை அழைக்கிறான்.",
        '48.4': "ஞானியரையே வீரராகக் கொண்ட, எப்போதும் வளரும் ஸோமன் தேவர்களிடையே எமக்காகப் பகனையும் வாயுவையும் வசப்படுத்தட்டும்.",
        '48.5': "இன்று செல்வம் பெற, திட்பம் அறிந்தவனே, வழி காண்போரில் சிறந்தவனே, நீ வலிமையையும் பெரும் புகழையும் வெல்கிறாய்.",
        '49.0': "மனிதரைக் காண்பவனே, இந்துவே, களிப்புக்காக, தேவர் விருந்துக்காக, இந்திரன் பருகப் பெருகு.",
        '49.1': "தூதுப் பணிக்காக எமக்குப் பெருகு; நீ இந்திரனுக்காகப் பிழியப்படுகிறாய்; நண்பர்களுக்காகத் தேவர்களின் சிறந்த வரங்களைக் கொண்டு வா.",
        '49.2': "சிவந்தவனான உன்னை நாங்கள் களிப்புக்காகப் பாலால் அலங்கரிக்கிறோம்; செல்வத்தின் கதவுகளை எமக்குத் திற.",
        '49.3': "ஓட்டத்தில் நுகத்தடிக் குதிரை போலக் குதிரை வடிகட்டியைக் கடந்தது; இந்து தேவர்களிடையே செல்கிறான்.",
        '49.4': "கம்பளியைக் கடந்து மரத்தில் விளையாடும் அவனை நண்பர்கள் அழைத்தனர்; துதிகள் இந்துவைப் போற்றின.",
        '49.5': "எந்தத் தாரையால் பருகப்பட்டு நீ தொலைவு வரை காண்கிறாயோ அதனால் பெருகு; இந்துவே, துதிப்பவனுக்கு வீர வலிமை தா.",
        '50.0': "தேவர் விருந்துக்காகத் திறமையான பந்தயக் குதிரைகள் போல, மலைகளில் வளர்ந்தவை பெருகியபடி பெருக்கப்பட்டன.",
        '50.1': "தந்தையின் சீதனமுள்ள கன்னி போல அலங்கரிக்கப்பட்ட ஸோமத் துளிகள் வாயுவுக்காகப் பெருக்கப்பட்டன.",
        '50.2': "உணவு நிறைந்த, கலங்களில் பிழியப்பட்ட இந்த ஸோமத் துளிகள் தம் செயல்களால் இந்திரனை வளர்க்கின்றன.",
        '50.3': "திறமையான கையுடையோரே, இங்கே ஓடி வாருங்கள்; கடையும் கோலால் ஒளிமிக்க பானங்களைப் பற்றுங்கள்; மகிழ்வூட்டுபவனைப் பாலுடன் கலவுங்கள்.",
        '50.4': "செல்வத்தை வெல்பவனே, பெருஞ்செல்வம் அளிப்பவனே, ஸோமனே, எமக்கு வழி காண்பவனே, பெருகு.",
        '50.5': "சீர்படுத்தத்தக்க, இந்திரனுக்கு மகிழ்வூட்டும் களிப்பான பவமானனைப் பத்து விரல்கள் சீர்படுத்துகின்றன.",
        '51.0': "இந்த நற்செயலால் ஸோமன் இன்னும் பெரிதாக வளர்ந்தான்; மகிழ்ந்து அவன் காளை போல நடந்துகொள்கிறான்.",
        '51.1': "செய்ய வேண்டிய அவன் செயல்கள், பகைவரை அழித்தல், தெரிகின்றன; துணிவுள்ளவன் கடன்களை வசூலிக்கிறான்.",
        '51.2': "அவன் துதி பிறக்கும்போது, இந்திரனுக்கான சாறான ஸோமன் ஆயிரத்தை வெல்லும் வஜ்ரமாகிறான்.",
        '51.3': "துதிகள் அவனைச் சீர்படுத்தும்போது கவி தானே தாங்குபவனிடமிருந்து ஞானிக்காக ரத்தினத்தை விரும்புகிறான்.",
        '51.4': "குதிரைகள் பரிசுகளை வெல்வது போல நீ செல்வத்தை வெல்ல விரும்புகிறாய்; போர்களில் நீ வெற்றியாளருடன் இருக்கிறாய்.",
        '52.0': "பெரும் வானின் இருப்பிடங்களில் வீரியங்களைத் தாங்கும் அழகியவனான உன்னை நற்செயல்களால் வேண்டுகிறோம்.",
        '52.1': "துணிவுள்ளோரை அடக்கும், போற்றத்தக்க, பெருநெறியுடைய, நூறு அரண்களை உடைக்கும் களிப்பு அவன்.",
        '52.2': "திறமையுள்ளவனே, அங்கிருந்து தளராத கருடன் மன்னனான உன்னை வானிலிருந்து செல்வத்தை நோக்கிக் கொண்டு வந்தான்.",
        '52.3': "ஒளியைக் காணும் அனைவருக்கும் பொதுவான, உலகங்களைக் கடக்கும் ருதக் காவலனைப் பறவை கொண்டு வந்தது.",
        '52.4': "அப்போது தூண்டப்பட்ட அவன் இந்திரனின் பெரும் மகிமையை அடைந்தான், விருப்பங்களை நிறைவேற்றும் அனைத்தும் காண்பவன்.",
        '53.0': "எமக்காக மழையையும் வானிலிருந்து நீர் அலையையும் நோயற்ற மிகுந்த உணவையும் பெருக்கு.",
        '53.1': "எந்தத் தாரையால் மக்களின் பசுக்கள் இங்கே எம் இல்லத்திற்கு வருமோ அதனால் பெருகு.",
        '53.2': "வேள்விகளில் தேவர்களுக்கு மிக இனியவனே, தாரையாக நெய்யைப் பெருக்கு; எமக்கு மழையைப் பெருக்கு.",
        '53.3': "எம் வலிமைக்காகக் கம்பளி வடிகட்டி வழியே தாரையாக ஓடு; தேவர்கள் நிச்சயம் கேட்பார்கள்.",
        '53.4': "பவமானன் அரக்கரை விரட்டியபடி, முன்போல ஒளிகளை ஒளிரச் செய்தபடி பெருகினான்.",
        '54.0': "நதி அலையின் முழக்கம் போல உன் ஆற்றல்கள் எழுகின்றன; யாழின் நரம்பைத் தூண்டு.",
        '54.1': "நீ கம்பளி உச்சிக்குச் செல்லும்போது, உன் புறப்பாட்டில் வேள்வியை நாடும் மூன்று குரல்கள் எழுகின்றன.",
        '54.2': "கம்பளியின் மேல் அன்பான, தேன் சொட்டும் பொன்னிறப் பவமானனைக் கற்களால் தூண்டுகின்றனர்.",
        '54.3': "மிக மகிழ்வூட்டுபவனே, கவியே, துதியின் இருப்பிடத்தில் அமர வடிகட்டியில் தாரையாகப் பெருகு.",
        '54.4': "மிக மகிழ்வூட்டுபவனே, பாலாலும் அதன் பூச்சுகளாலும் அலங்கரிக்கப்பட்டு, இந்துவே, இந்திரன் பருகப் பெருகு.",
        '55.0': "அத்வர்யுவே, கற்களால் பிழிந்த ஸோமத்தை வடிகட்டியில் ஊற்று; இந்திரன் பருகத் தூய்மைப்படுத்து.",
        '55.1': "வஜ்ரம் ஏந்திய இந்திரனுக்காக வானின் உயர்ந்த அமுதமான, மிக இனிய ஸோமத்தைப் பிழியுங்கள்.",
        '55.2': "இந்துவே, பவமானனே, உன் சாற்றின் அந்தத் தேனைத் தேவர்களும் மருத்துகளும் சுவைக்கின்றனர்.",
        '55.3': "ஸோமனே, களிப்புக்காகப் பிழியப்பட்ட நீ, காளையே, காவலுக்காகத் துதிப்பவனை வளர்க்கிறாய்.",
        '55.4': "தொலைநோக்குடையவனே, பிழியப்பட்ட நீ வலிமையையும் புகழையும் நோக்கி வடிகட்டியில் தாரையாகப் பெருகு.",
        '56.0': "வானில் வாழ்பவனே, செல்வத்தை வெல்பவனே, உன் சாற்றால் எமக்கு வலிமை கொண்டு வந்தபடி, பிழியப்பட்டு வடிகட்டியில் பெருகு.",
        '56.1': "அன்பானவனே, ஆயிரம் தாரைகளுடையவனே, உன் தொன்மையான வழிகளில் உன் தாரையுடன் கம்பளி வழியே செல்.",
        '56.2': "அவனைக் கொப்பரை போலக் கலக்கு; இந்துவே, உன் கொடையைக் கிளறி அளி; ஆயுதம் ஏந்தியவனே, ஆயுதங்களால் கலக்கு.",
        '56.3': "இந்துவே, பலரால் அழைக்கப்பட்டவனே, எம்மை அச்சுறுத்தும் அம்மக்களின் வலிமையைக் குறை.",
        '56.4': "இந்துவே, நூறு காவல்களுடன், அல்லது ஆயிரம் தூய காவல்களுடன், செல்வம் அளித்தபடி எமக்காகப் பெருகு.",
        '57.0': "கற்களின் தலைவனே, அரக்கனைப் பிளந்தபடி உன் ஆற்றல்கள் எழுந்தன; எதிர்ப்போரை விரட்டு.",
        '57.1': "இந்த வலிமையால் நீ அழிக்கிறாய்; தேர்ப் போரில் பரிசு வைக்கப்படும்போது, அச்சமற்ற இதயத்துடன் நான் போற்றுகிறேன்.",
        '57.2': "இந்தப் பவமானனின் நெறிகளைத் தீய எண்ணமுள்ளவன் தாக்க முடியாது; உன்னை எதிர்த்துப் போரிடுபவனை உடைத்தெறி.",
        '57.3': "களிப்பைச் சொட்டும், நதிகளிலுள்ள பொன்னிறக் குதிரையான, இந்திரனுக்கு மகிழ்வூட்டும் இந்துவை அவர்கள் தூண்டுகின்றனர்.",
        '58.0': "அவன் தொன்மையான ஒளியைப் பின்பற்றி ஆயிரத்தை வெல்லும் ரிஷியான ஒளிமிக்க பாலை அவர்கள் கறந்தனர்.",
        '58.1': "அவன் சூரியன் போலக் காணத்தக்கவன்; ஏரிகளை நோக்கி, ஏழு சரிவுகளை நோக்கி, வான் வரை ஓடுகிறான்.",
        '58.2': "தூய்மையாகியபடி ஸோமன் சூரியத் தேவனைப் போல எல்லா உலகங்களுக்கும் மேலே நிற்கிறான்.",
        '58.3': "தேவர் விருந்துக்காக, இந்திரனை நேசிக்கும் இந்துவே, தூய்மையாகியபடி நீ எமக்குப் பசுக்கள் நிறைந்த பரிசுகளைப் பெருக்குகிறாய்.",
        '59.0': "ஸோமனே, உன் சாற்றுடன் ஒவ்வொரு தானியத்தையும் ஒவ்வொரு ஊட்டத்தையும் எல்லா நற்பேறுகளையும் எமக்குப் பெருக்கு.",
        '59.1': "இந்துவே, உன் துதி எவ்வாறோ, உன் சாற்றின் பிறப்பு எவ்வாறோ அவ்வாறு, அன்பான தர்ப்பையில் அமர்.",
        '59.2': "பசுக்களைக் காண்பவனே, குதிரைகளைக் காண்பவனே, ஸோமனே, உன் சாற்றுடன் விரைவான நாட்களில் பெருகு.",
        '59.3': "வெல்பவனும் வெல்லப்படாதவனும், தாக்கிப் பகைவனைக் கொல்பவனுமான நீ, ஆயிரங்களை வெல்பவனே, பெருகு.",
        '60.0': "வேகமான ஸோமன் அரக்கரை அழித்து, தேவர்களை நாடியபடி பெரும் ருதத்தை நோக்கி வடிகட்டியில் பெருகுகிறான்.",
        '60.1': "ஸோமன் பரிசை நோக்கிப் பெருகும்போது, நூறு செயல்படும் தாரைகள் இந்திரனின் நட்பில் புகுந்தன.",
        '60.2': "கன்னி காதலனைப் போலப் பத்துக் கன்னியர் உன்னை அழைத்தனர்; ஸோமனே, வெற்றிக்காக நீ சீர்படுத்தப்படுகிறாய்.",
        '60.3': "இந்துவே, இந்திரனுக்கும் விஷ்ணுவுக்கும் இனியவனாகப் பெருகு; துதிக்கும் மக்களைத் துன்பத்திலிருந்து காப்பாற்று.",
        '61.0': "உன் இடைவிடாத தாரைகள் வானிலிருந்து மழை போல ஆயிரம் பரிசை நோக்கிச் செல்கின்றன.",
        '61.1': "எல்லா அன்பான பாக்களையும் நோக்கியபடி, பொன்னிறத்தான் தன் ஆயுதங்களைச் சுழற்றியபடி பெருகுகிறான்.",
        '61.2': "மனிதரால் சீர்படுத்தப்பட்டு, நல்ல நெறியுள்ள மன்னன் போல, வலியவனாக, அவன் காடுகளில் பருந்து போல அமர்கிறான்.",
        '61.3': "இந்துவே, தூய்மையாகியபடி வானத்தின், மண்ணின் எல்லாச் செல்வங்களையும் எமக்குக் கொண்டு வா.",
        '62.0': "அவன் கடத்துகிறான், மகிழ்வூட்டுபவன் ஓடுகிறான், பிழிந்த சாற்றின் தாரை; அவன் கடத்துகிறான், மகிழ்வூட்டுபவன் ஓடுகிறான்.",
        '62.1': "ஒளிரும் தேவி (விடியல்) மனிதரின் செல்வங்களையும் காவலையும் அறிவாள்; அவன் கடத்துகிறான், மகிழ்வூட்டுபவன் ஓடுகிறான்.",
        '62.2': "த்வஸ்ரனிடமிருந்தும் புருஷந்தியிடமிருந்தும் நாங்கள் ஆயிரங்களைப் பெறுகிறோம்; அவன் கடத்துகிறான், மகிழ்வூட்டுபவன் ஓடுகிறான்.",
        '62.3': "யாரிடமிருந்து நாங்கள் முப்பதாயிரம் ஆடைகளைப் பெறுகிறோமோ; அவன் கடத்துகிறான், மகிழ்வூட்டுபவன் ஓடுகிறான்.",
        '63.0': "பசுக்களையும் குதிரைகளையும் அனைத்தையும் வெல்பவனே, இன்பத்தை வெல்லும் ஸோமனே, பெருகு; சந்ததியுடன் ரத்தினத்தைக் கொண்டு வா.",
        '63.1': "ஏமாற்ற முடியாதவனே, நீர்களுக்காகப் பெருகு; செடிகளுக்காகப் பெருகு; புனிதக் கலங்களுக்காகப் பெருகு.",
        '63.2': "பவமான ஸோமனே, நீ எம்மை எல்லாத் துன்பங்களிலிருந்தும் கடத்து; கவியாகத் தர்ப்பையில் அமர்.",
        '63.3': "சுவர்க்கம் காணும் பவமானனே, பிறந்தவுடனே நீ பெரியவனானாய்; இந்துவே, நீ அனைவரையும் விஞ்சுகிறாய்.",
        '64.0': "அனைத்தும் காண்பவனான, ஆயிரம் கண்ணுடைய இந்துவான பவமானனைக் காயத்ரப் பாடலால் பாடுங்கள்.",
        '64.1': "ஆயிரம் கண்ணுடைய, ஆயிரத்தைத் தாங்கும் உன்னை அவர்கள் கம்பளி வழியே தூய்மைப்படுத்தினர்.",
        '64.2': "பவமானன் கம்பளியைக் கடந்து பெருகினான்; இந்திரனின் இதயத்தில் புகுந்தபடி கலசங்களை நோக்கி ஓடுகிறான்.",
        '64.3': "அனைத்தும் காணும் ஸோமனே, இந்திரனின் கொடைக்காக நலமாகப் பெருகு; சந்ததியுடன் விதையைக் கொண்டு வா.",
        '65.0': "இந்துவே, எவனுடைய களிப்புகளில் இந்திரன் தொண்ணூற்றொன்பது அரண்களை உடைத்தானோ அந்த நீ இந்த விருந்துடன் சுற்றிப் பெருகு.",
        '65.1': "பக்தனான திவோதாசனுக்காக உடனே அரண்களையும் சம்பரனையும், பின் துர்வசன், யது ஆகியோரையும் அவன் வென்றான்.",
        '65.2': "குதிரைகளை அறிந்தவனே, இந்துவே, எமக்குக் குதிரை, பசு, பொன் ஆகியவற்றைப் பெருக்கு; ஆயிரம் மடங்கு உணவைப் பெருக்கு.",
        '65.3': "வடிகட்டியை நனைக்கும் பவமானனான உன் நட்பை நாங்கள் தேர்ந்தெடுக்கிறோம்.",
        '65.4': "ஸோமனே, வடிகட்டி வழியே தாரையாகப் பெருகும் உன் அலைகளால் எம்மீது அருள் புரி.",
        '65.5': "அனைத்தையும் ஆளும் ஸோமனே, தூய்மையாகியபடி எமக்குச் செல்வத்தையும் வீரர் நிறைந்த உணவையும் கொண்டு வா.",
        '65.6': "நதிகளை அன்னையராகக் கொண்ட அவனைப் பத்து விரல்கள் சீர்படுத்துகின்றன; அவன் ஆதித்யருடன் காணப்பட்டான்.",
        '65.7': "பிழியப்பட்ட அவன் இந்திரன், வாயுவுடனும் சூரியக் கதிர்களுடனும் வடிகட்டிக்கு வருகிறான்.",
        '65.8': "எமக்காக, பகன், வாயு, பூஷன் ஆகியோருக்காக இனியவனாகப் பெருகு; மித்ரன், வருணனுக்கு அன்பானவனாக.",
        '65.9': "உன் சாற்றின் பிறப்பு உயர்ந்தது; வானில் இருப்பது மண்ணில் பெறப்பட்டது: வலிய அடைக்கலம், பெரும் புகழ்.",
        '65.10': "இதன் மூலம், வெல்ல விரும்பியபடி, நாங்கள் மனிதரின் எல்லா மாட்சிகளையும் அயலானிடமிருந்து பெறுகிறோம்.",
        '65.11': "வழிபடத்தக்க இந்திரனுக்காக, வருணன், மருத்துகளுக்காக, விரிவைக் காண்பவனே, எமக்காகச் சுற்றிப் பெருகு.",
        '65.12': "புதிதாகப் பிறந்த, நீர்களைக் கடக்கும், பாலால் அலங்கரிக்கப்பட்ட இந்துவிடம் தேவர்கள் வந்தனர்.",
        '65.13': "அன்னையர் கன்றைப் போல எங்கள் துதிகள் இந்திரனின் இதயத்தை வெல்லும் அவனை வளர்க்கட்டும்.",
        '65.14': "ஸோமனே, பசுவுக்கு நலமாகப் பெருகு; செழித்த உணவைக் கற; போற்றத்தக்க கடலைப் பெருக்கு.",
        '65.15': "பவமானன் வானின் அற்புத இடிபோல வைச்வானரனின் பெரும் ஒளியைப் பிறப்பித்தான்.",
        '65.16': "அரசே, பவமானனே, உன் சாறு, தீங்கற்ற களிப்பு, கம்பளி வடிகட்டி வழியே பெருகுகிறது.",
        '65.17': "பவமானனே, திறமையும் ஒளியும் உள்ள உன் சாறு அனைவரும் சுவர்க்கம் காண ஒளியாக ஒளிர்கிறது.",
        '65.18': "உன் சிறந்த களிப்புடன் உன் சாற்றால் பெருகு; தேவர் நண்பனே, தீயோரை அழிப்பவனே.",
        '65.19': "பகைவனான விருத்திரனைக் கொன்றவனே, நாள்தோறும் பரிசை வெல்பவனே, நீ பசுக்களையும் குதிரைகளையும் வெல்கிறாய்.",
        '65.20': "சிவந்தவனே, சாதுவான பசுக்களுடன் போலக் கலந்துகொள்; பருந்து போல உன் இடத்தில் அமர்.",
        '65.21': "பெரும் நீர்களை அடைத்த விருத்திரனைக் கொல்ல இந்திரனுக்கு உதவிய நீ பெருகு.",
        '65.22': "வள்ளலான ஸோமனே, நல்ல வீரருடன் நாங்கள் செல்வத்தை வெல்வோமாக; தூய்மையாகியபடி எம் துதிகளைப் பெருக்கு.",
        '65.23': "உன்னால் காக்கப்பட்டு, உன் உதவியால் நாங்கள் தாக்குவோரை வெல்வோமாக; ஸோமனே, எம் விரதங்களில் விழிப்புடன் இரு.",
        '65.24': "பகைவரை விரட்டியபடி, கொடுக்காதவரை விரட்டியபடி, இந்திரனின் இருப்பிடத்திற்குச் சென்றபடி ஸோமன் பெருகுகிறான்.",
        '65.25': "பவமானனே, எமக்குப் பெருஞ்செல்வத்தைக் கொண்டு வா; பகைவரை அழி; இந்துவே, வீரருடன் கூடிய புகழைத் தா.",
        '65.26': "நீ கொடை அளிக்க விரும்பும்போது, தூய்மையாகி வள்ளலாகும்போது, நூறு வஞ்சகரும் உன்னைத் தடுக்க முடியாது.",
        '65.27': "இந்துவே, பிழியப்பட்ட காளையே, பெருகு; மக்களிடையே எம்மைப் புகழுடையவர்களாக்கு; எல்லாப் பகைவரையும் அழி.",
        '65.28': "இந்துவே, உன் நட்பில், உன் உயர்ந்த ஒளியில் தாக்குவோரை நாங்கள் வெல்வோமாக.",
        '65.29': "அழிப்பதற்கான உன் பயங்கரமான, கூர்மையான ஆயுதங்களால் அனைவரின் பழியிலிருந்தும் எம்மைக் காப்பாற்று.",
        '66.0': "இந்த வேகமான இந்துக்கள் எல்லா நற்பேறுகளையும் நோக்கி வடிகட்டி வழியே பெருக்கப்பட்டன.",
        '66.1': "பல துன்பங்களை விரட்டியபடி, குதிரைகள் எம் குழந்தைகளுக்கும் குதிரைகளுக்கும் எளிய வழிகளை அமைக்கின்றன.",
        '66.2': "பசுவுக்கு விரிவை அமைத்தபடி, அவை நல்ல துதியை நோக்கியும் எமக்கு மிகுந்த ஊட்டத்தை நோக்கியும் பெருகுகின்றன.",
        '66.3': "திறமையான, மலையில் வாழும் தண்டு களிப்புக்காக நீரில் பிழியப்பட்டது; பருந்து போல அவன் தன் இடத்தில் அமர்ந்தான்.",
        '66.4': "தேவர் விரும்பும், நீரில் கழுவிய, மனிதர் பிழிந்த ஒளிமிக்க சாற்றைப் பசுக்கள் பாலால் இனிமையாக்குகின்றன.",
        '66.5': "ஓட்டுநர் குதிரையைப் போல, வேள்வியில் தேன் சாறான அவனை அமரத்துவத்திற்காக அலங்கரித்தனர்.",
        '66.6': "இந்துவே, காவலுக்காகப் பெருக்கப்பட்ட உன் தேன் சொட்டும் தாரைகளுடன் நீ வடிகட்டியில் அமர்ந்தாய்.",
        '66.7': "கம்பளி மயிர்கள் வழியே, மரப் பாத்திரங்களில் உன் இடத்தில் அமர்ந்தபடி, இந்திரன் பருகப் பெருகு.",
        '66.8': "இந்துவே, அங்கிரசருக்காக மிக இனியவனாகப் பெருகு; விரிவைக் காண்பவனே, நெய்யையும் பாலையும்.",
        '66.9': "அனைத்தும் காணும், நிறுவப்பட்ட இந்தப் பவமானன் பெரும் உறவைத் தூண்டியபடி கவனிக்கப்படுகிறான்.",
        '66.10': "காளைநெறியுடைய இந்தக் காளைப் பவமானன், சாபத்தை அழிப்பவன், வழிபடுவோனுக்குச் செல்வத்தை உண்டாக்குவான்.",
        '66.11': "பசு, குதிரை நிறைந்த, மிக ஒளிமிக்க, பலர் விரும்பும் ஆயிரம் மடங்கு செல்வத்தைப் பெருக்கு.",
        '66.12': "இவன் மனிதரால் சீர்படுத்தப்பட்டுச் சுற்றி ஊற்றப்படுகிறான்; அகலமாக நடப்பவன், திறமையுள்ள ஞானி.",
        '66.13': "ஆயிரம் காவல்களும் நூறு கொடைகளும் உடைய, உலகை அளக்கும் கவியான களிப்பு இந்திரனுக்காகப் பெருகுகிறது.",
        '66.14': "துதியால் பிறந்து, இங்கே போற்றப்பட்ட இந்து கூட்டில் பறவை போல இந்திரனுள் வைக்கப்படுகிறான்.",
        '66.15': "மனிதர் பிழிந்த பவமான ஸோமன் வலிமையுடன் கலங்களில் அமரப் பரிசை நோக்கிப் போல ஓடினான்.",
        '66.16': "ரிஷிகளின் ஏழு துதிகளால், மூன்று முதுகும் மூன்று இருக்கையுமுள்ள தேரில் செல்ல அவனைப் பூட்டுகின்றனர்.",
        '66.17': "பிழிபவர்களே, செல்வத்தை வெல்லும், வேகமான பொன்னிறக் குதிரையான அவனைப் பரிசை நோக்கிச் செல்லத் தூண்டுங்கள்.",
        '66.18': "கலசத்தில் புகுந்தபடி, பிழியப்பட்டு, எல்லா எழில்களையும் நோக்கிப் பெருகியபடி, அவன் பசுக்களிடையே வீரன் போல நிற்கிறான்.",
        '66.19': "இந்துவே, உன் களிப்புக்காக மனிதர் பாலைக் கறக்கின்றனர்; தேவர்கள் தேவர்களுக்காகத் தேனை.",
        '66.20': "தேவர்களுக்காக, தேவர்களிடையே மிகப் புகழ்பெற்ற, மிக இனிய ஸோமத்தை எமக்காக வடிகட்டியில் ஊற்றுங்கள்.",
        '66.21': "பெரும் புகழுக்காகப் போற்றப்பட்ட இந்த ஸோமங்கள் மிக மகிழ்வூட்டுபவனின் தாரையில் பெருக்கப்பட்டன.",
        '66.22': "தூய்மையாகியபடி நீ விருந்துக்காகப் பால் பானங்களையும் வீரியங்களையும் நோக்கிப் பெருகுகிறாய்; பரிசை வெல்பவனே, சுற்றிப் பெருகு.",
        '66.23': "எல்லாப் பக்கங்களிலும் போற்றப்பட்ட, ஜமதக்னியால் போற்றப்பட்ட நீ பசுக்கள் நிறைந்த எல்லா உணவுகளையும் எமக்குப் பெருக்கு.",
        '66.24': "வாக்கில் முதன்மையான ஸோமனே, உன் அற்புதக் காவல்களுடன் எல்லாப் பாக்களையும் நோக்கிப் பெருகு.",
        '66.25': "முதன்மையான நீ கடலின் நீர்களையும் குரல்களையும் தூண்டியபடி பெருகு; அனைத்தையும் இயக்கு.",
        '66.26': "கவியான ஸோமனே, உன் பெருமைக்காக இந்த உலகங்கள் நிலைத்தன; உனக்காக நதிகள் பெருகுகின்றன.",
        '66.27': "உன் இடைவிடாத தாரைகள் வானின் மழை போல ஒளிமிக்க போர்வையை (கம்பளியை) நோக்கிச் செல்கின்றன.",
        '66.28': "வலியவனும் திறமையை நிறைவேற்றுபவனும் விருந்தையே கொடையாகக் கொண்ட தலைவனுமான இந்துவை இந்திரனுக்காகத் தூய்மைப்படுத்துங்கள்.",
        '66.29': "சத்தியனும் கவியுமான பவமான ஸோமன் துதிப்பவனுக்கு வீர வலிமை அளித்தபடி வடிகட்டியில் அமர்ந்தான்.",
        '67.0': "ஸோமனே, வீர வலிமையுடன் ஆயிரம் மடங்கு செல்வத்தைப் பெருக்கு; எம்மிடம் புகழை நிலைநிறுத்து.",
        '67.1': "இந்திரனுக்கு மிக மகிழ்வூட்டும் நீ உணவையும் வீறையும் பெருக்குகிறாய்; கலங்களில் அமர்கிறாய்.",
        '67.2': "இந்திரன், விஷ்ணுவுக்காகப் பிழியப்பட்ட ஸோமன் கலசத்தில் பெருகினான்; வாயுவுக்கு இனியவனாகட்டும்.",
        '67.3': "இந்த வேகமான, பழுப்பு நிற ஸோமங்கள் ருதத்தின் தாரையில் வளைவுகளைக் கடந்து பெருக்கப்பட்டன.",
        '67.4': "இந்திரனை வளர்த்தபடி, நீர்களைக் கடந்தபடி, அனைத்தையும் மேன்மையாக்கியபடி, கொடுக்காதவரை விரட்டியபடி.",
        '67.5': "பிழியப்பட்ட பழுப்பு இந்துக்கள் தம் சொந்த உலகில் இந்திரனை நோக்கிச் சென்றபடி பெருகுகின்றன.",
        '67.6': "எந்தத் தாரையால் நீ சூரியனை ஒளிரச் செய்தாயோ அதனால், மனிதரின் நீர்களைத் தூண்டியபடி பெருகு.",
        '67.7': "பவமானன் மனுவுக்காக, வானிடை வழியே செல்ல, சூரியனின் குதிரை ஏதசனைப் பூட்டினான்.",
        '67.8': "மேலும் சூரியன் செல்ல அந்தப் பத்துப் பொன்னிறக் குதிரைகளைப் பூட்டினான்; இந்து \"இந்திரா\" என்றபடி.",
        '67.9': "துதிகளே, வாயுவுக்காகப் பிழிந்த, இந்திரனுக்கு மகிழ்வூட்டுபவனைக் கம்பளியின் மேல் ஊற்றுங்கள்.",
        '67.10': "பவமான ஸோமனே, தாக்குபவன் அழிக்க முடியாத, வெல்ல முடியாத செல்வத்தை எமக்குக் கண்டு தா.",
        '67.11': "பசு, குதிரை நிறைந்த ஆயிரம் மடங்கு செல்வத்தை நோக்கி, வலிமை, புகழை நோக்கிப் பெருகு.",
        '67.12': "சூரியத் தேவன் போல, கற்களால் பிழியப்பட்ட ஸோமன் கலசத்தில் சாற்றைத் தாங்கியபடி பெருகுகிறான்.",
        '67.13': "இந்த ஒளியோர் ருதத்தின் தாரையில் மேன்மையான இருப்பிடங்களை நோக்கி, பசுக்கள் நிறைந்த பரிசை நோக்கிப் பெருகினர்.",
        '67.14': "வஜ்ரம் ஏந்திய இந்திரனுக்காகப் பிழியப்பட்ட, தயிர் கலந்த ஸோமங்கள் வடிகட்டியைக் கடந்து பெருகின.",
        '67.15': "மிக இனிய ஸோமனே, செல்வத்திற்காக வடிகட்டியில் பெருகு; தேவர்களுக்கு மிக இனிய களிப்பு நீ.",
        '67.16': "நதிகளிலுள்ள பொன்னிறக் குதிரையான, இந்திரனுக்கு மகிழ்வூட்டும் இந்துவை மனிதர் சீர்படுத்துகின்றனர்.",
        '67.17': "ஸோமனே, பொன், குதிரை, வீரருடன் பெருகு; பசுக்கள் நிறைந்த பரிசைக் கொண்டு வா.",
        '67.18': "போட்டியில் போல, பரிசை நாடும், மிக இனியவனை இந்திரனுக்காகக் கம்பளியின் மேல் ஊற்றுங்கள்.",
        '67.19': "காவலை நாடும் ஞானியர் சீர்படுத்தத்தக்க கவியைத் துதிகளால் சீர்படுத்துகின்றனர்; காளை முழங்கியபடி பெருகுகிறது.",
        '67.20': "ருதத்தின் தாரையில், நீரைக் கடக்கும் காளை ஸோமனுக்கு ஞானியர் துதிகளால் ஒன்றாகப் பாடினர்.",
        '67.21': "தேவனே, இடைவிடாது பெருகு; உன் களிப்பு இந்திரனை அடையட்டும்; உன் இயல்பால் வாயுவின் மேல் ஏறு.",
        '67.22': "பவமான ஸோமனே, புகழுக்குரிய செல்வத்தை நீ பொழிகிறாய்; அன்பானவனே, கடலுள் புகு.",
        '67.23': "ஸோமனே, திட்பம் அறிந்த, மகிழ்வூட்டுபவனே, பகைவரை விரட்டியபடி பெருகுகிறாய்; தேவரை எதிர்ப்பவனை விரட்டு.",
        '67.24': "ஒளிமிக்க இந்துக்களான பவமான ஸோமங்கள் எல்லாப் பாக்களையும் நோக்கிப் பெருக்கப்பட்டன.",
        '67.25': "வேகமான, ஒளிரும் பவமான இந்துக்கள் எல்லாப் பகைவரையும் விரட்டியபடி பெருக்கப்பட்டன.",
        '67.26': "பவமானர்கள் வானிலிருந்தும் வானிடையிலிருந்தும் மண்ணின் உச்சியில் பெருக்கப்பட்டனர்.",
        '67.27': "ஸோமனே, இந்துவே, உன் தாரையில் தூய்மையாகியபடி எல்லாப் பகைவரையும் விரட்டு; திறமையுள்ளவனே, அரக்கரை அழி.",
        '67.28': "ஸோமனே, அரக்கரை விரட்டியபடி முழங்கிப் பெருகு; ஒளிமிக்க உயர்ந்த வலிமையைக் கொண்டு வா.",
        '67.29': "ஸோமனே, இந்துவே, வானம்-மண்ணின் செல்வங்களையும் விரும்பத்தக்க அனைத்தையும் எம்மிடம் நிலைநிறுத்து.",
        '68.0': "ஸோமனே, நீ ஒளிமிக்க காளை; தேவனே, காளைநெறியுடைய காளை; காளையாக அறங்களைத் தாங்குகிறாய்.",
        '68.1': "காளையே, உன் வலிமை காளையுடையது; மரமும் காளை, களிப்பும் காளை; உண்மையில், காளையே, நீ காளையே.",
        '68.2': "காளையே, குதிரை போல நீ கனைத்தாய்; இந்துவே, பசுக்களையும் குதிரைகளையும் ஒன்று சேர்; செல்வத்தின் கதவுகளைத் திற.",
        '68.3': "பசு, குதிரை, வீரரை நாடும், ஒளிமிக்க, வேகமான குதிரைகளான ஸோமங்கள் பெருக்கப்பட்டன.",
        '68.4': "ருதத்தை விரும்புவோரால் அலங்கரிக்கப்பட்டு, கைகளில் சீர்படுத்தப்பட்டு அவை கம்பளி வடிகட்டியில் பெருகுகின்றன.",
        '68.5': "அந்த ஸோமங்கள் வழிபடுவோனுக்கு வானம், மண், வானிடையின் எல்லாச் செல்வங்களையும் பெருக்கட்டும்.",
        '68.6': "அனைத்தும் அறிந்த பவமானனே, உன் தாரைகள் சூரியக் கதிர்கள் போலப் பெருக்கப்பட்டன.",
        '68.7': "வானின் மேல் கொடியை அமைத்தபடி, நீ எல்லா வடிவங்களையும் நோக்கிப் பெருகுகிறாய்; ஸோமனே, கடலாகப் பொங்குகிறாய்.",
        '68.8': "தூண்டப்பட்டு, பவமானனே, தாங்குதலில் நீ குரலை எழுப்புகிறாய்; சூரியத் தேவன் போல முழங்கினாய்.",
        '68.9': "கவனமுள்ள, கவிகளின் சிந்தனைக்கு இனிய இந்து, தேரோட்டி குதிரையை விடுவது போலத் தூய்மையானான்.",
        '68.10': "தேவர் நண்பனே, உன் அலை ருதத்தின் இருப்பிடத்தில் அமர்ந்தபடி வடிகட்டியில் பெருகியது.",
        '68.11': "இந்துவே, தேவர்களுக்கு மிக இனிய களிப்பாக, இந்திரன் பருக எமக்காக வடிகட்டியில் பெருகு.",
        '68.12': "ஞானியரால் சீர்படுத்தப்பட்டபடி உணவுக்காகத் தாரையாகப் பெருகு; இந்துவே, உன் ஒளியுடன் பசுக்களிடம் வா.",
        '68.13': "துதியை விரும்புபவனே, தூய்மையாகியபடி மக்களுக்கு விரிவையும் வீறையும் அமை; பொன்னிறத்தானே, பால் கலவையை உண்டாக்கு.",
        '68.14': "தேவர் விருந்துக்காகத் தூய்மையாகியபடி, ஒளிர்ந்தபடி, குதிரைகளால் செலுத்தப்பட்டு இந்திரனின் இருப்பிடத்திற்குச் செல்.",
        '68.15': "தூண்டப்பட்ட வேகமான இந்துக்கள் துதியால் விரைவுபட்டுக் கடலை நோக்கிப் பெருக்கப்பட்டன.",
        '68.16': "மனிதரால் சீர்படுத்தப்பட்ட இந்துக்கள் இயல்பாகக் கடலுக்கு, ருதத்தின் இருப்பிடத்திற்குச் சென்றன.",
        '68.17': "எம்மை நேசித்தபடி, உன் வலிமையால் எல்லாச் செல்வங்களுடன் எம்மிடம் வா; வீரருடன் கூடிய எம் அடைக்கலத்தைக் காப்பாற்று.",
        '68.18': "பாடகரால் தன் இடத்தில் பூட்டப்பட்டு, கடலில் வைக்கப்படும்போது சுமக்கும் குதிரை கனைக்கிறது.",
        '68.19': "வேகமானவன் ருதத்தின் பொன் இருப்பிடத்தில் அமரும்போது, சிந்தனையற்றோரைப் பின்னே விடுகிறான்.",
        '68.20': "விரும்புவோர் போற்றினர்; கவனமுள்ளோர் வழிபடுகின்றனர்; கவனமற்றோர் மூழ்குகின்றனர்.",
        '68.21': "இந்துவே, மருத்துகளுடன் கூடிய இந்திரனுக்காக, ருதத்தின் இருப்பிடத்தில் அமர மிக இனியவனாகப் பெருகு.",
        '68.22': "சொல்லறிந்த ஞானியரான அறிஞர் உன்னை அலங்கரிக்கின்றனர்; மனிதர் உன்னைச் சீர்படுத்துகின்றனர்.",
        '68.23': "கவியே, பவமானனே, மித்ரன், அர்யமன், வருணன், மருத்துகள் உன் சாற்றைப் பருகுகின்றனர்.",
        '68.24': "ஸோமனே, தூய்மையாகியபடி நீ ஞானமுள்ள குரலை எழுப்புகிறாய்; இந்துவே, ஆயிரத்தைத் தாங்கும் குரலை.",
        '68.25': "மேலும், ஸோம இந்துவே, தூய்மையாகியபடி ஆயிரத்தைத் தாங்கும், வேள்வியை நாடும் குரலைக் கொண்டு வா.",
        '68.26': "இந்துவே, இம்மக்களால் பெரிதும் அழைக்கப்பட்டவனே, தூய்மையாகியபடி, அன்பானவனே, கடலுள் புகு.",
        '68.27': "மின்னும் ஒளியுடன், எதிரொலிக்கும் எழிலுடன் பால் கலந்த ஒளிமிக்க ஸோமங்கள்.",
        '68.28': "தூண்டப்பட்டு, ஓட்டுநரால் செலுத்தப்பட்டு, வெல்ல அமர்ந்தோர் போலக் குதிரை பரிசுக்கு வந்தது.",
        '68.29': "ஸோமனே, சரியாக, எம் நலத்திற்காக, வானுடன் இணைந்த கவியே, நாங்கள் காணச் சூரியனாகப் பெருகு.",
        '69.0': "ஒளிமிக்க சகோதரிகள், உறவினர், பெருமையை நாடியபடி சூரியன் போன்ற தலைவனான பெரும் இந்துவைத் தூண்டுகின்றனர்.",
        '69.1': "பவமானனே, ஒளிமேல் ஒளியுடன், தேவர்களிடமிருந்து தேவனாக, எல்லாச் செல்வங்களிலும் புகு.",
        '69.2': "பவமானனே, தேவர்களுக்கு நல்ல துதி, மழை, வழிபாடு ஆகியவற்றைப் பெருக்கு; ஊட்டத்திற்காக மிகுந்த உணவைப் பெருக்கு.",
        '69.3': "உன் ஒளியால் நீ காளை; பவமானனே, சிந்தனையுள்ள நாங்கள் ஒளிமிக்க உன்னை அழைக்கிறோம்.",
        '69.4': "நல்ல ஆயுதமுள்ளவனே, மகிழ்ந்தபடி வீர வலிமையைப் பெருக்கு; இந்துவே, இங்கே வா.",
        '69.5': "நீருடன் ஊற்றப்பட்டு, கைகளில் சீர்படுத்தப்படும்போது, நீ மரப் பாத்திரத்தில் உன் இடத்தை அடைகிறாய்.",
        '69.6': "வ்யச்வனைப் போலப் பெரியவனான, ஆயிரம் கண்ணுடைய பவமான ஸோமனுக்குப் பாடுங்கள்.",
        '69.7': "எவனுடைய தேன் சொட்டும் நிறமான பொன்னிற இந்துவை இந்திரன் பருகக் கற்களால் தூண்டுகிறார்களோ.",
        '69.8': "எல்லாச் செல்வங்களையும் வென்ற குதிரையான உன் நட்பை நாங்கள் தேர்ந்தெடுக்கிறோம்.",
        '69.9': "காளையாக, மருத்துகளுடன் கூடிய இந்திரனுக்கு மகிழ்வூட்டுபவனாக, வலிமையால் அனைத்தையும் தாங்கியபடி தாரையாகப் பெருகு.",
        '69.10': "இரு பலகைகளைத் தாங்கும், ஒளியைக் காணும் பவமானனான, குதிரையான உன்னைப் போட்டிகளில் தூண்டுகிறேன்.",
        '69.11': "இந்த ஞானத் துதியால் கவனிக்கப்பட்டு, பொன்னிறத்தானே, தாரையாகப் பெருகு; போட்டிகளில் உன் துணைவனைத் தூண்டு.",
        '69.12': "இந்துவே, அனைவருக்கும் அழகியவனே, எமக்குப் பெரும் உணவைப் பெருக்கு; ஸோமனே, எமக்கு வழி காண்பவனே.",
        '69.13': "இந்துவே, கலசங்கள் தாரைகளாலும் வலிமையாலும் உனக்காக ஒலித்தன; இந்திரன் பருகப் புகு.",
        '69.14': "எவனுடைய களிப்பூட்டும், தீவிரச் சாற்றைக் கற்களால் கறக்கிறார்களோ அந்த நீ, செருக்குடையோரை அழிப்பவனே, பெருகு.",
        '69.15': "மன்னனான பவமானன் மனுவுக்காக அறிவுகளுடன், வானிடை வழியே பயணிக்கச் செல்கிறான்.",
        '69.16': "இந்துவே, காவலுக்காக எமக்கு நூறு பசுக்களையும், கால்நடைப் பெருக்கத்தையும், நல்ல குதிரைகளையும், நற்பேற்றுக் கொடையையும் கொண்டு வா.",
        '69.17': "ஸோமனே, தேவர் விருந்துக்காகப் பிழியப்பட்ட நீ ஒளிக்காக வடிவம் போல வலிமையையும் வேகத்தையும் எமக்குக் கொண்டு வா.",
        '69.18': "மிக ஒளிமிக்க ஸோமனே, மரப் பாத்திரங்களை நோக்கி முழங்கியபடி, பருந்து போல உன் இடத்தில் அமர்ந்தபடி பெருகு.",
        '69.19': "நீர்களை வெல்லும் ஸோமன் இந்திரன், வாயு, வருணன், மருத்துகளுக்காகவும் விஷ்ணுவுக்காகவும் பெருகுகிறான்.",
        '69.20': "எம் குழந்தைகளுக்கு உணவு அளித்தபடி, ஸோமனே, எல்லாப் பக்கங்களிலிருந்தும் ஆயிரம் மடங்கு செல்வத்தை எமக்குப் பெருக்கு.",
        '69.21': "தொலைவில், அருகில், அல்லது அங்கே சர்யணாவதத்தில் பிழியப்பட்ட ஸோமங்கள்,",
        '69.22': "செயலூக்கமுள்ள ஆர்ஜீகரிடையே, குடியிருப்புகளிடையே, அல்லது ஐந்து மக்களிடையே உள்ளவை,",
        '69.23': "பிழியப்படும் அந்தத் தெய்வீக இந்துக்கள் வானிலிருந்து மழையையும் வீர வலிமையையும் எமக்குப் பெருக்கட்டும்.",
        '69.24': "ஜமதக்னியால் போற்றப்பட்ட அழகிய பொன்னிறத்தான் பசுத்தோலின் மேல் தூண்டப்பட்டுப் பெருகுகிறான்.",
        '69.25': "வீறைத் தூண்டும் ஒளியோர் குதிரைகள் போலத் தூண்டப்பட்டு, கலக்கப்பட்டு நீரில் சீர்படுத்தப்படுகின்றனர்.",
        '69.26': "பிழிதலில் இருப்போர் தேவ சேவைக்காக உன்னைத் தூண்டினர்; இந்த ஒளியுடன் பெருகு.",
        '69.27': "இன்பம் தரும், சுமக்கும், காக்கும், பலர் விரும்பும் உன் திறமையை இன்று நாங்கள் தேர்ந்தெடுக்கிறோம்.",
        '69.28': "மகிழ்வூட்டுபவனை, சிறந்தவனை, ஞானியை, அறிஞனை, காப்பவனை, பலர் விரும்புபவனை.",
        '69.29': "திறமையுள்ளவனே, எம் உடல்களுக்காகச் செல்வத்தையும் நல்லறிவையும்; காப்பவனை, பலர் விரும்புபவனை.",
        '70.0': "அனைத்தும் காண்பவனே, எல்லாப் பாக்களையும் நோக்கிப் பெருகு; நண்பர்களால் போற்றத்தக்க நண்பன் நீ.",
        '70.1': "பவமான ஸோமனே, எம்மை நோக்கி நிற்கும் உன் அந்த இரு இருப்பிடங்களால் நீ அனைத்தையும் ஆள்கிறாய்.",
        '70.2': "பவமான ஸோமனே, கவியே, பருவங்களுடன் எல்லாப் பக்கங்களிலும் உன் இருப்பிடங்களைச் சுற்றி நீ இருக்கிறாய்.",
        '70.3': "உணவைப் பிறப்பித்தபடி, விரும்பத்தக்க அனைத்தையும் நோக்கிப் பெருகு; நண்பர்களுக்கு நண்பனாக, காவலுக்காக.",
        '70.4': "ஸோமனே, உன் ஒளிமிக்க கதிர்கள் தம் வடிவங்களால் வானின் முதுகில் வடிகட்டியை விரிக்கின்றன.",
        '70.5': "ஸோமனே, இந்த ஏழு நதிகள் உன் கட்டளைப்படி பெருகுகின்றன; உனக்காகப் பசுக்கள் ஓடுகின்றன.",
        '70.6': "ஸோமனே, பிழியப்பட்டு, இந்திரனுக்கு மகிழ்வூட்டுபவனாக, அழியாத புகழைத் தாங்கியபடி தாரையாகச் செல்.",
        '70.7': "ஏழு சகோதரிகள் துதிகளால் உன்னைத் தூண்டியபடி, விவஸ்வானின் ஓட்டத்தில் ஞானியான உன்னைப் பாடினர்.",
        '70.8': "பாடுவோனான நீ மரத்தில் அலங்கரிக்கப்படும்போது, கன்னியர் கம்பளியின் மேல், உயர்ந்த இடத்தில் உன்னைச் சீர்படுத்துகின்றனர்.",
        '70.9': "கவியே, குதிரையான பவமானனே, புகழை நாடும் பந்தயக் குதிரைகள் போல உன் தாரைகள் பெருக்கப்பட்டன.",
        '70.10': "தேன் சொட்டும் கலத்தை நோக்கிக் கம்பளி வடிகட்டியின் மேல் அவை பெருக்கப்பட்டன; துதிகள் ஒலித்தன.",
        '70.11': "பசுக்கள் தொழுவத்திற்குச் செல்வது போல இந்துக்கள் கடலுக்கு, ருதத்தின் இருப்பிடத்திற்குச் சென்றன.",
        '70.12': "இந்துவே, நீ பாலால் போர்த்தப்படும்போது, எம் பெரும் மகிழ்ச்சிக்காக நீர்களான நதிகள் பெருகுகின்றன.",
        '70.13': "இந்துவே, உன் நட்பில், வழிபட விரும்பியபடி, உன்னால் காக்கப்பட்டு, நாங்கள் உன் நட்பை விரும்புகிறோம்.",
        '70.14': "ஸோமனே, பசுக்களுக்கான பெரும் தேடலுக்காக, மனிதரைக் காண்பவனுக்காகப் பெருகு; இந்திரனின் வயிற்றுள் புகு.",
        '70.15': "ஸோமனே, நீ பெரியவன், மூத்தவன்; இந்துவே, வலியோரில் மிக வலியவன்; போரிட்டு நீ எப்போதும் வென்றாய்.",
        '70.16': "வலியோரைவிட வலியவனும், வீரரைவிட வீரனும், கொடையாளரைவிடக் கொடையாளனுமான நீ.",
        '70.17': "ஸோமனே, சந்ததியையும் உடல்களையும் பெறுவதில் நீயே சூரியன்; நட்புக்காக உன்னைத் தேர்கிறோம், கூட்டுறவுக்காகத் தேர்கிறோம்.",
        '70.18': "அக்னியே, நீ ஆயுளைத் தூய்மைப்படுத்துகிறாய்; எமக்கு வீறையும் உணவையும் கொண்டு வா; தீப்பேற்றைத் தொலைவில் விரட்டு.",
        '70.19': "அக்னியே ரிஷி, பவமானன், ஐந்து மக்களுக்குரியவன், புரோகிதன்; பெரும் இல்லமுடைய அவனை நாங்கள் வேண்டுகிறோம்.",
        '70.20': "செயலில் திறமையுள்ள அக்னியே, எமக்காக ஒளியையும் வீர வலிமையையும் தூய்மைப்படுத்து, என்னுள் செல்வத்தையும் செழிப்பையும் வைத்தபடி.",
        '70.21': "பவமானன் பகைவரைக் கடந்து நல்ல துதியை நோக்கிப் பெருகுகிறான், சூரியன் போல அனைவருக்கும் அழகியவனாக.",
        '70.22': "மனிதரால் சீர்படுத்தப்பட்ட, உணவு நிறைந்த, உணவுக்காக வைக்கப்பட்ட இந்து தொலைநோக்குடைய பந்தயக் குதிரை.",
        '70.23': "பவமானன் ருதத்தையும் பெரும் ஒளிமிக்க சுடரையும் பிறப்பித்தான், கரிய இருள்களை அழித்தபடி.",
        '70.24': "அழிக்கும் பொன்னிறப் பவமானனிடமிருந்து ஒளிமிக்க, விரைவான, வேகச் சுடருடைய தாரைகள் பெருக்கப்பட்டன.",
        '70.25': "பவமானன் தேரோட்டிகளில் சிறந்தவன், ஒளியோரில் மிகப் போற்றப்பட்டவன், பொன்னொளியன், மருத்துகளே அவன் கணம்.",
        '70.26': "பரிசு வெல்வோரில் சிறந்த பவமானன் கதிர்களால் பரவினான், துதிப்பவனுக்கு வீர வலிமை அளித்தபடி.",
        '70.27': "பிழியப்பட்ட இந்து கம்பளி வடிகட்டியைக் கடந்து பெருகினான்; தூய்மையாகியபடி இந்து இந்திரனை நோக்கிச் செல்கிறான்.",
        '70.28': "இந்த ஸோமன் கற்களுடன் பசுத்தோலின் மேல் விளையாடுகிறான், இந்திரனைக் களிப்புக்கு அழைத்தபடி.",
        '70.29': "பவமானனே, வானிலிருந்து கொண்டு வந்த உன் அந்த ஒளிமிக்க சாற்றால், நாங்கள் வாழ எம்மீது அருள் புரி.",
        '71.0': "ஸோமனே, தாரைகளில் பெருகும், மகிழ்வூட்டும், வேள்வியில் மிக வலியவனான நீ செல்வம் அளித்தபடி பெருகு.",
        '71.1': "பிழியப்பட்ட, மனிதரை மகிழ்விக்கும், ஓடும், மிக மகிழ்வூட்டும் நீ உன் சாற்றால் இந்திரனுக்குக் கொடையாளன்.",
        '71.2': "கற்களால் பிழியப்பட்ட நீ முழங்கியபடி பெருகு; ஒளிமிக்க உயர்ந்த வலிமையைக் கொண்டு வா.",
        '71.3': "தூண்டப்பட்ட இந்து கம்பளி வடிகட்டியைக் கடந்து பெருகுகிறான்; பொன்னிறத்தான் பரிசுக்காக முழங்கினான்.",
        '71.4': "இந்துவே, ஸோமனே, நீ கம்பளி வழியே புகழ், நற்பேறு, பசுக்கள் நிறைந்த பரிசுகளை நோக்கிப் பெருகுகிறாய்.",
        '71.5': "இந்துவே, ஸோமனே, நூறு பசுக்களுடைய, பசு, குதிரை நிறைந்த ஆயிரம் மடங்கு செல்வத்தை எமக்குக் கொண்டு வா.",
        '71.6': "வேகமான பவமான இந்துக்கள் வடிகட்டி வழியே தம் பாதைகளில் இந்திரனை அடைந்தன.",
        '71.7': "உயர்ந்த ஸோமச் சாறான, இந்திரனுக்குத் தொன்மையான இந்து உயிர்களுக்கு ஆயுளாகப் பெருகுகிறான்.",
        '71.8': "ஒளியோர் சூரியன் போன்ற, தேன் சொட்டும் பவமானனைத் தூண்டுகின்றனர்; துதியால் அவனைப் பாடினர்.",
        '71.9': "ஆடுகளையே குதிரைகளாகக் கொண்ட பூஷன் ஒவ்வொரு பயணத்திலும் எம் காவலன்; கன்னியரில் எமக்குப் பங்கு தரட்டும்.",
        '71.10': "சடைமுடியானுக்காக (பூஷனுக்காக) இந்த ஸோமன் நெய் போலத் தேனைப் பெருக்குகிறான்; கன்னியரில் எமக்குப் பங்கு தரட்டும்.",
        '71.11': "ஒளியோனே, உனக்காகப் பிழியப்பட்ட இது நெய் போலத் தூய்மையாகப் பெருகுகிறது; கன்னியரில் எமக்குப் பங்கு தரட்டும்.",
        '71.12': "கவிகளின் சொல்லைப் பிறப்பிப்பவனே, ஸோமனே, தாரையாகப் பெருகு; தேவர்களிடையே நீ ரத்தினம் அளிப்பவன்.",
        '71.13': "அவன் கலசங்களுக்குள் ஓடுகிறான்; பருந்து போலத் தன் கவசத்தில் மூழ்குகிறான், மரப் பாத்திரங்களை நோக்கி முழங்கியபடி.",
        '71.14': "ஸோமனே, பிழியப்பட்ட உன் சாறு கலசத்தில் பெருக்கப்பட்டது; வேகமான பருந்து போலப் பெருகுகிறது.",
        '71.15': "ஸோமனே, மிக இனியவனாக, இந்திரனை மகிழ்வித்தபடி பெருகு.",
        '71.16': "பரிசுக்காக ஓடும் தேர்கள் போல அவை தேவர் விருந்துக்காகப் பெருக்கப்பட்டன.",
        '71.17': "பிழியப்பட்ட, மிக மகிழ்வூட்டும் அந்த ஒளிமிக்க ஸோமங்கள் வாயுவுக்காகப் பெருக்கப்பட்டன.",
        '71.18': "கல்லால் அடிக்கப்பட்டு, போற்றப்பட்டு, ஸோமனே, துதிப்பவனுக்கு வீர வலிமை அளித்தபடி நீ வடிகட்டிக்குச் செல்கிறாய்.",
        '71.19': "அடிக்கப்பட்ட, போற்றப்பட்ட இந்த அரக்கரை அழிப்பவன் கம்பளி வடிகட்டி வழியே மூழ்கிச் செல்கிறான்.",
        '71.20': "அருகிலோ தொலைவிலோ, இங்கே என்னை எந்த அச்சம் பற்றுகிறதோ, பவமானனே, அதை அழி.",
        '71.21': "அனைத்தும் காணும் பவமானன் இன்று தன் வடிகட்டியால் எம்மைத் தூய்மைப்படுத்தட்டும்; தூய்மையாக்குபவனான அவன் எம்மைப் புனிதமாக்கட்டும்.",
        '71.22': "அக்னியே, உன் சுடருக்குள் விரிந்த வடிகட்டியால் எங்கள் வேண்டுதலைத் தூய்மைப்படுத்து.",
        '71.23': "அக்னியே, உன் சுடர்மிக்க வடிகட்டியால் எம்மைத் தூய்மைப்படுத்து; மந்திரத் தூண்டல்களால் எம்மைத் தூய்மைப்படுத்து.",
        '71.24': "சவித்ரு தேவனே, வடிகட்டியாலும் உன் தூண்டலாலும் எல்லாப் பக்கங்களிலும் என்னைத் தூய்மைப்படுத்து.",
        '71.25': "சவித்ரு தேவனே, ஸோமனே, அக்னியே, உங்கள் மூன்று உயர்ந்த இருப்பிடங்களாலும் ஆற்றல்களாலும் எம்மைத் தூய்மைப்படுத்துங்கள்.",
        '71.26': "தேவ மக்கள் என்னைத் தூய்மைப்படுத்தட்டும்; வசுக்கள் அறிவால் தூய்மைப்படுத்தட்டும்; விச்வேதேவர்களே, என்னைத் தூய்மைப்படுத்துங்கள்; ஜாதவேதனே, என்னைத் தூய்மைப்படுத்து.",
        '71.27': "ஸோமனே, உன் எல்லாத் தண்டுகளுடனும் பெருகு, பாய்; தேவர்களுக்கு உயர்ந்த அவி நீ.",
        '71.28': "ஆஹுதிகளால் வளரும், பெரிதும் போற்றப்பட்ட அன்பான இளைஞனிடம் வணக்கத்தைச் சுமந்து நாங்கள் வந்தோம்.",
        '71.29': "பகைவனின் கோடரி அழிந்தது; ஸோமதேவனே, அதற்காகப் பெருகு; எலிக்கு எதிராகவும், ஸோமதேவனே.",
        '71.30': "ரிஷிகள் சேர்த்த சாரமான பாவமானீ ருக்குகளை ஓதுபவன் மாதரிச்வனால் சுவையூட்டப்பட்ட, தூய்மையான எல்லா உணவையும் உண்கிறான்.",
        '71.31': "ரிஷிகள் சேர்த்த சாரமான பாவமானீ ருக்குகளை ஓதுபவனுக்குச் சரஸ்வதி பால், நெய், தேன், நீர் ஆகியவற்றைச் சுரக்கிறாள்.",
        '72.0': "பாவமானீ ருக்குகள் நலம் தருவன; நிறைவாகச் சுரப்பன, நெய் சொட்டுவன. ரிஷிகள் சேர்த்த சாரம் வேதம் அறிந்தோரில் வைக்கப்பட்ட அமுதம்.",
        '72.1': "பாவமானீ ருக்குகள் இவ்வுலகையும் மறுவுலகையும் எங்களுக்கு அருளட்டும்; தேவர்கள் சேர்த்த அத்தேவியர் எங்கள் விருப்பங்களை நிறைவேற்றட்டும்.",
        '72.2': "தவறாகச் செய்த யஜ்ஞம், தவறாகப் படித்த கல்வி, அறியாமையால் செய்த பாவம், தகுதியற்றவர்க்குச் செய்த யாஜனம் — இவை அனைத்தையும் நான் பவமானீ மந்திரங்களால் தூய்மையாக்குகிறேன். (ரிக்வேத கிலம் 3.10.8)",
        '72.3': "பரப்ரஹ்மமான பவமானத்தை ஓதும் அறிஞர்கள் ஏழு பிறவிகள் செல்வமிக்க வேதபாரங்கதரான விப்ரர்களாக ஆவர். (ரிக்வேத கிலம் 3.10.18)",
        '73.0': "அக்னியைத் திருப்தி செய்கிறேன்; சந்திரனை; பாரதியை; வாயுவை; ஹரியைத் திருப்தி செய்கிறேன். (பால், தேன், இளநீரால் ஐந்து பவமான தேவதைகளுக்குத் தர்ப்பணம்.)",
        '74.0': "ஸ்விஷ்டக்ருத் முதல் ஸமர்ப்பணம் வரையிலான உத்தராங்கத்தை (“ஹோமவிதி — பூர்வாங்க உத்தராங்கம்” பாடத்திலிருந்து) செய்து…",
        '74.1': "இந்த பவமான ஹோமத்தால் யஜ்ஞபுருஷனின் அந்தர்யாமியான பாரதீரமண முக்யப்ராணாந்தர்கதரான ஹரிணீபதி ஸ்ரீபரசுராமர் மகிழட்டும். ஸ்ரீகிருஷ்ணார்ப்பணமஸ்து.",
        '75.0': "தூபம், தீபம், நைவேத்யம், நீராஜனம் (ஆரத்தி), மந்திரபுஷ்பம், ப்ரதக்ஷிண நமஸ்காரங்களை ஸமர்ப்பிக்கிறேன்.",
        '75.1': "சுப காரியங்களுக்கு மீண்டும் வர உங்களை உங்கள் இடத்திற்குத் திரும்ப ப்ரதிஷ்டை செய்கிறேன். (கலச தேவதைகளின் உத்வாஸனம்.)",
      },
    },
  },
};
